def precise_sleep(seconds):
    """高精度延迟函数，使用Windows多媒体计时器实现微秒级精度"""
    if seconds <= 0:
        return
    
    try:
        import ctypes
        kernel32 = ctypes.windll.kernel32
        timer_resolution = 1
        
        old_resolution = ctypes.c_uint()
        kernel32.timeBeginPeriod(timer_resolution)
        
        start_time = time.perf_counter()
        remaining = seconds
        
        while remaining > 0:
            if remaining > 0.02:
                time.sleep(remaining / 2)
            else:
                kernel32.Sleep(int(remaining * 1000))
            elapsed = time.perf_counter() - start_time
            remaining = seconds - elapsed
        
        kernel32.timeEndPeriod(timer_resolution)
    except:
        time.sleep(seconds)

# Windows API 按键检测（替代 keyboard 模块）
_VK_MAP = {
    'space': 0x20, 'enter': 0x0D, 'esc': 0x1B, 'escape': 0x1B,
    'tab': 0x09, 'backspace': 0x08,
    'up': 0x26, 'down': 0x28, 'left': 0x25, 'right': 0x27,
    'insert': 0x2D, 'delete': 0x2E,
    'home': 0x24, 'end': 0x23,
    'page up': 0x21, 'page down': 0x22, 'pageup': 0x21, 'pagedown': 0x22,
    'caps lock': 0x14, 'capslock': 0x14,
    'num lock': 0x90, 'numlock': 0x90,
    'scroll lock': 0x91, 'scrolllock': 0x91,
    'print screen': 0x2C, 'printscreen': 0x2C, 'prtsc': 0x2C,
    'pause': 0x13,
    'shift': 0x10, 'left shift': 0xA0, 'right shift': 0xA1,
    'ctrl': 0x11, 'left ctrl': 0xA2, 'right ctrl': 0xA3, 'control': 0x11,
    'alt': 0x12, 'left alt': 0xA4, 'right alt': 0xA5, 'menu': 0x12,
    'left windows': 0x5B, 'right windows': 0x5C, 'win': 0x5B, 'windows': 0x5B,
}
for _i in range(1, 13):
    _VK_MAP[f'f{_i}'] = 0x6F + _i  # F1-F12: 0x70-0x7B

def _key_name_to_vk(key_str):
    """将按键名称字符串转换为 Windows 虚拟键码"""
    if not key_str:
        return None
    key_str = key_str.strip().lower()
    if key_str in _VK_MAP:
        return _VK_MAP[key_str]
    if len(key_str) == 1:
        # 字母或数字键
        if key_str.isalpha():
            return ord(key_str.upper())
        if key_str.isdigit():
            return ord(key_str)
    return None

def _is_key_pressed_win(key_str):
    """使用 Windows API 检测按键是否按下（替代 keyboard.is_pressed）"""
    vk = _key_name_to_vk(key_str)
    if vk is None:
        return False
    try:
        # GetAsyncKeyState 返回 short，最高位为 1 表示按下
        return bool(ctypes.windll.user32.GetAsyncKeyState(vk) & 0x8000)
    except Exception:
        return False

class _KeyboardCompatModule:
    """keyboard 模块兼容层，使用 Windows API + pynput 实现常用功能"""

    def __init__(self):
        self._pynput_kb = None

    def _get_pynput(self):
        if self._pynput_kb is None:
            try:
                from pynput.keyboard import Controller
                self._pynput_kb = Controller()
            except Exception:
                self._pynput_kb = None
        return self._pynput_kb

    def _normalize_key(self, key_str):
        """将 keyboard 模块风格的键名标准化"""
        if not key_str:
            return key_str
        return key_str.lower().strip() if isinstance(key_str, str) else key_str

    def is_pressed(self, key):
        """检测按键是否按下"""
        key_lower = self._normalize_key(key)
        return _is_key_pressed_win(key_lower)

    def press(self, key):
        """按下按键"""
        kb = self._get_pynput()
        if kb:
            from pynput.keyboard import Key, KeyCode
            key_lower = self._normalize_key(key)
            vk = _key_name_to_vk(key_lower)
            if vk is not None:
                kb.press(KeyCode.from_vk(vk))
            else:
                kb.press(key)

    def release(self, key):
        """释放按键"""
        kb = self._get_pynput()
        if kb:
            from pynput.keyboard import Key, KeyCode
            key_lower = self._normalize_key(key)
            vk = _key_name_to_vk(key_lower)
            if vk is not None:
                kb.release(KeyCode.from_vk(vk))
            else:
                kb.release(key)

    def send(self, key, do_press=True, do_release=True):
        """发送按键（按下并释放）"""
        if do_press:
            self.press(key)
        if do_release:
            self.release(key)

    def press_and_release(self, key):
        """按下并释放按键"""
        self.send(key)

    def write(self, text, delay=0.001, restore_state_after=True):
        """输入文本"""
        kb = self._get_pynput()
        if kb:
            kb.type(text)

    def wait(self, hotkey=None, suppress=False, trigger_on_release=False):
        """等待按键按下"""
        if hotkey is None:
            return
        import time as _time
        while True:
            if self.is_pressed(hotkey):
                break
            _time.sleep(0.02)

    def add_hotkey(self, hotkey, callback, args=(), suppress=False, timeout=1, trigger_on_release=False):
        """注册热键（简化实现，不做实际监听）"""
        return None

    def remove_hotkey(self, hotkey_or_handle):
        """移除热键"""
        pass

    def clear_hotkeys(self):
        """清除所有热键"""
        pass

    def record(self, until='escape', suppress=False):
        """录制按键（简化实现）"""
        return []

    def play(self, events, speed_factor=1.0):
        """播放录制的按键"""
        pass

def _inject_keyboard_compat():
    """将 keyboard 兼容模块注入 sys.modules，使用户脚本 import keyboard 不报错"""
    import sys as _sys
    try:
        # 先尝试真实导入，如果已安装就用真实的
        import keyboard as _real_kb
        return _real_kb
    except ImportError:
        # 没有安装，注入兼容层
        compat = _KeyboardCompatModule()
        _sys.modules['keyboard'] = compat
        return compat

