# === kmbox Net 键鼠盒子支持（联网盒子，通过网络执行键鼠操作）===
# kmNet.pyd 是 Debug 版本编译的，依赖 Debug 版本的 VC++ 运行时库
# 这些 DLL 需要打包到程序中，否则在其他电脑上无法加载 kmNet
def _setup_kmnet_dependencies():
    """设置 kmNet 的 DLL 搜索路径并预加载依赖的 DLL"""
    _exe_dir = os.path.dirname(sys.executable)
    _search_dirs = []
    # 打包后：搜索 _MEIPASS（单文件模式）和 _internal（目录模式）
    if getattr(sys, 'frozen', False):
        _meipass = getattr(sys, '_MEIPASS', None)
        _internal_dir = os.path.join(_exe_dir, '_internal')
        for _d in [_meipass, _internal_dir, _exe_dir]:
            if _d and os.path.isdir(_d):
                _search_dirs.append(_d)
                # 添加到 PATH 环境变量
                try:
                    os.environ['PATH'] = _d + os.pathsep + os.environ.get('PATH', '')
                except Exception:
                    pass
                # 添加到 Python DLL 搜索目录
                try:
                    os.add_dll_directory(_d)
                except Exception:
                    pass
    else:
        # 开发模式：搜索脚本目录
        _search_dirs.append(os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else os.getcwd())

    # 预加载 kmNet 依赖的 DLL（Debug 版本优先）
    # 注意：kmNet.pyd 是 Debug 版本，需要 msvcp140d.dll、vcruntime140d.dll 等
    _dll_names = [
        'msvcp140d.dll', 'vcruntime140d.dll', 'vcruntime140_1d.dll', 'ucrtbased.dll',
        'VCRUNTIME140.dll', 'VCRUNTIME140_1.dll', 'MSVCP140.dll', 'MSVCP140_1.dll', 'MSVCP140_2.dll',
        'ucrtbase.dll', 'WS2_32.dll', 'DNSAPI.dll', 'IPHLPAPI.dll',
        'secur32.dll', 'crypt32.dll', 'wldap32.dll',
    ]
    try:
        import ctypes
        for _dll_name in _dll_names:
            for _d in _search_dirs:
                _dll_path = os.path.join(_d, _dll_name)
                if os.path.exists(_dll_path):
                    try:
                        ctypes.CDLL(_dll_path)
                    except Exception:
                        pass
                    break
    except Exception:
        pass

    return _search_dirs

_kmnet_search_dirs = _setup_kmnet_dependencies()

# 优雅导入 kmNet 模块：尝试多个路径，失败则降级（不影响程序启动）
_KMNET_AVAILABLE = False
_kmNet = None
_kmnet_load_errors = []
try:
    import kmNet as _kmNet
    _KMNET_AVAILABLE = True
except Exception as _e:
    _kmnet_load_errors.append(f"直接导入失败: {_e}")
    import importlib.util, ctypes, ctypes.wintypes
    _base_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else os.getcwd()
    _search_dirs = list(_kmnet_search_dirs)
    _search_dirs.extend([
        _base_dir,
        os.path.join(_base_dir, '发布文件', 'python版本demo'),
    ])
    _is_frozen = getattr(sys, 'frozen', False)
    _kmnet_load_errors.append(f"是否打包: {_is_frozen}")
    _kmnet_load_errors.append(f"脚本目录: {_base_dir}")
    _kmnet_load_errors.append(f"搜索路径: {_search_dirs}")
    _original_cwd = os.getcwd()
    for _d in _search_dirs:
        if _d and os.path.isdir(_d):
            if _d not in sys.path:
                sys.path.insert(0, _d)
            _pyd_path = os.path.join(_d, 'kmNet.cp310-win_amd64.pyd')
            _pyd_exists = os.path.exists(_pyd_path)
            _kmnet_load_errors.append(f"检查 {_pyd_path}: {'存在' if _pyd_exists else '不存在'}")
            if _pyd_exists:
                try:
                    os.chdir(_d)
                    _spec = importlib.util.spec_from_file_location('kmNet', _pyd_path)
                    _kmNet = importlib.util.module_from_spec(_spec)
                    _spec.loader.exec_module(_kmNet)
                    _KMNET_AVAILABLE = True
                    _kmnet_load_errors.append(f"成功加载: {_pyd_path}")
                    os.chdir(_original_cwd)
                    break
                except Exception as _ie:
                    os.chdir(_original_cwd)
                    _kmnet_load_errors.append(f"加载失败 {_pyd_path}: {_ie}")
                    try:
                        os.chdir(_d)
                        ctypes.CDLL(_pyd_path)
                        _kmnet_load_errors.append(f"ctypes.CDLL尝试成功")
                        os.chdir(_original_cwd)
                    except Exception as _ce:
                        os.chdir(_original_cwd)
                        _win_error = ctypes.GetLastError()
                        _kmnet_load_errors.append(f"ctypes.CDLL失败，Windows错误码: {_win_error}")
                        try:
                            _kernel32 = ctypes.WinDLL('kernel32', use_last_error=True)
                            _kernel32.FormatMessageW.argtypes = [ctypes.wintypes.DWORD, ctypes.wintypes.LPCVOID, ctypes.wintypes.DWORD, ctypes.wintypes.DWORD, ctypes.wintypes.LPWSTR, ctypes.wintypes.DWORD, ctypes.wintypes.LPVOID]
                            _kernel32.FormatMessageW.restype = ctypes.wintypes.DWORD
                            _buf = ctypes.create_unicode_buffer(512)
                            _kernel32.FormatMessageW(0x1200, None, _win_error, 0, _buf, 512, None)
                            _kmnet_load_errors.append(f"Windows错误描述: {_buf.value.strip()}")
                        except Exception as _fe:
                            _kmnet_load_errors.append(f"获取错误描述失败: {_fe}")
            _pyd_path2 = os.path.join(_d, 'kmNet.pyd')
            _pyd2_exists = os.path.exists(_pyd_path2)
            _kmnet_load_errors.append(f"检查 {_pyd_path2}: {'存在' if _pyd2_exists else '不存在'}")
            if _pyd2_exists:
                try:
                    _spec = importlib.util.spec_from_file_location('kmNet', _pyd_path2)
                    _kmNet = importlib.util.module_from_spec(_spec)
                    _spec.loader.exec_module(_kmNet)
                    _KMNET_AVAILABLE = True
                    _kmnet_load_errors.append(f"成功加载: {_pyd_path2}")
                    break
                except Exception as _ie2:
                    _kmnet_load_errors.append(f"加载失败 {_pyd_path2}: {_ie2}")
            try:
                import kmNet as _kmNet
                _KMNET_AVAILABLE = True
                _kmnet_load_errors.append(f"成功通过import kmNet加载")
                break
            except Exception as _ime:
                _kmnet_load_errors.append(f"import kmNet失败: {_ime}")
                continue
    if not _KMNET_AVAILABLE:
        import traceback
        _kmnet_load_errors.append(f"traceback: {traceback.format_exc()}")


