def is_backup_active():
    """当前是否在使用备用线路"""
    return _current_api_base == _BACKUP_BASE

def _detect_cloudflare_block(html_text):
    """检测响应是否是拦截页（5秒盾/挑战页）"""
    if not html_text:
        return False
    t = html_text.lower()
    markers = [
        "cloudflare", "cf-browser-verification", "cf-challenge",
        "attention required", "just a moment", "error 52", "error 53",
        "ray id", "checking your browser",
    ]
    return any(m in t for m in markers)

def _probe_ping(root_url):
    """探测指定线路的 ping 接口，返回 True 表示可用
    尝试 2 次，每次超时 5 秒，返回文本为 'ok' 即视为可用
    """
    ping_url = root_url + _PING_ENDPOINT
    for attempt in range(2):
        try:
            resp = _safe_get(ping_url, timeout=5, retries=0)
            text = resp.text.strip()
            if text.lower() == "ok":
                return True
            if _detect_cloudflare_block(resp.text):
                continue
        except Exception:
            pass
    return False

def trigger_backup_if_needed(reason=""):
    """触发切换：主线路 → 备用线路。
    切换后本次运行内所有请求全部走备用线路。
    已在备用线路上则忽略。
    """
    global _current_api_base, _dns_fallback_triggered
    if _dns_fallback_triggered:
        return False
    _dns_fallback_triggered = True
    _current_api_base = _BACKUP_BASE
    try:
        log_dir = os.path.join(BASE_DATA_DIR, "logs")
        os.makedirs(log_dir, exist_ok=True)
        log_path = os.path.join(log_dir, f"network_{time.strftime('%Y%m%d')}.log")
        with open(log_path, 'a', encoding='utf-8') as f:
            f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] [FAILOVER] switch to backup line\n")
            f.write(f"  reason: {reason}\n")
    except Exception:
        pass
    return True

def startup_domain_probe():
    """启动时域名探测
    先探测主线路 ping 接口，不可用则切换到备用线路。
    只在程序启动时调用一次，后续不再切换。
    """
    global _ping_probe_done
    if _ping_probe_done:
        return
    _ping_probe_done = True
    try:
        if _probe_ping(_PRIMARY_ROOT):
            return  # 主线路可用，保持默认
        # 主线路不可用，切换到备用
        trigger_backup_if_needed("startup ping probe failed")
    except Exception:
        pass

