# ========== 网络时间获取 ==========
NTP_SERVERS = [
    "ntp.aliyun.com",
    "ntp1.aliyun.com",
    "ntp2.aliyun.com",
    "time.windows.com",
    "pool.ntp.org"
]

HTTP_TIME_SERVERS = [
    "https://www.baidu.com",
    "https://www.taobao.com",
    "https://www.jd.com"
]

_last_network_time = 0
_last_network_time_offset = 0

def get_network_time():
    """获取网络时间戳（秒），优先NTP，失败则用HTTP，都失败返回None"""
    global _last_network_time, _last_network_time_offset
    
    for ntp_server in NTP_SERVERS:
        client = None
        try:
            import socket
            import struct
            client = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            client.settimeout(3)
            data = b'\x1b' + 47 * b'\0'
            client.sendto(data, (ntp_server, 123))
            data, _ = client.recvfrom(1024)
            if data:
                t = struct.unpack('!12I', data)[10]
                t -= 2208988800
                _last_network_time = t
                _last_network_time_offset = t - int(time.time())
                return t
        except:
            continue
        finally:
            if client:
                try:
                    client.close()
                except:
                    pass
    
    for http_server in HTTP_TIME_SERVERS:
        try:
            from datetime import datetime
            headers = {"Cache-Control": "no-cache"}
            response = _NET_SESSION.head(http_server, headers=headers, timeout=5)
            date_str = response.headers.get("Date", "")
            if date_str:
                from email.utils import parsedate_to_datetime
                dt = parsedate_to_datetime(date_str)
                t = int(dt.timestamp())
                _last_network_time = t
                _last_network_time_offset = t - int(time.time())
                return t
        except:
            continue
    
    if _last_network_time > 0:
        return int(time.time()) + _last_network_time_offset
    
    return None

def get_safe_time():
    """获取安全时间戳，优先网络时间，失败则用本地时间加防回退检查。
    注意：本函数不写 last_time.dat —— last_verified_time 只应由
    verify_response() 在服务器签名响应通过后写入，否则网络时间比
    服务器快几秒就会导致"时间倒退"误判，所有心跳验签全部失败。
    """
    net_time = get_network_time()
    if net_time:
        return net_time

    last_time = _get_last_verified_time()
    local_time = int(time.time())

    if last_time > 0 and local_time < last_time:
        return last_time

    return local_time

def _get_last_verified_time():
    """读取最后验证时间（带签名校验）"""
    try:
        path = os.path.join(BASE_DATA_DIR, "last_time.dat")
        if os.path.exists(path):
            with open(path, 'r', encoding='utf-8') as f:
                content = f.read().strip()
                if '|' in content:
                    parts = content.split('|', 1)
                    if len(parts) == 2:
                        time_str, signature = parts
                        expected_sign = hashlib.sha256((time_str + SIGN_KEY).encode()).hexdigest()
                        if signature == expected_sign and time_str.isdigit():
                            return int(time_str)
        return 0
    except:
        pass
    return 0

def _save_last_verified_time(t):
    """保存最后验证时间（带签名）"""
    try:
        path = os.path.join(BASE_DATA_DIR, "last_time.dat")
        os.makedirs(os.path.dirname(path), exist_ok=True)
        signature = hashlib.sha256((str(t) + SIGN_KEY).encode()).hexdigest()
        with open(path, 'w', encoding='utf-8') as f:
            f.write(f"{t}|{signature}")
    except:
        pass

# ========== 网络验证工具函数 ==========
def md5_string(data_str):
    return hashlib.md5(data_str.encode('utf-8')).hexdigest().lower()

def _hmac_sha256_hex(msg_bytes: bytes, key_bytes: bytes) -> str:
    """【S3 新增强签】HMAC-SHA256 输出 64 字符 hex，抗长度扩展攻击。"""
    import hmac as _hmac
    mac = _hmac.new(key_bytes, msg_bytes, hashlib.sha256)
    return mac.hexdigest().lower()

def calc_sign(data):
    key_len = len(SIGN_KEY)
    res = ""
    for i in range(len(data)):
        v = (ord(data[i]) + ord(SIGN_KEY[i % key_len])) % 256
        res += f"{v:02x}"
    return res.lower()

def verify_response(raw, xsign2, x_hs256: str = ""):
    """【S3 响应验签升级】
    优先级：X-Hs256(HMAC-SHA256 强签) > X-Sign2(MD5) > sign字段 MD5 > sign字段 旧 calc_sign
    全部走完只要一级通过就算合法；同时最后校验时间戳 + 时间不可倒流，防止重放与本地改时间。

    参数：
      raw     - 服务器原始响应体（可能带 |sign= 或 |hs256= 后缀）
      xsign2  - 响应头 X-Sign2（MD5）
      x_hs256 - 响应头 X-Hs256（HMAC-SHA256 hex 64 字符），2026 新版服务器会下发
    """
    if not raw:
        return ""

    raw = raw.strip()
    traceback = None  # 保留给外层诊断

    # ① 剥离可选的 |hs256= 强签后缀（新版本优先走这条），把 body 单独提出来
    body = raw
    embedded_hs256 = ""
    if "|hs256=" in raw:
        body, embedded_hs256 = raw.rsplit("|hs256=", 1)
        body = body.strip()
        embedded_hs256 = embedded_hs256.strip()
    elif "|sign=" in raw:
        body, _sign_tail = raw.split("|sign=", 1)
        body = body.strip()
    else:
        # 没有任何签后缀，旧服务短签名（sign写在最末尾）情况 —— 交给后面处理
        body = raw

    # ② 从原始 body 末尾抽时间戳（最后一个 | 后面）
    ts_str = ""
    last_pipe_body = body.rfind("|")
    if last_pipe_body >= 0:
        ts_candidate = body[last_pipe_body + 1:].strip()
        # 【F1-2 修复】只有 9 位以上的纯数字才视为 Unix 时间戳
        # (2001-09-09 对应的时间戳是 1000000000，9 位数起)
        # 防止 ok|365|sign=xxx 中的 365 被误判为时间戳，导致误走时间差校验被拒绝。
        if ts_candidate.isdigit() and len(ts_candidate) >= 9:
            ts_str = ts_candidate

    # ③ 计算验签的待签名原文（不含 sign/hs256 后缀，含末尾时间戳，与服务器签名顺序保持一致）
    signed_plain = body  # 原始 body 就包含时间戳（如果有的话）
    key_utf8 = SIGN_KEY.encode("utf-8")

    valid_sign = False

    # ── 第 1 级：HMAC-SHA256 强签（X-Hs256 响应头 或 |hs256= body 后缀）──
    hs256_input = (x_hs256 or "").strip().lower()
    if not hs256_input and embedded_hs256:
        hs256_input = embedded_hs256.lower()
    if len(hs256_input) == 64:
        local_hs256 = _hmac_sha256_hex(signed_plain.encode("utf-8"), key_utf8)
        if hmac.compare_digest(local_hs256, hs256_input):
            valid_sign = True

    # ── 第 2 级：X-Sign2 响应头 MD5（卡密通推荐）──
    if not valid_sign and xsign2 and len(xsign2) == 32:
        local_sign = md5_string(signed_plain + SIGN_KEY)
        if hmac.compare_digest(local_sign, xsign2.lower()):
            valid_sign = True

    # ── 第 3 级：sign 字段（响应体内部 |sign=）MD5 版本 ──
    if not valid_sign and "|sign=" in raw:
        _sign_body, _sign_tail = raw.split("|sign=", 1)
        _sign_tail = _sign_tail.strip()
        # 如果响应是旧格式：body|sign|timestamp|sign=xxxx，signed_plain 已经只取了 body|sign|timestamp
        if len(_sign_tail) >= 32:
            _sig32 = _sign_tail[:32]
            local_sign = md5_string(signed_plain + SIGN_KEY)
            if hmac.compare_digest(local_sign.lower(), _sig32.lower()):
                valid_sign = True
        else:
            local_sign = calc_sign(signed_plain)
            if hmac.compare_digest(local_sign.lower(), _sign_tail.lower()):
                valid_sign = True

    # 任何一级都没过 → 拒绝响应，防止中间人伪造
    if not valid_sign:
        return ""

    # ── 时间戳校验 + 时间倒退防篡改 ──
    # 【F1 兼容性修复】如果签名通过但服务器没有返回时间戳，
    # 跳过时间校验直接返回 body（兼容旧版服务端）。
    # 只有时间戳存在时才执行严格的时间差 + 时间不可逆校验。
    has_ts = bool(ts_str and ts_str.isdigit())
    if has_ts:
        try:
            server_timestamp = int(ts_str)
        except Exception:
            has_ts = False

    if has_ts:
        try:
            current_timestamp = get_safe_time()
        except Exception:
            current_timestamp = None
        if current_timestamp is not None:
            time_diff = abs(current_timestamp - server_timestamp)
            if time_diff > TIMESTAMP_MAX_DIFF:
                return ""
        # 防"本地时间向后调"绕过试用期：服务器时间应严格 >= 上一次成功验证时间
        try:
            last_t = _get_last_verified_time()
            if last_t and server_timestamp < last_t:
                return ""
            # 本次合法，记录为新的"最后验证时间"（下次还能继续往前比）
            if server_timestamp > 0:
                _save_last_verified_time(server_timestamp)
        except Exception:
            pass

    # 去掉最后时间戳，返回真正业务内容（ok|xxx|expirelabel|expirets 这种格式的前缀）
    if has_ts and last_pipe_body > 0:
        return body[:last_pipe_body]
    return body

_NET_UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"

# 网络请求重试配置
_NET_MAX_RETRIES = 2
_NET_RETRY_DELAY = 0.3

# 【S2 稳定修复】全局 requests.Session 不是线程安全的，多线程并发调用时会出现
# 连接池错乱 / 响应对象交叉返回 / urllib3.PoolKey 复用错误。用 RLock 串行化。
_NET_SESSION_LOCK = threading.RLock()

# 【S1 安全修复】SPKI pin 白名单。空列表表示"当前未启用 pin 强校验"——
# 但只要这里填入服务器证书 SubjectPublicKeyInfo 的 SHA-256（大写十六进制），
# 所有 HTTPS 请求在发出前都会去做一次独立 TLS 握手并比对公钥指纹；不匹配就拒绝。
# 用法示例：_SERVER_SPKI_PIN_SHA256 = ["AA:BB:CC:DD:..."]
_SERVER_SPKI_PIN_SHA256: list[str] = []

def _pin_peers_ok(url: str) -> bool:
    """请求前做 SPKI pin 校验（如果白名单非空）。
    空列表 / 非 HTTPS / 没有 cryptography / 解析失败 → 返回 True 不阻断。"""
    if not _SERVER_SPKI_PIN_SHA256:
        return True
    try:
        from urllib.parse import urlparse
        host = urlparse(url).hostname
        if not host:
            return True
        scheme = (urlparse(url).scheme or "").lower()
        if scheme != "https":
            return True  # HTTP 不走 TLS，pin 不适用
        port = urlparse(url).port or 443
    except Exception:
        return True
    try:
        import socket as _sk
        import ssl as _sslmod
        try:
            from cryptography import x509 as _x509
            from cryptography.hazmat.primitives import hashes as _hashes
            from cryptography.hazmat.primitives.serialization import Encoding as _Enc, PublicFormat as _PF
        except Exception:
            return True  # 缺少密码学库，pin 校验无法执行 -> 放行（保持兼容）
        ctx = _sslmod.create_default_context()
        ctx.check_hostname = False
        ctx.verify_mode = _sslmod.CERT_NONE
        with _sk.create_connection((host, port), timeout=5.0) as sock:
            with ctx.wrap_socket(sock, server_hostname=host) as ss:
                der = ss.getpeercert(binary_form=True)
        if not der:
            return False
        cert = _x509.load_der_x509_certificate(der)
        spki_der = cert.public_key().public_bytes(_Enc.DER, _PF.SubjectPublicKeyInfo)
        import hashlib as _hl
        fp = _hl.sha256(spki_der).hexdigest().upper()
        normalized_pins = [p.replace(":", "").replace("-", "").replace(" ", "").upper()
                           for p in _SERVER_SPKI_PIN_SHA256]
        return fp in normalized_pins
    except Exception:
        # 连接失败 / 证书解析失败 —— 交给后续 _NET_SESSION 的真实请求去报网络错误
        return True

# 创建全局session，禁用代理和SSL验证，确保跨环境兼容性
_NET_SESSION = requests.Session()
_NET_SESSION.proxies = {"http": None, "https": None}
_NET_SESSION.verify = False
_NET_SESSION.headers.update({"User-Agent": _NET_UA})

# 【P3-3 Session 定期重建】每 200 次请求或 30 分钟自动重建 Session，
# 防止长期运行下 Cookie / 连接池状态累积导致泄漏或连接退化
_NET_SESSION_MAX_USES = 200
_NET_SESSION_MAX_AGE_SEC = 1800
_net_session_uses = 0
_net_session_created = time.time()

def _maybe_rebuild_session():
    """在 RLock 保护下检查并重建 Session，调用方已持有 _NET_SESSION_LOCK"""
    global _NET_SESSION, _net_session_uses, _net_session_created
    now = time.time()
    if (_net_session_uses >= _NET_SESSION_MAX_USES or
            now - _net_session_created >= _NET_SESSION_MAX_AGE_SEC):
        try:
            _NET_SESSION.close()
        except Exception:
            pass
        _NET_SESSION = requests.Session()
        _NET_SESSION.proxies = {"http": None, "https": None}
        _NET_SESSION.verify = False
        _NET_SESSION.headers.update({"User-Agent": _NET_UA})
        _net_session_uses = 0
        _net_session_created = now

def _safe_get(url, headers=None, timeout=30, retries=None, **kwargs):
    """安全的GET请求，支持自动重试和错误恢复
    自动禁用代理和SSL验证，确保跨环境兼容性
    【S2 稳定修复】全局 Session 加 RLock 串行化，避免多线程并发连接池错乱
    【S1 安全修复】请求前做 SPKI pin 校验（pin 列表非空时）
    【P3-3】Session 定期重建，防止 Cookie/连接池累积"""
    if headers is None:
        headers = {}
    headers.setdefault("User-Agent", _NET_UA)

    # 强制禁用代理和SSL验证
    kwargs.setdefault("proxies", {"http": None, "https": None})
    kwargs.setdefault("verify", False)
    
    if retries is None:
        retries = _NET_MAX_RETRIES
    
    last_error = None
    for attempt in range(retries + 1):
        try:
            # 【S1】请求前 SPKI pin（_SERVER_SPKI_PIN_SHA256 空时直接 return True，不阻断）
            if not _pin_peers_ok(url):
                raise requests.exceptions.SSLError(
                    f"[SPKI pin] {url} 证书公钥指纹未匹配白名单，请求在发出前已拦截"
                )
            with _NET_SESSION_LOCK:
                _maybe_rebuild_session()
                response = _NET_SESSION.get(url, headers=headers, timeout=timeout, **kwargs)
            # 成功后递增计数（重试的同一逻辑请求只算 1 次）
            global _net_session_uses
            _net_session_uses += 1
            return response
        except requests.exceptions.RequestException as e:
            last_error = e
            if attempt < retries:
                time.sleep(_NET_RETRY_DELAY * (attempt + 1))
                continue
    raise last_error

def _safe_post(url, json=None, headers=None, timeout=30, retries=None, **kwargs):
    """安全的POST请求，支持自动重试和错误恢复
    自动禁用代理和SSL验证，确保跨环境兼容性
    【S2 稳定修复】RLock + 【S1】请求前 SPKI pin
    【P3-3】Session 定期重建"""
    if headers is None:
        headers = {}
    headers.setdefault("User-Agent", _NET_UA)
    
    # 强制禁用代理和SSL验证
    kwargs.setdefault("proxies", {"http": None, "https": None})
    kwargs.setdefault("verify", False)
    
    if retries is None:
        retries = _NET_MAX_RETRIES
    
    last_error = None
    for attempt in range(retries + 1):
        try:
            if not _pin_peers_ok(url):
                raise requests.exceptions.SSLError(
                    f"[SPKI pin] {url} 证书公钥指纹未匹配白名单，请求在发出前已拦截"
                )
            with _NET_SESSION_LOCK:
                _maybe_rebuild_session()
                response = _NET_SESSION.post(url, json=json, headers=headers, timeout=timeout, **kwargs)
            # 成功后递增计数（重试的同一逻辑请求只算 1 次）
            global _net_session_uses
            _net_session_uses += 1
            return response
        except requests.exceptions.RequestException as e:
            last_error = e
            if attempt < retries:
                time.sleep(_NET_RETRY_DELAY * (attempt + 1))
                continue
    raise last_error

def _safe_urlopen(url, timeout=15):
    """安全的urllib请求，禁用系统代理影响
    【修复】不再使用全局install_opener，避免多线程竞态和跨环境兼容问题
    【P1-2 安全修复】请求前做 SPKI pin 校验，与 _safe_get/_safe_post 保持一致"""
    # 提取 URL 字符串做 SPKI pin 校验
    _url_str = url if isinstance(url, str) else getattr(url, 'full_url', '')
    if _url_str and not _pin_peers_ok(_url_str):
        raise urllib.error.URLError(
            f"[SPKI pin] {_url_str} 证书公钥指纹未匹配白名单，请求在发出前已拦截"
        )
    if isinstance(url, str):
        url = urllib.request.Request(url, headers={'User-Agent': _NET_UA})
    # 使用ProxyHandler禁用代理，直接使用opener而非全局安装
    proxy_handler = urllib.request.ProxyHandler({})
    # 添加HTTPS处理器（跳过SSL验证，确保跨环境兼容）
    ssl_ctx = ssl.create_default_context()
    ssl_ctx.check_hostname = False
    ssl_ctx.verify_mode = ssl.CERT_NONE
    https_handler = urllib.request.HTTPSHandler(context=ssl_ctx)
    opener = urllib.request.build_opener(proxy_handler, https_handler)
    return opener.open(url, timeout=timeout)

def check_card_core(card, mac, is_heartbeat=False):
    """
    核心卡密验证函数
    支持多种网络环境，包含完整的错误处理和日志记录
    每次调用动态取当前生效线路，主线路不可用时自动走备用
    """
    last_error = None
    _failover_tried = False  # 本轮验证是否已尝试过切换线路
    
    for attempt in range(3):
        try:
            # 获取时间戳
            t_str = str(get_safe_time())
            
            # 构建请求URL（动态取当前线路，切换后自动走备用）
            url = f"{get_server_url()}?card={_url_quote(str(card), safe='')}&mac={_url_quote(str(mac), safe='')}&app={APP_NAME}&heart=1&t={t_str}"
            
            # 发送请求 - 使用安全的GET请求（带重试机制）
            response = _safe_get(
                url, 
                headers={"Cache-Control": "no-cache"}, 
                timeout=10,
                retries=1  # 外层还有3次重试，这里只加1次
            )
            
            ret = response.text
            xsign2 = response.headers.get("X-Sign2", "")
            xhs256 = response.headers.get("X-Hs256", "")
            
            # 记录调试日志
            log_dir = os.path.join(BASE_DATA_DIR, "logs")
            os.makedirs(log_dir, exist_ok=True)
            log_path = os.path.join(log_dir, f"verify_{time.strftime('%Y%m%d')}.log")
            with open(log_path, 'a', encoding='utf-8') as f:
                f.write(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] ")
                f.write(f"attempt={attempt}, ")
                f.write(f"status_code={response.status_code}, ")
                f.write(f"xsign2_present={bool(xsign2)}, ")
                f.write(f"xsign2_length={len(xsign2)}, ")
                f.write(f"response_length={len(ret)}, ")
                f.write(f"has_sign={'|sign=' in ret}, ")
                f.write(f"response_first_200={repr(ret[:200])}\n")
            
            # 【修复】服务器限频响应(too_frequent)可能未带有效签名，
            # 验签失败会被误判为"签名失败"而触发外层重试，反而加剧限频。
            # 这里只要在原始响应里检测到 too_frequent，就直接视为终态返回、不再重试。
            if "too_frequent" in ret:
                _freq_msg, _ = trans_msg_and_get_action("too_frequent")
                return "error|" + _freq_msg

            # 检查响应格式
            if not ret or ("|sign=" not in ret and "|hs256=" not in ret):
                if attempt < 2:
                    time.sleep(0.5)
                    continue
                _log_network_error("PROTOCOL", f"服务器返回格式错误: {repr(ret[:100]) if ret else '空响应'}")
                return "network|服务器响应异常，可能是网络波动或代理干扰"
            
            # 验证响应签名（X-Hs256 优先 -> X-Sign2 -> sign字段 -> 时间戳 -> 不可倒流）
            biz = verify_response(ret, xsign2, xhs256)
            
            if biz:
                if biz.startswith("error|"):
                    raw_code = biz.split('|')[1]
                    msg, is_ok = trans_msg_and_get_action(raw_code)
                    if is_ok:
                        return f"ok|{msg}"
                    # 【F4 修复】too_frequent 是服务器限频，立即返回不重试
                    # 否则内部 3 次重试会加剧限频，导致连续多个 too_frequent
                    if raw_code == "too_frequent":
                        return f"error|{msg}"
                    return f"error|{msg}"

                arr = biz.split("|")
                status_code = arr[0]
                days = arr[1] if len(arr) == 2 else arr[2]

                if is_heartbeat:
                    msg, _ = trans_msg_and_get_action("heartbeat")
                else:
                    msg, _ = trans_msg_and_get_action("valid")

                expire_time = ""
                expire_ts = 0
                now = get_safe_time()
                if days.isdigit():
                    if len(arr) >= 4:
                        total_mins = int(arr[3])
                        expire_time = f"{total_mins // 1440}天{(total_mins % 1440) // 60}小时{total_mins % 60}分钟"
                        expire_ts = now + total_mins * 60
                    else:
                        expire_time = f"{days}天"
                        expire_ts = now + int(days) * 86400
                elif days.lower() == "permanent":
                    msg, _ = trans_msg_and_get_action("permanent")
                    expire_time = msg
                    expire_ts = now + 365 * 86400 * 100  # 100年，视为永不过期
                else:
                    expire_time = days
                    expire_ts = 0
                return f"ok|{msg}|{expire_time}|{expire_ts}"
            
            # 签名验证失败
            if attempt < 2:
                time.sleep(0.5)
                continue
        
        except requests.exceptions.Timeout as e:
            last_error = f"请求超时: {str(e)[:100]}"
            if attempt < 2:
                time.sleep(0.3)
                continue
                
        except requests.exceptions.SSLError as e:
            last_error = f"SSL证书错误: {str(e)[:100]}"
            _log_network_error("SSL_ERROR", last_error)
            # SSL错误通常不是临时问题，直接返回
            ssl_msg = "SSL证书验证失败"
            if "CERTIFICATE_VERIFY_FAILED" in str(e):
                ssl_msg = "SSL证书验证失败，请检查系统时间和根证书"
            elif "name mismatch" in str(e).lower():
                ssl_msg = "SSL证书域名不匹配"
            return f"network|{ssl_msg}"
                
        except requests.exceptions.ConnectionError as e:
            last_error = f"连接错误: {str(e)[:150]}"
            if attempt < 2:
                time.sleep(0.5)
                continue
                
        except requests.exceptions.RequestException as e:
            last_error = f"请求异常: {str(e)[:100]}"
            if attempt < 2:
                time.sleep(0.3)
                continue
                
        except Exception as e:
            last_error = f"未知异常: {str(e)[:100]}"
            if attempt < 2:
                time.sleep(0.3)
                continue
    
    # 所有重试都失败了
    # 如果还没切换过线路，自动切换到备用线路再试一次
    if not _failover_tried and trigger_backup_if_needed(f"卡密验证失败: {str(last_error)[:100]}"):
        _failover_tried = True
        # 切换线路后，用新地址重新验证一次
        try:
            t_str = str(get_safe_time())
            url = f"{get_server_url()}?card={_url_quote(str(card), safe='')}&mac={_url_quote(str(mac), safe='')}&app={APP_NAME}&heart=1&t={t_str}"
            response = _safe_get(url, headers={"Cache-Control": "no-cache"}, timeout=10, retries=1)
            ret = response.text
            xsign2 = response.headers.get("X-Sign2", "")
            xhs256 = response.headers.get("X-Hs256", "")
            
            # 检测拦截页
            if _detect_cloudflare_block(ret):
                raise Exception("backup line returned challenge page")
            
            # 检查响应格式
            if not ret or ("|sign=" not in ret and "|hs256=" not in ret):
                _log_network_error("PROTOCOL", f"backup line format error: {repr(ret[:100]) if ret else 'empty'}")
            else:
                # 验证响应签名
                biz = verify_response(ret, xsign2, xhs256)
                if biz:
                    if biz.startswith("error|"):
                        raw_code = biz.split('|')[1]
                        msg, is_ok = trans_msg_and_get_action(raw_code)
                        if is_ok:
                            return f"ok|{msg}"
                        if raw_code == "too_frequent":
                            return f"error|{msg}"
                        return f"error|{msg}"
                    
                    arr = biz.split("|")
                    status_code = arr[0]
                    days = arr[1] if len(arr) == 2 else arr[2]
                    
                    if is_heartbeat:
                        msg, _ = trans_msg_and_get_action("heartbeat")
                    else:
                        msg, _ = trans_msg_and_get_action("valid")
                    
                    expire_time = ""
                    expire_ts = 0
                    now = get_safe_time()
                    if days.isdigit():
                        if len(arr) >= 4:
                            total_mins = int(arr[3])
                            expire_time = f"{total_mins // 1440}天{(total_mins % 1440) // 60}小时{total_mins % 60}分钟"
                            expire_ts = now + total_mins * 60
                        else:
                            expire_time = f"{days}天"
                            expire_ts = now + int(days) * 86400
                    elif days.lower() == "permanent":
                        msg, _ = trans_msg_and_get_action("permanent")
                        expire_time = msg
                        expire_ts = now + 365 * 86400 * 100
                    else:
                        expire_time = days
                        expire_ts = 0
                    return f"ok|{msg}|{expire_time}|{expire_ts}"
        except Exception as e:
            last_error = f"backup line also failed: {str(e)[:100]}"
    
    # 备用线路也失败，或已经切换过，返回最终错误
    if last_error:
        # 根据错误类型返回友好的错误信息，附带排查指引
        err_str = str(last_error)
        
        if "超时" in err_str or "Timeout" in err_str or "timed out" in err_str.lower():
            _log_network_error("TIMEOUT", last_error)
            return "network|请求响应超时，请检查网络连接是否稳定，或稍后重试"
        elif "连接错误" in err_str or "ConnectionError" in err_str or "connection" in err_str.lower():
            _log_network_error("CONNECTION", last_error)
            # 进一步区分具体连接问题
            if "DNS" in err_str or "NameResolutionError" in err_str:
                return "network|DNS解析失败，请检查DNS设置或网络连接"
            elif "ConnectionRefusedError" in err_str or "111" in err_str:
                return "network|服务器拒绝连接，服务器可能暂时不可用"
            elif "RemoteDisconnected" in err_str or "ConnectionResetError" in err_str:
                return "network|连接被远程服务器中断，请稍后重试"
            else:
                return "network|无法连接到服务器，请检查网络连接是否正常"
        elif "SSL" in err_str.upper() or "CERTIFICATE" in err_str.upper():
            _log_network_error("SSL", last_error)
            if "CERTIFICATE_VERIFY_FAILED" in err_str:
                return "network|SSL证书验证失败，请检查系统时间是否正确"
            elif "name mismatch" in err_str.lower():
                return "network|SSL证书域名不匹配"
            else:
                return "network|SSL连接错误，请检查网络环境或系统证书"
        elif "proxy" in err_str.lower() or "代理" in err_str:
            _log_network_error("PROXY", last_error)
            return "network|代理连接失败，请检查代理设置或关闭代理后重试"
        else:
            _log_network_error("UNKNOWN", last_error)
            return f"network|网络请求失败，请检查网络连接后重试"
    else:
        return "network|验证响应异常，可能是时间不同步或网络波动"

def _log_network_error(error_type, error_msg):
    """记录网络错误日志到文件，便于排查问题"""
    try:
        log_dir = os.path.join(BASE_DATA_DIR, "logs")
        os.makedirs(log_dir, exist_ok=True)
        log_path = os.path.join(log_dir, f"network_{time.strftime('%Y%m%d')}.log")
        
        log_entries = []
        log_entries.append(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {'='*60}")
        log_entries.append(f"错误类型: {error_type}")
        log_entries.append(f"错误信息: {error_msg}")
        log_entries.append(f"服务器: {get_server_url()}")
        log_entries.append(f"是否备用线路: {'是' if is_backup_active() else '否'}")
        log_entries.append(f"平台: {sys.platform}")
        log_entries.append(f"Python版本: {sys.version}")
        log_entries.append(f"程序版本: {LOCAL_VERSION}")
        log_entries.append(f"是否打包: {getattr(sys, 'frozen', False)}")
        
        # 检测系统代理设置
        try:
            import urllib.request
            proxy_settings = urllib.request.getproxies()
            log_entries.append(f"系统代理: {proxy_settings if proxy_settings else '无'}")
        except Exception as e:
            log_entries.append(f"系统代理: 获取失败 - {str(e)[:50]}")
        
        # 检测环境变量代理
        proxy_env = {}
        for var in ['HTTP_PROXY', 'HTTPS_PROXY', 'NO_PROXY', 'http_proxy', 'https_proxy', 'no_proxy']:
            val = os.environ.get(var)
            if val:
                proxy_env[var] = val
        if proxy_env:
            log_entries.append(f"环境变量代理: {proxy_env}")
        else:
            log_entries.append("环境变量代理: 无")
        
        # DNS解析测试
        try:
            import socket
            from urllib.parse import urlparse
            _diag_host = urlparse(_current_api_base).hostname
            ip_addr = socket.gethostbyname(_diag_host)
            log_entries.append(f"DNS解析 {_diag_host} → {ip_addr}")
        except socket.gaierror as e:
            log_entries.append(f"DNS解析失败: {str(e)[:80]}")
        except Exception as e:
            log_entries.append(f"DNS测试异常: {str(e)[:60]}")
        
        # TCP端口测试
        try:
            import socket
            from urllib.parse import urlparse
            _diag_host = urlparse(_current_api_base).hostname
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(5)
            result = sock.connect_ex((_diag_host, 443))
            sock.close()
            if result == 0:
                log_entries.append(f"TCP连接 {_diag_host}:443 正常")
            else:
                log_entries.append(f"TCP连接 {_diag_host}:443 失败 (错误码: {result})")
        except Exception as e:
            log_entries.append(f"TCP测试异常: {str(e)[:60]}")
        
        # 网络适配器状态
        try:
            import psutil
            net_io = psutil.net_io_counters()
            log_entries.append(f"网络状态: 发送={net_io.bytes_sent/1024/1024:.1f}MB, 接收={net_io.bytes_recv/1024/1024:.1f}MB")
            
            # 检查活动网络接口
            net_if = psutil.net_if_addrs()
            active_ips = []
            for iface, addrs in net_if.items():
                for addr in addrs:
                    if hasattr(addr, 'family') and addr.family == 2:  # AF_INET
                        if not addr.address.startswith('127.'):
                            active_ips.append(f"{iface}: {addr.address}")
            if active_ips:
                log_entries.append(f"活动网络接口: {', '.join(active_ips)}")
            else:
                log_entries.append("⚠ 未检测到活动的外网接口")
        except Exception:
            pass
        
        # 尝试通过HTTP测试连接（使用_safe_get避免代理干扰）
        try:
            test_resp = _NET_SESSION.get("https://www.baidu.com", timeout=5)
            log_entries.append(f"百度HTTPS测试: 状态码{test_resp.status_code} ✓")
        except Exception as e:
            log_entries.append(f"百度HTTPS测试失败: {str(e)[:80]}")
        
        # 检查防火墙相关提示
        log_entries.append("排查建议:")
        log_entries.append("  1. 检查是否能正常访问其他网站(如百度)")
        log_entries.append("  2. 如果使用了VPN/代理，尝试关闭后重试")
        log_entries.append("  3. 检查防火墙是否阻止了程序的网络访问")
        log_entries.append("  4. 确认系统时间是否准确")
        
        log_entries.append("")
        
        with open(log_path, 'a', encoding='utf-8') as f:
            f.write('\n'.join(log_entries))
            
    except Exception:
        pass

def test_network_connection():
    """测试网络连接状态，返回 (success, message)"""
    results = []
    all_ok = True
    
    # 1. 基础网络连通性测试
    test_urls = [
        ("主服务器", SERVER_URL),
        ("百度", "https://www.baidu.com"),
        ("淘宝", "https://www.taobao.com"),
    ]
    
    for name, url in test_urls:
        try:
            start_time = time.time()
            response = _safe_get(url, timeout=8, retries=0)
            elapsed = (time.time() - start_time) * 1000
            if response.status_code == 200:
                results.append(f"✓ {name}: 正常 ({elapsed:.0f}ms)")
            else:
                results.append(f"⚠ {name}: 状态码 {response.status_code} ({elapsed:.0f}ms)")
                all_ok = False
        except requests.exceptions.Timeout:
            results.append(f"✗ {name}: 请求超时")
            all_ok = False
        except requests.exceptions.SSLError as e:
            results.append(f"✗ {name}: SSL证书错误 - {str(e)[:80]}")
            all_ok = False
        except requests.exceptions.ConnectionError as e:
            err_msg = str(e)[:100]
            if "NameResolutionError" in str(type(e).__name__) or "DNS" in str(e):
                results.append(f"✗ {name}: DNS解析失败")
            elif "ConnectionRefusedError" in str(e) or "111" in str(e):
                results.append(f"✗ {name}: 连接被拒绝")
            elif "timed out" in str(e) or "Timeout" in str(e):
                results.append(f"✗ {name}: 连接超时")
            else:
                results.append(f"✗ {name}: 连接失败 - {err_msg}")
            all_ok = False
        except Exception as e:
            results.append(f"✗ {name}: 错误 - {str(e)[:80]}")
            all_ok = False
    
    # 2. TCP连接测试（绕过HTTP层，直接测试端口连通性）
    try:
        import socket
        from urllib.parse import urlparse
        host = urlparse(_current_api_base).hostname
        port = 443
        start_time = time.time()
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)
        result_code = sock.connect_ex((host, port))
        elapsed = (time.time() - start_time) * 1000
        sock.close()
        if result_code == 0:
            results.append(f"✓ TCP连接 {host}:{port} 正常 ({elapsed:.0f}ms)")
        else:
            results.append(f"✗ TCP连接 {host}:{port} 失败 (错误码: {result_code})")
            all_ok = False
    except Exception as e:
        results.append(f"✗ TCP测试异常: {str(e)[:60]}")
    
    # 3. DNS解析测试
    try:
        import socket
        from urllib.parse import urlparse
        _diag_host = urlparse(_current_api_base).hostname
        start_time = time.time()
        ip_addr = socket.gethostbyname(_diag_host)
        elapsed = (time.time() - start_time) * 1000
        results.append(f"✓ DNS解析 {_diag_host} → {ip_addr} ({elapsed:.0f}ms)")
    except socket.gaierror as e:
        results.append(f"✗ DNS解析失败: {str(e)[:60]}")
        all_ok = False
    except Exception as e:
        results.append(f"✗ DNS测试异常: {str(e)[:60]}")
    
    # 4. 系统代理检测
    try:
        import urllib.request
        proxy_settings = urllib.request.getproxies()
        if proxy_settings:
            results.append(f"ℹ 系统代理: {proxy_settings}")
    except Exception:
        pass
    
    # 5. 检查环境变量中的代理设置
    proxy_env = {}
    for var in ['HTTP_PROXY', 'HTTPS_PROXY', 'NO_PROXY', 'http_proxy', 'https_proxy', 'no_proxy']:
        val = os.environ.get(var)
        if val:
            proxy_env[var] = val
    if proxy_env:
        results.append(f"ℹ 环境变量代理: {proxy_env}")
    
    # 6. 检查网络适配器状态
    try:
        import psutil
        net_io = psutil.net_io_counters()
        if net_io.bytes_sent > 0 or net_io.bytes_recv > 0:
            results.append(f"✓ 网络适配器正常 (发送: {net_io.bytes_sent/1024/1024:.1f}MB, 接收: {net_io.bytes_recv/1024/1024:.1f}MB)")
        else:
            results.append("⚠ 网络适配器无数据传输")
    except Exception:
        pass
    
    all_results = "\n".join(results)
    return all_ok, all_results

def diagnose_network():
    """
    全面网络诊断函数
    返回 (success, 诊断报告字符串)
    """
    report = []
    critical_issues = []
    
    report.append("=" * 60)
    report.append("网络连接诊断报告")
    report.append(f"诊断时间: {time.strftime('%Y-%m-%d %H:%M:%S')}")
    report.append("=" * 60)
    
    # 1. 系统网络状态
    report.append("\n【1. 系统网络状态】")
    try:
        import psutil
        net_io = psutil.net_io_counters()
        report.append(f"  网络发送总量: {net_io.bytes_sent/1024/1024:.2f} MB")
        report.append(f"  网络接收总量: {net_io.bytes_recv/1024/1024:.2f} MB")
        
        # 检查网络接口
        net_if = psutil.net_if_addrs()
        active_ips = []
        for iface, addrs in net_if.items():
            for addr in addrs:
                if addr.family == 2:  # AF_INET
                    if not addr.address.startswith('127.'):
                        active_ips.append(f"{iface}: {addr.address}")
        
        if active_ips:
            report.append(f"  活动网络接口: {', '.join(active_ips)}")
        else:
            report.append("  ⚠ 未检测到活动的网络接口（除回环）")
            critical_issues.append("未检测到活动的网络接口")
            
    except Exception as e:
        report.append(f"  系统网络状态检查失败: {str(e)[:60]}")
    
    # 2. DNS解析测试
    report.append("\n【2. DNS解析测试】")
    from urllib.parse import urlparse
    _diag_host = urlparse(_current_api_base).hostname
    test_domains = [
        ("主服务器", _diag_host),
        ("百度", "www.baidu.com"),
        ("淘宝", "www.taobao.com"),
        ("DNS服务器", "dns.baidu.com"),
    ]
    
    for name, domain in test_domains:
        try:
            start_time = time.time()
            ip_addr = socket.gethostbyname(domain)
            elapsed = (time.time() - start_time) * 1000
            report.append(f"  ✓ {name} ({domain}): {ip_addr} ({elapsed:.0f}ms)")
        except socket.gaierror as e:
            report.append(f"  ✗ {name} ({domain}): 解析失败 - {str(e)[:50]}")
            critical_issues.append(f"DNS解析失败: {domain}")
        except Exception as e:
            report.append(f"  ✗ {name} ({domain}): {str(e)[:50]}")
    
    # 3. TCP端口连接测试
    report.append("\n【3. TCP端口连接测试】")
    test_ports = [
        ("主服务器HTTPS", _diag_host, 443),
        ("百度HTTPS", "www.baidu.com", 443),
        ("淘宝HTTPS", "www.taobao.com", 443),
        ("阿里DNS", "223.5.5.5", 53),
        ("腾讯DNS", "114.114.114.114", 53),
    ]
    
    for name, host, port in test_ports:
        try:
            start_time = time.time()
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(5)
            result = sock.connect_ex((host, port))
            elapsed = (time.time() - start_time) * 1000
            sock.close()
            if result == 0:
                report.append(f"  ✓ {name} ({host}:{port}): 连接成功 ({elapsed:.0f}ms)")
            else:
                report.append(f"  ✗ {name} ({host}:{port}): 连接失败 (错误码: {result})")
                if name.startswith("主服务器"):
                    critical_issues.append(f"无法连接到{name}")
        except socket.timeout:
            report.append(f"  ✗ {name} ({host}:{port}): 连接超时")
            if name.startswith("主服务器"):
                critical_issues.append(f"连接{name}超时")
        except Exception as e:
            report.append(f"  ✗ {name} ({host}:{port}): {str(e)[:50]}")
    
    # 4. HTTP/HTTPS请求测试
    report.append("\n【4. HTTP请求测试】")
    test_urls = [
        ("主服务器", SERVER_URL),
        ("百度首页", "https://www.baidu.com"),
        ("淘宝首页", "https://www.taobao.com"),
    ]
    
    http_ok = 0
    for name, url in test_urls:
        try:
            start_time = time.time()
            response = _safe_get(url, timeout=8, retries=0)
            elapsed = (time.time() - start_time) * 1000
            if response.status_code == 200:
                report.append(f"  ✓ {name}: HTTP {response.status_code} ({elapsed:.0f}ms)")
                http_ok += 1
            else:
                report.append(f"  ⚠ {name}: HTTP {response.status_code} ({elapsed:.0f}ms)")
        except requests.exceptions.Timeout:
            report.append(f"  ✗ {name}: 请求超时")
        except requests.exceptions.SSLError as e:
            report.append(f"  ✗ {name}: SSL错误 - {str(e)[:60]}")
            if name == "主服务器":
                critical_issues.append("主服务器SSL证书错误")
        except requests.exceptions.ConnectionError as e:
            report.append(f"  ✗ {name}: 连接错误 - {str(e)[:60]}")
            if name == "主服务器":
                critical_issues.append("无法连接到主服务器")
        except Exception as e:
            report.append(f"  ✗ {name}: {str(e)[:60]}")
    
    # 5. 代理检查
    report.append("\n【5. 代理设置检查】")
    try:
        import urllib.request
        proxy_settings = urllib.request.getproxies()
        if proxy_settings:
            report.append(f"  系统代理: {proxy_settings}")
            report.append("  ⚠ 检测到系统代理，可能影响网络连接")
        else:
            report.append("  ✓ 未设置系统代理")
    except Exception as e:
        report.append(f"  代理检查失败: {str(e)[:50]}")
    
    # 检查环境变量代理
    proxy_env_found = []
    for var in ['HTTP_PROXY', 'HTTPS_PROXY', 'NO_PROXY']:
        val = os.environ.get(var) or os.environ.get(var.lower())
        if val:
            proxy_env_found.append(f"{var}={val}")
    if proxy_env_found:
        report.append(f"  环境变量代理: {', '.join(proxy_env_found)}")
        report.append("  ⚠ 环境变量代理可能影响网络连接")
    else:
        report.append("  ✓ 未设置环境变量代理")
    
    # 6. 防火墙提示
    report.append("\n【6. 防火墙检查提示】")
    report.append("  如以上测试均失败，请检查：")
    report.append("  - Windows防火墙是否阻止了程序的网络访问")
    report.append("  - 是否有第三方安全软件拦截了网络请求")
    report.append("  - 公司/学校网络是否有访问限制")
    report.append("  - 是否需要配置代理服务器")
    
    # 7. 总结
    report.append("\n" + "=" * 60)
    if critical_issues:
        report.append("【诊断结果】发现以下问题：")
        for issue in critical_issues:
            report.append(f"  ⚠ {issue}")
        report.append("\n建议操作：")
        report.append("  1. 检查网络物理连接（网线/Wi-Fi）")
        report.append("  2. 重启路由器和调制解调器")
        report.append("  3. 检查防火墙和安全软件设置")
        report.append("  4. 尝试关闭代理设置")
        report.append("  5. 如果使用VPN/加速器，尝试关闭后重试")
        success = False
    else:
        report.append("【诊断结果】网络连接正常")
        success = True
    
    report.append("=" * 60)
    
    full_report = "\n".join(report)
    
    # 保存诊断报告到文件
    try:
        log_dir = os.path.join(BASE_DATA_DIR, "logs")
        os.makedirs(log_dir, exist_ok=True)
        report_path = os.path.join(log_dir, f"diagnostic_{time.strftime('%Y%m%d_%H%M%S')}.log")
        with open(report_path, 'w', encoding='utf-8') as f:
            f.write(full_report)
    except Exception:
        pass
    
    return success, full_report

def trans_msg_and_get_action(code):
    mapping = {
        "already_online": ("该卡密已在线", False),
        "online_limit_reached": ("在线设备数已满", False),
        "activate": ("激活成功", True),
        "valid": ("验证通过", True),
        "permanent": ("终身有效", True),
        "heartbeat": ("心跳正常", True),
        "bypass": ("验证已关闭", True),
        "unbind_ok": ("解绑成功", True),
        "invalid_card": ("卡密无效", False),
        "expired": ("卡密已过期", False),
        "banned": ("卡密已被禁用", False),
        "device_mismatch": ("设备不匹配", False),
        "missing_params": ("参数不完整", False),
        # 【F4 修复】too_frequent 是服务器限频（验证请求间隔过短），
        # 属于临时性错误，卡密本身有效，不应触发重新验证或弹窗。
        # is_ok=False 但调用方会通过 error_type="api" + msg="too_frequent" 单独识别处理。
        "too_frequent": ("验证过于频繁，请稍候", False),
    }
    if code in mapping:
        return mapping[code]
    return (code, False)


def _atomic_write_text(path, content):
    """【P2-2 原子写入】先写同目录 .tmp 文件，flush+fsync 后 os.replace 原子覆盖。
    断电/磁盘满/进程被杀时不会留下半截文件损坏原有数据。
    【F3 Windows 文件锁重试】对 os.replace 增加最多 3 次重试，应对杀毒软件/搜索索引瞬时锁定。"""
    tmp_path = path + ".tmp"
    try:
        with open(tmp_path, 'w', encoding='utf-8') as f:
            f.write(content)
            f.flush()
            try:
                os.fsync(f.fileno())
            except OSError:
                pass
        # 【F3】os.replace 在 Windows 上若目标文件被杀毒/索引瞬时锁定会抛 PermissionError，
        # 最多重试 3 次（间隔 0.5s / 1s / 1.5s）。
        last_exc = None
        for retry in range(3):
            try:
                os.replace(tmp_path, path)
                last_exc = None
                break
            except PermissionError as _pe:
                last_exc = _pe
                if retry < 2:
                    time.sleep(0.5 * (retry + 1))
                continue
            except OSError:
                raise
        if last_exc is not None:
            raise last_exc
    except Exception:
        # 写入失败时清理 .tmp，不破坏原文件
        try:
            if os.path.exists(tmp_path):
                os.remove(tmp_path)
        except OSError:
            pass
        raise


def _atomic_write_json(path, obj):
    """【P2-2 原子写入】json.dump → _atomic_write_text 的封装"""
    _atomic_write_text(path, json.dumps(obj, indent=2, ensure_ascii=False))

def save_card_key(key):
    try:
        if not key:
            # 空卡密直接删除文件，不写空文件（防止 load_card_key 读到空串误判为"无卡密"）
            clear_card_key()
            return
        encrypted = Crypto.xor(key, SIGN_KEY)
        _atomic_write_text(CARD_PATH, encrypted)
    except Exception:
        pass
    # 【修复】同时写入 auth_config.dat 作为双重备份，防止 saved_card.dat 丢失后卡密无法恢复
    try:
        manager = CardManager()
        manager.cfg["current_card"] = key.strip().replace(" ", "").upper()
        manager.save()
    except Exception:
        pass

def load_card_key():
    if os.path.isfile(CARD_PATH):
        try:
            with open(CARD_PATH, 'r', encoding='utf-8') as f:
                encrypted = f.read().strip()
            if encrypted:
                return Crypto.dxor(encrypted, SIGN_KEY)
        except Exception:
            pass
    # 【修复】saved_card.dat 不存在或为空时，回退到 auth_config.dat 中的 current_card
    # 这样即使 saved_card.dat 被清空（如心跳失败重试），卡密仍可从配置文件恢复
    try:
        mgr = CardManager()
        cc = mgr.cfg.get("current_card")
        if cc and isinstance(cc, str) and cc.strip():
            return cc.strip()
    except Exception:
        pass
    return ""

def clear_card_key():
    if os.path.isfile(CARD_PATH):
        try:
            os.remove(CARD_PATH)
        except:
            pass

def verify_license_key(key, hwid, is_heartbeat=False):
    result = check_card_core(key, hwid, is_heartbeat)
    if result.startswith("ok|"):
        parts = result.split("|")
        msg = parts[1]
        # 【修复】当服务器未返回过期时间时，返回空字符串而非REMAINING_TIME（"长期"）
        # 避免限时卡密首次激活时误显示为"长期"
        expire = parts[2] if len(parts) >= 3 else ""
        # 【修复】解析服务器返回的过期时间戳，用于更新本地配置
        expire_ts = 0
        if len(parts) >= 4 and parts[3]:
            try:
                expire_ts = int(parts[3])
            except ValueError:
                expire_ts = 0
        # 【修复】验证成功时同步更新本地配置，确保主程序启动时能正确读取
        # 无论 expire_ts 是否为 0（永久卡），都必须保存 current_card 到 auth_config.dat
        # 作为 saved_card.dat 的备份，防止 saved_card.dat 丢失后卡密无法恢复
        try:
            manager = CardManager()
            if expire_ts > 0:
                manager.cfg["expire"] = expire_ts
            manager.cfg["current_card"] = key.strip().replace(" ", "").upper()
            manager.save()
        except Exception:
            pass
        return {"ok": True, "expire": expire, "expire_ts": expire_ts, "msg": msg}
    elif result.startswith("network|"):
        return {"ok": False, "msg": result.split("|")[1], "error_type": "network"}
    elif result.startswith("error|"):
        return {"ok": False, "msg": result.split("|")[1], "error_type": "api"}
    else:
        return {"ok": False, "msg": "未知错误", "error_type": "unknown"}

def check_update():
    try:
        url = get_api_url("get_version")
        res = _safe_get(url, timeout=5, retries=0)
        server_ver = res.text.strip()

        if not server_ver or "." not in server_ver:
            return None, None

        try:
            server_ver_tuple = tuple(map(int, server_ver.split('.')))
            local_ver_tuple = tuple(map(int, LOCAL_VERSION.split('.')))
            if server_ver_tuple > local_ver_tuple:
                return server_ver, UPDATE_DOWNLOAD_URL
        except (ValueError, TypeError):
            # 版本号含非数字字符时回退到字符串比较
            if server_ver > LOCAL_VERSION:
                return server_ver, UPDATE_DOWNLOAD_URL
    except:
        pass
    return None, None

def get_notice():
    try:
        url = get_api_url("get_notice")
        response = _safe_get(url, headers={"Cache-Control": "no-cache"}, timeout=5, retries=0)
        return response.text if response.text else "暂无最新公告"
    except:
        return "未能连接到服务器获取公告"

# 硬件唯一码（绝对安全，带缓存优化启动速度）
class Hardware:
    @staticmethod
    def get_code():
        cache_path = os.path.join(BASE_DATA_DIR, "hwid.cache")
        # 优先读取缓存，避免重复计算
        if os.path.exists(cache_path):
            try:
                with open(cache_path, 'r', encoding='utf-8') as f:
                    cached = f.read().strip()
                    if len(cached) == 16:
                        return cached
            except:
                pass

        raw = None

        # 1) 瞬时读取注册表 MachineGuid：Win11 上 PowerShell+WMI 慢且已弃用，
        #    改为注册表读取（毫秒级），彻底消除启动时机器码采集导致的界面“无响应”。
        try:
            import winreg
            with winreg.OpenKey(
                    winreg.HKEY_LOCAL_MACHINE,
                    r"SOFTWARE\Microsoft\Cryptography",
                    0,
                    winreg.KEY_READ | getattr(winreg, "KEY_WOW64_64KEY", 0)) as k:
                _g, _ = winreg.QueryValueEx(k, "MachineGuid")
                if isinstance(_g, str) and _g.strip():
                    raw = _g.strip()
        except Exception:
            raw = None

        # 2) 兜底：仍走 PowerShell + WMI（-NoProfile，短超时），仅在注册表读不到时触发
        if not raw:
            try:
                if platform.system() == "Windows":
                    cpu = subprocess.check_output(
                        ["powershell", "-NoProfile", "-Command", "(Get-WmiObject Win32_Processor).ProcessorId"],
                        universal_newlines=True, stderr=subprocess.DEVNULL,
                        creationflags=subprocess.CREATE_NO_WINDOW, timeout=8
                    ).strip()
                    disk = subprocess.check_output(
                        ["powershell", "-NoProfile", "-Command", "(Get-WmiObject Win32_DiskDrive).SerialNumber"],
                        universal_newlines=True, stderr=subprocess.DEVNULL,
                        creationflags=subprocess.CREATE_NO_WINDOW, timeout=8
                    ).strip()
                    raw = "_".join([cpu, disk])
                else:
                    raw = "_".join([platform.node(), platform.processor()])
            except Exception:
                raw = None

        if raw:
            code = hashlib.sha256(raw.encode('utf-8')).hexdigest().upper()[:16]
        else:
            code = hashlib.sha256(b"fallback_hardware_code").hexdigest().upper()[:16]

        try:
            with open(cache_path, 'w', encoding='utf-8') as f:
                f.write(code)
        except Exception:
            pass
        return code

# 加密存储
# =============【S1 AES-GCM 升级：工具函数/常量】=============
# 新增的加密基础设施：XOR -> AES-GCM，机器码派生密钥
# 前缀标识：写入时统一加前缀，读取时根据前缀判断算法，100% 兼容旧 XOR 数据
_CRYPTO_AES_PREFIX = "A2"   # 只要文件开头是 A2 就是 AES-GCM 格式

def _have_crypto_lib():
    """lazy check: cryptography 库是否可用"""
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM  # noqa: F401
        return True
    except Exception:
        return False

def _derive_storage_key() -> bytes:
    """基于机器码派生 32 字节 AES-256 密钥。
    跨机器数据无法解密（机器绑定）；不会被硬编码 SIGN_KEY/ENCRYPT_KEY 影响。"""
    try:
        try:
            machine = Hardware.get_code()
        except Exception:
            machine = ""
        if not machine:
            try:
                import platform
                machine = platform.node() + "|" + platform.machine()
            except Exception:
                machine = "lingshu_fallback"
    except Exception:
        machine = "lingshu_fallback"
    raw = ("_lingshu_storage_v2_|" + machine).encode("utf-8")
    try:
        import hashlib
        k = hashlib.sha256(raw).digest()
        for _ in range(5000):
            k = hashlib.sha256(k).digest()
        return k  # 32 bytes
    except Exception:
        # 最终兜底：sha256 不可用就截断到 32 bytes（极端场景）
        padded = (raw * 3)[:32]
        if len(padded) < 32:
            padded = padded + b"\x00" * (32 - len(padded))
        return padded

def _aes_encrypt_bytes(plaintext: bytes, key32: bytes) -> str:
    """AES-256-GCM 加密 bytes -> base64(nonce||ciphertext||tag)
    需要 cryptography 库；失败抛异常让调用方回退 XOR。"""
    import os, base64
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    nonce = os.urandom(12)
    aes = AESGCM(key32)
    ct = aes.encrypt(nonce, plaintext, b"lingshu-storage-v2")
    return base64.b64encode(nonce + ct).decode("ascii")

def _aes_decrypt_bytes(b64payload: str, key32: bytes) -> bytes:
    """AES-256-GCM 解密 -> bytes。失败抛异常（tag 不合法 / 非 AES 数据 / 机器不匹配）。"""
    import base64
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    blob = base64.b64decode(b64payload)
    nonce, ct = blob[:12], blob[12:]
    aes = AESGCM(key32)
    return aes.decrypt(nonce, ct, b"lingshu-storage-v2")

# =============【S1 AES-GCM 升级：Crypto 类重写】=============
class Crypto:
    @staticmethod
    def xor(data, key):
        """对外仍叫 xor()；内部优先 AES-GCM，失败回退旧字符级 XOR。
        加密密钥：AES 路径用机器码派生 storage_key；旧 XOR 路径使用入参 key（语义保留）。

        数据序列化策略（与 dxor 配合保证「历史文件 + 新文件」都能解）：
          - dict/list 等结构化数据 → 始终 json.dumps 再加密（与 CardManager 的历史实现一致）。
          - str 类型 → 直接按字符级 XOR，不包 JSON，确保 save_card_key 写入的 saved_card.dat
            与「未升级前原生 xor 字符串」的旧文件字节一致，做到真正无缝回读。
        """
        # 尝试 AES-GCM：只有结构化数据 / 需要 JSON 封装的类型走这里，纯字符串不强制包 JSON 以免破坏旧格式
        try:
            if _have_crypto_lib():
                if isinstance(data, (dict, list, tuple, bool, int, float)) or data is None:
                    raw = json.dumps(data, ensure_ascii=False)
                    k = _derive_storage_key()
                    b64 = _aes_encrypt_bytes(raw.encode("utf-8"), k)
                    return _CRYPTO_AES_PREFIX + b64
                # 纯字符串：同样也支持 AES（多加一道 AES2: 前缀 JSON 包装），同时旧 XOR 保持字节兼容
                if isinstance(data, str):
                    raw = json.dumps(data, ensure_ascii=False)
                    k = _derive_storage_key()
                    b64 = _aes_encrypt_bytes(raw.encode("utf-8"), k)
                    return _CRYPTO_AES_PREFIX + b64
        except Exception:
            pass
        # 回退：原始字符级 XOR；字符串按字节直接 XOR，不包 JSON（与历史 saved_card.dat 字节兼容）
        if isinstance(data, (dict, list, tuple, bool, int, float)) or data is None:
            d = json.dumps(data, ensure_ascii=False)
        else:
            d = str(data)
        out = []
        for i, c in enumerate(d):
            out.append(chr(ord(c) ^ ord(key[i % len(key)])))
        return "".join(out)

    @staticmethod
    def dxor(data, key):
        """A2 前缀优先走 AES；失败回退旧字符级 XOR；对 XOR 解密结果再做「JSON 优先、字符串兜底」。
        这样：
          - 新 AES 文件：json.loads 成功 → 返回 dict/str/list 等 Python 对象
          - 旧结构化 XOR 文件：json.loads 成功 → 返回 dict/list
          - 旧 saved_card.dat 纯字符串密文：json.loads 失败 → 返回解密后的原始字符串，
            保证 load_card_key 不再因为异常被吞而返回空串，历史卡密能自动回填。
        """
        import traceback
        if isinstance(data, str) and data.startswith(_CRYPTO_AES_PREFIX):
            try:
                if _have_crypto_lib():
                    payload = data[len(_CRYPTO_AES_PREFIX):]
                    k = _derive_storage_key()
                    raw = _aes_decrypt_bytes(payload, k)
                    return json.loads(raw.decode("utf-8"))
            except Exception:
                pass  # AES 解不开，继续尝试旧 XOR 兼容
        # 原始字符级 XOR（同时兜底无前缀 或 AES 失败后降级）
        try:
            out = []
            for i, c in enumerate(data):
                out.append(chr(ord(c) ^ ord(key[i % len(key)])))
            decoded = "".join(out)
        except Exception as _e:
            debug_print(f"[Crypto.dxor] 字符级 XOR 解密失败: {_e}\n{traceback.format_exc()}")
            raise

        try:
            # 策略：先按 JSON 解析（dict/list/字符串 JSON 都能过），失败就返回原始字符串（兼容旧 saved_card.dat）
            return json.loads(decoded)
        except Exception:
            # JSON 解析失败常见两种：
            #  1) 真正被篡改/解错的密文 → 内容无意义，交给上层 CardManager.isinstance(data,dict) 之类判断
            #  2) 历史 saved_card.dat：直接 XOR 明文卡密字符串 → 不是合法 JSON，返回 raw 字符串
            # 为了便于以后排查，这里只在可疑长度时打日志
            try:
                if decoded is not None and len(str(decoded)) > 0 and len(str(decoded)) < 200:
                    _hint = repr(decoded[:20]) if isinstance(decoded, str) else repr(type(decoded))
                    debug_print(f"[Crypto.dxor] JSON 解析失败，按 raw 返回（可能是历史纯字符串）len={len(decoded) if isinstance(decoded, str) else '?'} preview={_hint}")
            except Exception:
                pass
            return decoded

    @staticmethod
    def xor_binary(data: bytes, key: bytes) -> bytes:
        return bytes(b ^ key[i % len(key)] for i, b in enumerate(data))

# 【修复】卡密管理
class CardManager:
    def __init__(self):
        self.machine = Hardware.get_code()
        self.cfg = self.load()
        # 【安全修复】加载独立的卡密历史记录文件
        self._load_card_history()

    def _load_card_history(self):
        """【安全修复】加载独立的卡密历史记录，防止删除配置文件后卡密可以再次激活"""
        self.card_history = set()
        try:
            if os.path.exists(CARD_HISTORY_PATH):
                with open(CARD_HISTORY_PATH, 'r', encoding='utf-8') as f:
                    data = Crypto.dxor(f.read(), ENCRYPT_KEY)
                    if isinstance(data, list):
                        self.card_history = set(data)
                    elif isinstance(data, dict) and "cards" in data:
                        self.card_history = set(data["cards"])
        except Exception:
            import traceback as _tb
            debug_print(f"[CardManager._load_card_history] 加载失败：{_tb.format_exc()}")

    def _save_card_history(self):
        """【安全修复】保存独立的卡密历史记录"""
        try:
            _atomic_write_text(CARD_HISTORY_PATH, Crypto.xor({"cards": list(self.card_history)}, ENCRYPT_KEY))
        except Exception:
            import traceback as _tb
            debug_print(f"[CardManager._save_card_history] 保存失败：{_tb.format_exc()}")

    def load(self):
        if not os.path.exists(CONFIG_PATH):
            return {
                "schema_version": CARD_CFG_SCHEMA_VERSION,
                "machine": self.machine,
                "current_card": None,
                "expire": 0,
            }
        try:
            with open(CONFIG_PATH, 'r', encoding='utf-8') as f:
                data = Crypto.dxor(f.read(), ENCRYPT_KEY)
            # 【T3 schema 迁移】无论 machine 是否匹配，只要是 dict 就尝试迁移，避免历史版本数据被直接丢弃
            migrated_data, changed = migrate_card_cfg(data if isinstance(data, dict) else {}, self.machine)
            if migrated_data.get("machine") != self.machine:
                return {
                    "schema_version": CARD_CFG_SCHEMA_VERSION,
                    "machine": self.machine,
                    "current_card": None,
                    "expire": 0,
                }
            # 兼容旧数据格式：migrate_card_cfg 已做 card→current_card
            # 【安全修复】不再从主配置读取历史记录，使用独立文件
            if changed:
                try:
                    # 迁移后立刻回写（已匹配机器码的前提下）—— 使用原子写入
                    import copy as _copy
                    save_cfg = _copy.deepcopy(migrated_data)
                    _atomic_write_text(CONFIG_PATH, Crypto.xor(save_cfg, ENCRYPT_KEY))
                except Exception:
                    import traceback as _tb
                    debug_print(f"[CardManager.load] 迁移后回写失败：{_tb.format_exc()}")
            return migrated_data
        except Exception:
            import traceback as _tb
            debug_print(f"[CardManager.load] 加载失败：{_tb.format_exc()}")
            return {
                "schema_version": CARD_CFG_SCHEMA_VERSION,
                "machine": self.machine,
                "current_card": None,
                "expire": 0,
            }

    def save(self):
        try:
            if isinstance(self.cfg, dict):
                self.cfg.setdefault("schema_version", CARD_CFG_SCHEMA_VERSION)
                # save 时同步一次迁移（防止 load 没触发迁移就直接改字段）
                _tmp, _changed = migrate_card_cfg(self.cfg, self.machine)
                if _changed:
                    self.cfg = _tmp
            # 【P2-4 防御】如果 cfg 缺少 expire 和 current_card 两个关键字段，
            # 但磁盘上已有配置文件，说明 cfg 可能被损坏（dxor 返回了异常值），
            # 此时写回会抹掉原有卡密数据 → 拒绝写入并记录日志
            if not isinstance(self.cfg, dict) or (
                "expire" not in self.cfg and "current_card" not in self.cfg
            ):
                if os.path.exists(CONFIG_PATH):
                    import traceback as _tb
                    debug_print(f"[CardManager.save] 拒绝写入空配置（cfg 缺少 expire/current_card），保护已有数据：{_tb.format_exc()}")
                    return
            # 【P2-2 原子写入】先写 .tmp 再 os.replace
            _atomic_write_text(CONFIG_PATH, Crypto.xor(self.cfg, ENCRYPT_KEY))
        except Exception:
            import traceback as _tb
            debug_print(f"[CardManager.save] 保存失败：{_tb.format_exc()}")

    def remain(self):
        return max(0, self.cfg["expire"] - get_safe_time())

    def expired(self):
        """检查是否已过期（区分未激活和已过期状态）"""
        # 如果从未激活过（expire为0且current_card为None），返回False
        if self.cfg.get("expire", 0) == 0 and self.cfg.get("current_card") is None:
            return False
        return self.remain() == 0

    def get_last_card(self):
        """获取上一次使用的卡密"""
        return self.cfg.get("current_card", "")

    def is_card_used(self, card: str) -> bool:
        """【安全修复】检查卡密是否已被使用过（在独立历史记录文件中）"""
        return card in self.card_history

    def parse_secure_card(self, card):
        """解析卡密并验证机器码绑定 - 防止卡密在其他机器上激活"""
        card = card.strip().replace(" ", "").upper()
        if len(card) != 32:
            return 0
        seed = card[:16]
        chk = card[16:]
        
        # 【安全修复】验证卡密是否绑定当前机器
        # 卡密格式：SEED(16位)_HOURS_MASTER_KEY_MACHINE_CODE 的哈希
        for h in POSSIBLE_HOURS:
            # 尝试带机器码的验证（新格式）
            s_with_machine = f"{seed}_{h}_{MASTER_KEY}_{self.machine}"
            hv_with_machine = hashlib.sha256(s_with_machine.encode() + HASH_SALT).hexdigest().upper()[:16]
            
            # 尝试不带机器码的验证（兼容旧格式）
            s_without_machine = f"{seed}_{h}_{MASTER_KEY}"
            hv_without_machine = hashlib.sha256(s_without_machine.encode() + HASH_SALT).hexdigest().upper()[:16]
            
            if hv_with_machine == chk:
                # 新格式：带机器码绑定，只能在当前机器使用
                return h
            elif hv_without_machine == chk:
                # 旧格式：不带机器码绑定，允许使用但记录警告
                # 【安全修复】旧格式卡密禁止使用，必须重新生成带机器码的卡密
                return 0
        
        return 0

    def activate(self, card):
        """【安全修复】激活新卡密：严格检查历史记录，防止过期卡密复用，必须连接服务器验证"""
        card = card.strip().replace(" ", "").upper()
        h = self.parse_secure_card(card)
        
        if h <= 0:
            return False, "卡密无效或已失效"
        
        # 【安全修复】严格检查：只要在独立历史记录文件中，一律拒绝
        if self.is_card_used(card):
            return False, "该卡密已使用过，无法重复激活"

        # 【安全修复】强制连接服务器验证卡密有效性
        verify_result = verify_license_key(card, self.machine, is_heartbeat=False)
        if not verify_result.get("ok"):
            return False, verify_result.get("msg", "卡密验证失败")

        now = get_safe_time()
        rem = self.remain()
        
        # 【安全修复】将当前卡密（如果有）加入独立历史记录文件
        old_card = self.cfg.get("current_card")
        if old_card and old_card not in self.card_history:
            self.card_history.add(old_card)

        # 计算新的过期时间（优先使用服务器返回的过期时间戳）
        expire_ts = verify_result.get("expire_ts", 0)
        if expire_ts > 0:
            self.cfg["expire"] = expire_ts
        else:
            self.cfg["expire"] = now + rem + h * 3600
        
        self.cfg["current_card"] = card
        
        # 【安全修复】新卡密也立即加入独立历史记录文件，防止重复粘贴
        self.card_history.add(card)
        
        # 【安全修复】同时保存主配置和独立历史记录文件
        self.save()
        self._save_card_history()
        return True, f"激活成功！剩余：{self.format_time(self.remain())}"

    def verify_login(self, card):
        """验证登录：检查卡密是否匹配、是否过期"""
        card = card.strip().replace(" ", "").upper()
        
        if self.cfg.get("current_card") != card:
            return False, "卡密不匹配，请重新激活"
        
        if self.expired():
            return False, "卡密已过期，请重新激活"
        
        return True, f"登录成功！剩余：{self.format_time(self.remain())}"

    def format_time(self, s):
        d = s // 86400
        h = (s % 86400) // 3600
        m = (s % 3600) // 60
        return f"{d}天{h}时{m}分"

    def can_use_trial(self):
        """检查是否可以使用免费试用"""
        trial_check_paths = [
            TRIAL_PATH,
            os.path.join(os.path.expanduser("~"), ".lingshu_trial.dat"),
            os.path.join(os.path.expanduser("~"), "AppData", "Roaming", "lingshu", "trial.dat"),
            # 排除 sys.executable 路径，PyInstaller 模式下这是临时目录，可能误匹配其他用户的文件
        ]
        
        for path in trial_check_paths:
            if os.path.exists(path):
                try:
                    with open(path, 'r', encoding='utf-8') as f:
                        data = Crypto.dxor(f.read(), ENCRYPT_KEY)
                        if isinstance(data, dict) and data.get("machine") == self.machine:
                            return False, "您已使用过免费试用"
                except:
                    try:
                        with open(path, 'r', encoding='utf-8') as f:
                            content = f.read()
                            if self.machine in content:
                                return False, "您已使用过免费试用"
                    except:
                        pass
        
        return True, ""

    def activate_trial(self):
        """激活免费试用（3天）- 必须验证网络时间"""
        try:
            # 【安全修复】试用激活必须验证网络时间，防止用户修改系统时间绕过
            net_time = get_network_time()
            if not net_time:
                return False, "无法连接服务器获取时间，请检查网络后重试"
            
            now = net_time
            trial_info = {
                "machine": self.machine,
                "start_time": now,
                "days": TRIAL_DAYS
            }
            encrypted_data = Crypto.xor(trial_info, ENCRYPT_KEY)
            
            trial_save_paths = [
                TRIAL_PATH,
                os.path.join(os.path.expanduser("~"), ".lingshu_trial.dat")
            ]
            
            for path in trial_save_paths:
                try:
                    os.makedirs(os.path.dirname(path), exist_ok=True)
                    with open(path, 'w', encoding='utf-8') as f:
                        f.write(encrypted_data)
                except:
                    pass
            
            self.cfg["current_card"] = f"TRIAL_{self.machine[:8]}"
            self.cfg["expire"] = now + TRIAL_DAYS * 86400
            self.save()
            return True, f"免费试用激活成功！您可以使用{TRIAL_DAYS}天"
        except Exception as e:
            return False, f"试用激活失败: {str(e)}"

    def check_trial_status(self):
        """检查试用状态"""
        if not os.path.exists(TRIAL_PATH):
            return None
        
        try:
            with open(TRIAL_PATH, 'r', encoding='utf-8') as f:
                data = Crypto.dxor(f.read(), ENCRYPT_KEY)
                if isinstance(data, dict) and data.get("machine") == self.machine:
                    expire_time = data.get("start_time", 0) + data.get("days", 0) * 86400
                    now = get_safe_time()
                    remaining = expire_time - now
                    if remaining > 0:
                        return {"active": True, "remaining": remaining}
                    else:
                        return {"active": False, "remaining": 0}
        except:
            pass
        return None

# 【统一】静态八卦图绘制函数
def draw_static_bagua(painter, cx, cy, r):
    """绘制静态的、标准的八卦图"""
    painter.setPen(Qt.PenStyle.NoPen)
    
    # 1. 绘制外圆
    painter.setBrush(QColor(255, 255, 255))
    painter.drawEllipse(cx - r, cy - r, 2 * r, 2 * r)
    
    # 2. 绘制右侧黑色区域 (S形)
    painter.setBrush(QColor(0, 0, 0))
    painter.drawChord(cx - r, cy - r, 2 * r, 2 * r, 90 * 16, 180 * 16)
    painter.drawEllipse(cx - r // 2, cy - r, r, r)
    
    # 3. 绘制下半部分白色半圆
    painter.setBrush(QColor(255, 255, 255))
    painter.drawEllipse(cx - r // 2, cy, r, r)
    
    # 4. 绘制鱼眼
    painter.setBrush(QColor(0, 0, 0))
    painter.drawEllipse(cx - 5, cy + r // 2 - 5, 10, 10)
    painter.setBrush(QColor(255, 255, 255))
    painter.drawEllipse(cx - 5, cy - r // 2 - 5, 10, 10)

# 纯净旋转八卦图 (用于登录页和欢迎页) - 使用 QTimer 彻底避免属性问题
class RotatingTaiChi(QLabel):
    def __init__(self, parent=None, size=150):
        super().__init__(parent)
        self.setMinimumSize(size, size)
        self._rotation_angle = 0.0
        self._start_time = None
        
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        
        self.timer = QTimer(self)
        self.timer.timeout.connect(self._update_rotation)
        self.timer.start(16)

    def _update_rotation(self):
        import time
        if self._start_time is None:
            self._start_time = time.time()
        elapsed = time.time() - self._start_time
        self._rotation_angle = (elapsed % 12.0) / 12.0 * 360.0
        self.update()

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        rect = self.rect()
        w, h = rect.width(), rect.height()
        r = min(w, h) // 2 - 10
        cx, cy = w // 2, h // 2

        p.save()
        p.translate(cx, cy)
        p.rotate(self._rotation_angle)
        p.translate(-cx, -cy)

        # 使用统一绘制函数
        draw_static_bagua(p, cx, cy, r)
        
        p.restore()
        p.end()

# 【修改】静态八卦Logo (用于登录页和小窗口)
class StaticTaiChiLogo(QLabel):
    def __init__(self, parent=None, size=260):
        super().__init__(parent)
        self.setMinimumSize(size, size)
        self.setStyleSheet("background-color:#0a0a0a; border-radius:{}px;".format(size//2))

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        rect = self.rect()
        w, h = rect.width(), rect.height()
        r = min(w, h) // 2 - 12
        cx, cy = w // 2, h // 2

        p.save()
        # 不旋转，直接使用统一绘制函数
        draw_static_bagua(p, cx, cy, r)
        p.restore()
        p.end()

# 安全加载Pixmap，支持中文路径和嵌入图像
def load_pixmap_safe(path: str) -> QPixmap:
    """【修复】增强版图像加载，支持嵌入图像和各种情况"""
    # 首先尝试从嵌入图像加载
    if path:
        embedded_img = get_embedded_image(path)
        if embedded_img is not None:
            img_rgb = cv2.cvtColor(embedded_img, cv2.COLOR_BGR2RGB)
            h, w, ch = img_rgb.shape
            bytes_per_line = ch * w
            qt_img = QImage(img_rgb.tobytes(), w, h, bytes_per_line, QImage.Format.Format_RGB888)
            return QPixmap.fromImage(qt_img)
    
    if not path or not os.path.exists(path):
        return QPixmap()
    try:
        # 方法1：直接读取文件流
        with open(path, 'rb') as f:
            data = f.read()
        pixmap = QPixmap()
        if pixmap.loadFromData(data):
            return pixmap
        
        # 方法2：尝试用OpenCV读取再转换
        img_cv = cv2.imdecode(np.fromfile(path, dtype=np.uint8), cv2.IMREAD_COLOR)
        if img_cv is not None:
            img_rgb = cv2.cvtColor(img_cv, cv2.COLOR_BGR2RGB)
            h, w, ch = img_cv.shape
            bytes_per_line = ch * w
            qt_img = QImage(img_rgb.tobytes(), w, h, bytes_per_line, QImage.Format.Format_RGB888)
            return QPixmap.fromImage(qt_img)
            
        return QPixmap()
    except Exception as e:
        debug_print(f"[Debug] 加载图片失败 {path}: {e}")
        return QPixmap()

