# ============================================================
#  自绘按钮: hover动画 + 状态模式 (登录中/成功)
# ============================================================
class HoverButton(QPushButton):

    hovered = Signal()

    def __init__(self, text, colors_normal, colors_hover,
                 radius=10, font_px=14, font_weight=50,
                 fixed_height=42, fixed_width=None,
                 mid_stop=0.5,
                 shadow_color=QColor(139, 92, 246, 89),
                 shadow_blur=14, shadow_offset=4,
                 press_scale=0.97,
                 parent=None):
        super().__init__(parent)
        self.setText(text)
        self.setFixedHeight(fixed_height)
        if fixed_width is not None:
            self.setFixedWidth(fixed_width)
        self.setCursor(Qt.CursorShape.PointingHandCursor)

        self._c_normal = colors_normal
        self._c_hover = colors_hover
        self._radius = radius
        self._font_px = font_px
        self._font_weight = font_weight
        self._mid_stop = mid_stop
        self._press_scale = press_scale

        self._hover_t = 0.0
        self._target_hover = 0.0
        self._press_t = 0.0
        self._target_press = 0.0

        self._shadow = QGraphicsDropShadowEffect()
        self._shadow.setBlurRadius(shadow_blur)
        self._shadow.setColor(QColor(shadow_color))
        self._shadow.setOffset(0, shadow_offset)
        self.setGraphicsEffect(self._shadow)
        self._sh_blur = shadow_blur
        self._sh_offset = shadow_offset
        self._sh_color = QColor(shadow_color)

        self._timer = QTimer(self)
        self._timer.setInterval(16)
        self._timer.timeout.connect(self._anim_step)

        # 状态模式 (登录中/成功)
        self._in_status = False
        self._status_text = None
        self._status_colors = None

    # --- 状态模式 ---
    def set_status(self, text, colors=None):
        """在按钮内显示状态文字 (如 '登录中...' / '登录成功')"""
        self._in_status = True
        self._status_text = text
        self._status_colors = colors
        self.setEnabled(False)
        self._hover_t = 0.0
        self._target_hover = 0.0
        self._press_t = 0.0
        self._target_press = 0.0
        self._update_shadow()
        self.update()

    def clear_status(self):
        """恢复正常按钮状态"""
        self._in_status = False
        self._status_text = None
        self._status_colors = None
        self.setEnabled(True)
        self.update()

    # --- 动画步进 ---
    def _anim_step(self):
        if self._in_status:
            self._timer.stop()
            return

        speed = 0.12
        changed = False

        dh = self._target_hover - self._hover_t
        if abs(dh) > 0.003:
            self._hover_t += dh * speed
            changed = True
        else:
            self._hover_t = self._target_hover

        dp = self._target_press - self._press_t
        if abs(dp) > 0.003:
            self._press_t += dp * (speed * 1.5)
            changed = True
        else:
            self._press_t = self._target_press

        if self._step_shine():
            changed = True

        if changed:
            self._update_shadow()
            self.update()
        else:
            self._timer.stop()

    def _step_shine(self):
        return False

    def _update_shadow(self):
        t = self._hover_t
        self._shadow.setBlurRadius(self._sh_blur + 6 * t)
        self._shadow.setOffset(0, self._sh_offset + 2 * t)
        c = self._sh_color
        self._shadow.setColor(QColor(
            c.red(), c.green(), c.blue(),
            min(255, int(c.alpha() + 30 * t))
        ))

    # --- 事件 ---
    def enterEvent(self, event):
        if self._in_status:
            return
        self._target_hover = 1.0
        self._on_enter()
        self.hovered.emit()
        if not self._timer.isActive():
            self._timer.start()
        super().enterEvent(event)

    def _on_enter(self):
        pass

    def leaveEvent(self, event):
        if self._in_status:
            return
        self._target_hover = 0.0
        if not self._timer.isActive():
            self._timer.start()
        super().leaveEvent(event)

    def mousePressEvent(self, event):
        if self._in_status:
            return
        if event.button() == Qt.MouseButton.LeftButton:
            self._target_press = 1.0
            if not self._timer.isActive():
                self._timer.start()
        super().mousePressEvent(event)

    def mouseReleaseEvent(self, event):
        if self._in_status:
            return
        if event.button() == Qt.MouseButton.LeftButton:
            self._target_press = 0.0
            if not self._timer.isActive():
                self._timer.start()
        super().mouseReleaseEvent(event)

    # --- 绘制 ---
    @staticmethod
    def _lerp(c1, c2, t):
        return QColor(
            int(c1[0] + (c2[0] - c1[0]) * t),
            int(c1[1] + (c2[1] - c1[1]) * t),
            int(c1[2] + (c2[2] - c1[2]) * t)
        )

    def paintEvent(self, _event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)

        w, h = self.width(), self.height()

        if self._in_status:
            sc = self._status_colors
            if sc:
                c1, c2, c3 = QColor(*sc[0]), QColor(*sc[1]), QColor(*sc[2])
            else:
                c1 = self._lerp(self._c_normal[0], self._c_hover[0], 0)
                c2 = self._lerp(self._c_normal[1], self._c_hover[1], 0)
                c3 = self._lerp(self._c_normal[2], self._c_hover[2], 0)
            text = self._status_text or self.text()
            t = 0.0
            scale = 1.0
            tx = ty = 0
        else:
            t = self._hover_t
            c1 = self._lerp(self._c_normal[0], self._c_hover[0], t)
            c2 = self._lerp(self._c_normal[1], self._c_hover[1], t)
            c3 = self._lerp(self._c_normal[2], self._c_hover[2], t)
            text = self.text()
            scale = 1.0 - (1.0 - self._press_scale) * self._press_t
            tx = w * (1 - scale) / 2
            ty = h * (1 - scale) / 2

        p.translate(tx, ty - 2 * t)
        p.scale(scale, scale)

        path = QPainterPath()
        path.addRoundedRect(QRectF(0.5, 0.5, w - 1, h - 1), self._radius, self._radius)
        p.setClipPath(path)

        grad = QLinearGradient(0, 0, w, h)
        grad.setColorAt(0, c1)
        grad.setColorAt(self._mid_stop, c2)
        grad.setColorAt(1, c3)
        p.fillRect(QRectF(0, 0, w, h), grad)

        p.fillRect(QRectF(0, 0, w, 1.5), QColor(255, 255, 255, int(38 + 13 * t)))

        if not self._in_status:
            self._paint_shine(p, w, h)

        p.setClipping(False)

        p.setPen(QColor(255, 255, 255))
        font = QFont("Microsoft YaHei")
        font.setPixelSize(self._font_px)
        font.setWeight(QFont.Weight(self._font_weight))
        font.setStyleStrategy(QFont.StyleStrategy.PreferAntialias)
        p.setFont(font)
        p.drawText(QRectF(0, 0, w, h), Qt.AlignmentFlag.AlignCenter, text)

    def _paint_shine(self, p, w, h):
        pass


# ============================================================
#  登录按钮: 额外光泽扫过
# ============================================================
class ShineButton(HoverButton):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._shine_t = 0.0
        self._shine_active = False

    def _on_enter(self):
        self._shine_t = 0.0
        self._shine_active = True

    def _step_shine(self):
        if self._shine_active:
            self._shine_t += 0.028
            if self._shine_t >= 1.0:
                self._shine_t = 1.0
                self._shine_active = False
            return True
        return False

    def _paint_shine(self, p, w, h):
        if self._shine_t <= 0 or self._shine_t >= 1.0:
            return
        shine_left = -w + self._shine_t * 2 * w
        shine_right = shine_left + w
        grad = QLinearGradient(shine_left, 0, shine_right, 0)
        grad.setColorAt(0, QColor(255, 255, 255, 0))
        grad.setColorAt(0.5, QColor(255, 255, 255, 64))
        grad.setColorAt(1, QColor(255, 255, 255, 0))
        p.fillRect(QRectF(0, 0, w, h), grad)


# ============================================================
#  Toast 提示弹窗
# ============================================================
class ToastLabel(QWidget):

    def __init__(self, parent=None):
        super().__init__(parent)
        self._label = QLabel(self)
        self._label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.setFixedSize(260, 40)

        self._anim = QPropertyAnimation(self, b"pos")
        self._anim.setDuration(350)
        self._anim.setEasingCurve(QEasingCurve.Type.OutCubic)

        self._hide_timer = QTimer(self)
        self._hide_timer.setSingleShot(True)
        self._hide_timer.timeout.connect(self._slide_out)

        self._y_hidden = 0
        self._y_shown = 0

    def show_toast(self, text, toast_type="info"):
        colors = {
            "success": ("#10B981", "#059669"),
            "error":   ("#EF4444", "#DC2626"),
            "info":    ("#6366F1", "#8B5CF6"),
        }
        c1, c2 = colors.get(toast_type, colors["info"])
        self._label.setStyleSheet(f"""
            QLabel {{
                background-color: qlineargradient(x1:0, y1:0, x2:1, y2:1,
                    stop:0 {c1}, stop:1 {c2});
                color: white; border: none; border-radius: 8px;
                font-size: 14px; font-weight: 400; padding: 0 24px;
            }}
        """)
        self._label.setText(text)
        self._label.setFixedSize(self.width(), self.height())

        parent_h = self.parent().height()
        self._y_hidden = -40
        self._y_shown = 6

        parent_w = self.parent().width()
        x = (parent_w - self.width()) // 2
        self.move(x, self._y_hidden)
        self.show()
        self.raise_()

        self._anim.stop()
        self._anim.setStartValue(self.pos())
        self._anim.setEndValue(QPointF(x, self._y_shown))
        self._anim.start()

        self._hide_timer.stop()
        self._hide_timer.start(2500)

    def _slide_out(self):
        x = self.pos().x()
        self._anim.stop()
        self._anim.setStartValue(self.pos())
        self._anim.setEndValue(QPointF(x, self._y_hidden))
        self._anim.start()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._label.setGeometry(0, 0, self.width(), self.height())


# ============================================================
#  更多选项卡片 (自绘渐变背景 + 玻璃效果)
# ============================================================
class MoreCard(QWidget):

    def paintEvent(self, _event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)

        w, h = self.width(), self.height()

        for i in range(3):
            expand = (i + 1) * 3
            alpha = 22 - i * 6
            if alpha <= 0:
                break
            path = QPainterPath()
            path.addRoundedRect(
                QRectF(-expand, -expand, w + expand * 2, h + expand * 2),
                20 + expand, 20 + expand
            )
            painter.fillPath(path, QColor(0, 0, 0, alpha))

        path = QPainterPath()
        path.addRoundedRect(QRectF(0, 0, w, h), 20, 20)
        painter.setClipPath(path)

        grad = QLinearGradient(0, 0, w, h)
        grad.setColorAt(0.0, QColor(109, 213, 250))
        grad.setColorAt(0.45, QColor(139, 92, 246))
        grad.setColorAt(1.0, QColor(168, 85, 247))
        painter.fillRect(QRectF(0, 0, w, h), grad)

        painter.fillRect(QRectF(0, 0, w, h), QColor(255, 255, 255, 31))
        painter.fillRect(QRectF(0, 0, w, 2), QColor(255, 255, 255, 51))
        painter.fillRect(QRectF(0, h - 2, w, 2), QColor(0, 0, 0, 8))

        painter.setClipping(False)
        painter.setPen(QPen(QColor(255, 255, 255, 64), 1))
        painter.drawPath(path)


# ============================================================
#  更多选项面板 (窗口内居中覆盖层)
# ============================================================
class MoreOptionsPanel(QWidget):

    CARD_W = 340
    CARD_H = 260

    def __init__(self, parent, confirm_cn=None, confirm_ch=None):
        super().__init__(parent)
        self._cn = confirm_cn or [(139, 92, 246), (168, 85, 247), (217, 70, 239)]
        self._ch = confirm_ch or [(124, 58, 237), (147, 51, 210), (192, 35, 211)]
        self.hide()
        self._build_ui()

    def _build_ui(self):
        self.card = MoreCard(self)
        self.card.setFixedSize(self.CARD_W, self.CARD_H)

        layout = QVBoxLayout(self.card)
        layout.setContentsMargins(24, 20, 24, 18)
        layout.setSpacing(14)

        title = QLabel("更多选项")
        title.setStyleSheet(
            "font-size: 15px; font-weight: 500; color: #000000; "
            "background: transparent; border: none;"
        )
        layout.addWidget(title)

        layout.addLayout(self._build_machine_code_row())
        layout.addLayout(self._build_input_row())
        layout.addStretch()

        sep = QFrame()
        sep.setFixedHeight(1)
        sep.setStyleSheet("background-color: rgba(0,0,0,50); border: none;")
        layout.addWidget(sep)

        layout.addSpacing(4)
        layout.addLayout(self._build_button_row())

    def _build_machine_code_row(self):
        row = QHBoxLayout()
        row.setSpacing(10)

        lbl = QLabel("机器码:")
        lbl.setStyleSheet(
            "font-size: 13px; font-weight: 400; color: rgba(0,0,0,200); "
            "background: transparent; border: none;"
        )
        lbl.setFixedHeight(38)
        row.addWidget(lbl)

        frame = QFrame()
        frame.setFixedHeight(38)
        frame.setStyleSheet("""
            QFrame {
                background-color: rgba(255, 255, 255, 217);
                border: 1px solid rgba(255, 255, 255, 102);
                border-radius: 8px;
            }
        """)

        f_layout = QHBoxLayout(frame)
        f_layout.setContentsMargins(14, 0, 8, 0)
        f_layout.setSpacing(8)

        self._machine_code = self._gen_machine_code()
        masked = self._mask_code(self._machine_code)

        code_lbl = QLabel(masked)
        code_lbl.setStyleSheet(
            "font-size: 13px; font-weight: 400; color: #333333; "
            "background: transparent; border: none;"
        )
        code_lbl.setFixedHeight(38)
        f_layout.addWidget(code_lbl, 1)

        self.btn_copy = HoverButton(
            "复制",
            [(20, 184, 166), (13, 148, 136), (15, 118, 110)],
            [(16, 152, 142), (10, 128, 118), (12, 100, 92)],
            radius=6, font_px=12, font_weight=50,
            fixed_height=28, fixed_width=48,
            shadow_color=QColor(20, 184, 166, 60),
            shadow_blur=8, shadow_offset=2,
        )
        f_layout.addWidget(self.btn_copy)

        row.addWidget(frame, 1)

        self.btn_copy.clicked.connect(self._on_copy_code)

        return row

    def _gen_machine_code(self):
        """使用父窗口的 hwid 作为机器码"""
        parent = self.parent()
        if parent and hasattr(parent, 'hwid'):
            return parent.hwid
        return ""

    @staticmethod
    def _mask_code(code):
        if len(code) <= 12:
            return code
        return code[:8] + "****" + code[-4:]

    def _build_input_row(self):
        row = QHBoxLayout()
        row.setSpacing(10)

        lbl = QLabel("续费时长:")
        lbl.setStyleSheet(
            "font-size: 13px; font-weight: 400; color: rgba(0,0,0,200); "
            "background: transparent; border: none;"
        )
        lbl.setFixedHeight(38)
        row.addWidget(lbl)

        frame = QFrame()
        frame.setFixedHeight(38)
        frame.setStyleSheet("""
            QFrame {
                background-color: rgba(255, 255, 255, 217);
                border: 1px solid rgba(255, 255, 255, 102);
                border-radius: 8px;
            }
        """)

        f_layout = QHBoxLayout(frame)
        f_layout.setContentsMargins(14, 0, 14, 0)
        f_layout.setSpacing(0)

        self.input_field = QLineEdit()
        self.input_field.setFixedHeight(38)
        self.input_field.setPlaceholderText("输入卡密")
        self.input_field.setStyleSheet("""
            QLineEdit {
                background: transparent; border: none;
                font-size: 13px; font-weight: 300; color: #000000; padding: 0;
            }
            QLineEdit::placeholder { color: #999999; font-weight: 300; }
        """)

        f_layout.addWidget(self.input_field, 1)
        row.addWidget(frame, 1)

        return row

    def _build_button_row(self):
        row = QHBoxLayout()
        row.setSpacing(10)

        self.btn_unbind = HoverButton(
            "解绑",
            [(239, 68, 68), (220, 38, 38), (185, 28, 28)],
            [(220, 38, 38), (185, 28, 28), (153, 27, 27)],
            radius=8, font_px=13, font_weight=50,
            fixed_height=36, fixed_width=72,
            shadow_color=QColor(239, 68, 68, 80),
            shadow_blur=12, shadow_offset=3,
        )
        self.btn_confirm = HoverButton(
            "确认", self._cn, self._ch,
            radius=8, font_px=13, font_weight=50,
            fixed_height=36, fixed_width=72,
            shadow_color=QColor(139, 92, 246, 80),
            shadow_blur=12, shadow_offset=3,
        )
        self.btn_cancel = HoverButton(
            "取消",
            [(156, 163, 175), (148, 163, 184), (139, 152, 171)],
            [(107, 114, 128), (99, 107, 120), (91, 99, 112)],
            radius=8, font_px=13, font_weight=50,
            fixed_height=36, fixed_width=72,
            shadow_color=QColor(156, 163, 175, 40),
            shadow_blur=8, shadow_offset=2,
        )

        row.addWidget(self.btn_unbind)
        row.addStretch()
        row.addWidget(self.btn_cancel)
        row.addWidget(self.btn_confirm)

        self.btn_confirm.clicked.connect(self._on_confirm)
        self.btn_cancel.clicked.connect(self.hide_panel)
        self.btn_unbind.clicked.connect(self._on_unbind_clicked)

        self.btn_unbind.hovered.connect(lambda: self._hover_parent('sad'))
        self.btn_confirm.hovered.connect(lambda: self._hover_parent('happy'))
        self.btn_copy.hovered.connect(lambda: self._hover_parent('happy'))

        return row

    def _hover_parent(self, expr):
        parent = self.parent()
        if parent and hasattr(parent, '_on_hover'):
            parent._on_hover(expr)

    def get_value(self):
        text = self.input_field.text().strip()
        return text if text else None

    def show_panel(self):
        parent = self.parent()
        pw = parent.width()
        ph = parent.height()
        eye_offset = getattr(parent, 'EYE_OFFSET', 0)
        card_h = getattr(parent, 'CARD_H', ph)
        self.setFixedSize(pw, ph)
        cx = (pw - self.card.width()) // 2
        cy = eye_offset + (card_h - self.card.height()) // 2
        self.card.move(cx, cy)
        self.input_field.clear()
        self.show()
        self.raise_()
        self.setFocus()

    def hide_panel(self):
        self.hide()

    def _on_confirm(self):
        self.hide_panel()
        parent = self.parent()
        if parent and hasattr(parent, 'toast'):
            parent.toast.show_toast("续费功能请在设置中操作", "info")

    def _on_copy_code(self):
        parent = self.parent()
        if parent and hasattr(parent, '_copy_hwid'):
            parent._copy_hwid()
        else:
            QApplication.clipboard().setText(self._machine_code)

    def _on_unbind_clicked(self):
        self.hide_panel()
        parent = self.parent()
        if parent and hasattr(parent, 'on_unbind'):
            parent.on_unbind()

    def paintEvent(self, _event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        path = QPainterPath()
        path.addRoundedRect(QRectF(0, 0, self.width(), self.height()), 20, 20)
        painter.setClipPath(path)
        painter.fillRect(self.rect(), QColor(0, 0, 0, 110))

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            if not self.card.geometry().contains(event.position().toPoint()):
                self.hide_panel()
            event.accept()

    def keyPressEvent(self, event):
        if event.key() == Qt.Key.Key_Escape:
            self.hide_panel()
        else:
            super().keyPressEvent(event)


# ============================================================
#  眼睛+嘴巴挂件: 多种表情 + 按钮触发动作 (PySide6 版)
# ============================================================
class EyesWidget(QWidget):
    EYE_R = 20
    PUPIL_R = 9
    MAX_OFFSET = 10
    EYE_SPACING = 56
    EYE_CY = 56

    def __init__(self, parent=None, center_x_ratio=0.12, eye_cy=None,
                 eye_r=None, pupil_r=None, max_offset=None, eye_spacing=None):
        super().__init__(parent)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self._center_x_ratio = center_x_ratio
        self._eye_cy = eye_cy if eye_cy is not None else self.EYE_CY
        if eye_r is not None:
            self.EYE_R = eye_r
        if pupil_r is not None:
            self.PUPIL_R = pupil_r
        if max_offset is not None:
            self.MAX_OFFSET = max_offset
        if eye_spacing is not None:
            self.EYE_SPACING = eye_spacing

        self._lpx = 0.0
        self._lpy = 0.0
        self._rpx = 0.0
        self._rpy = 0.0

        self._blink = 0.0
        self._blink_phase = 'idle'

        self._expression = 'normal'
        self._bounce = 0.0
        self._bounce_phase = 'idle'
        self._ms = self.EYE_R / 20.0  # mouth/pen scale relative to original size

        self._blink_timer = QTimer(self)
        self._blink_timer.setInterval(3000 + int(random.random() * 4000))
        self._blink_timer.timeout.connect(self._start_blink)
        self._blink_timer.start()

        self._expr_timer = QTimer(self)
        self._expr_timer.setSingleShot(True)
        self._expr_timer.timeout.connect(self._reset_expression)

        self._timer = QTimer(self)
        self._timer.setInterval(16)
        self._timer.timeout.connect(self._tick)
        self._timer.start()

    def set_expression(self, expr, duration=2000):
        self._expression = expr
        if expr == 'happy':
            self._start_blink()
            self._bounce_phase = 'up'
        self._expr_timer.start(duration)

    def _reset_expression(self):
        self._expression = 'normal'
        self._bounce_phase = 'idle'

    def _start_blink(self):
        if self._blink_phase == 'idle':
            self._blink_phase = 'closing'
        self._blink_timer.setInterval(3000 + int(random.random() * 4000))
        self._blink_timer.start()

    def _tick(self):
        # 窗口不可见时跳过计算（最小化/隐藏/后台），节省CPU
        win = self.window()
        if not self.isVisible() or (win is not None and win.isMinimized()):
            return
        gpos = QCursor.pos()
        pos = self.mapFromGlobal(gpos)

        cx = self.width() * self._center_x_ratio
        cy = self._eye_cy
        spacing = self.EYE_SPACING / 2
        left_cx = cx - spacing
        right_cx = cx + spacing
        eye_cy = cy
        expr = self._expression

        if expr == 'thinking':
            l_tx = -self.MAX_OFFSET * 0.5
            l_ty = -self.MAX_OFFSET * 0.8
            r_tx = l_tx
            r_ty = l_ty
        elif expr == 'sad':
            l_tx = 0.0
            l_ty = self.MAX_OFFSET * 0.6
            r_tx = 0.0
            r_ty = self.MAX_OFFSET * 0.6
        else:
            ldx = pos.x() - left_cx
            ldy = pos.y() - eye_cy
            l_ang = math.atan2(ldy, ldx)
            l_tx = math.cos(l_ang) * self.MAX_OFFSET
            l_ty = math.sin(l_ang) * self.MAX_OFFSET

            rdx = pos.x() - right_cx
            rdy = pos.y() - eye_cy
            r_ang = math.atan2(rdy, rdx)
            r_tx = math.cos(r_ang) * self.MAX_OFFSET
            r_ty = math.sin(r_ang) * self.MAX_OFFSET

        # 记录插值前的位置，用于判断是否需要重绘
        _old_lpx, _old_lpy = self._lpx, self._lpy
        _old_rpx, _old_rpy = self._rpx, self._rpy

        self._lpx += (l_tx - self._lpx) * 0.18
        self._lpy += (l_ty - self._lpy) * 0.18
        self._rpx += (r_tx - self._rpx) * 0.18
        self._rpy += (r_ty - self._rpy) * 0.18

        if self._blink_phase == 'closing':
            self._blink += 0.20
            if self._blink >= 1.0:
                self._blink = 1.0
                self._blink_phase = 'opening'
        elif self._blink_phase == 'opening':
            self._blink -= 0.15
            if self._blink <= 0.0:
                self._blink = 0.0
                self._blink_phase = 'idle'

        if self._bounce_phase == 'up':
            self._bounce += 0.10
            if self._bounce >= 1.0:
                self._bounce = 1.0
                self._bounce_phase = 'down'
        elif self._bounce_phase == 'down':
            self._bounce -= 0.06
            if self._bounce <= 0.0:
                self._bounce = 0.0
                self._bounce_phase = 'idle'

        # 仅在有实际变化时触发重绘（减少无谓的60fps刷新）
        _threshold = 0.3
        _moved = (abs(self._lpx - _old_lpx) > _threshold or
                  abs(self._lpy - _old_lpy) > _threshold or
                  abs(self._rpx - _old_rpx) > _threshold or
                  abs(self._rpy - _old_rpy) > _threshold)
        _animating = (self._blink_phase != 'idle' or self._bounce_phase != 'idle')
        if _moved or _animating:
            self.update()

    def paintEvent(self, _event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)

        bounce_y = int(self._bounce * 6)
        cx = self.width() * self._center_x_ratio
        cy = self._eye_cy - bounce_y
        spacing = self.EYE_SPACING / 2

        left_cx = cx - spacing
        right_cx = cx + spacing

        self._draw_eye(p, left_cx, cy, self._lpx, self._lpy)
        self._draw_eye(p, right_cx, cy, self._rpx, self._rpy)
        self._draw_mouth(p, cx, cy + self.EYE_R + 4)

    def _draw_eye(self, p, ex, ey, ox, oy):
        r = self.EYE_R
        s = self._ms
        expr = self._expression

        if expr == 'happy' and self._blink < 0.3:
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(QColor(40, 40, 40), 2.5 * s))
            path = QPainterPath()
            path.moveTo(ex - r * 0.7, ey + 2)
            path.quadTo(ex, ey - r * 0.6, ex + r * 0.7, ey + 2)
            p.drawPath(path)
            return

        eye_r = r * 1.15 if expr == 'surprised' else r
        pupil_r = self.PUPIL_R * 0.7 if expr == 'surprised' else self.PUPIL_R

        if self._blink > 0.85:
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(QColor(40, 40, 40), 2.5 * s))
            p.drawEllipse(QPointF(ex, ey), eye_r, 2)
            return

        bs = 1.0 - self._blink * 0.25

        p.setBrush(QColor(255, 255, 255))
        p.setPen(QPen(QColor(40, 40, 40), 1.5 * s))
        p.drawEllipse(QPointF(ex, ey), eye_r * bs, eye_r * bs)

        px = ex + ox
        py = ey + oy
        p.setBrush(QColor(0, 0, 0))
        p.setPen(Qt.PenStyle.NoPen)
        p.drawEllipse(QPointF(px, py), pupil_r * bs, pupil_r * bs)

        p.setBrush(QColor(255, 255, 255))
        p.drawEllipse(QPointF(px + 2.5 * s, py - 2.5 * s), 2 * s, 2 * s)

    def _draw_mouth(self, p, mx, my):
        expr = self._expression
        s = self._ms
        pen = QPen(QColor(40, 40, 40), 2 * s)

        if expr == 'happy':
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(pen)
            path = QPainterPath()
            path.moveTo(mx - 8 * s, my)
            path.quadTo(mx, my + 9 * s, mx + 8 * s, my)
            p.drawPath(path)
        elif expr == 'sad':
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(pen)
            path = QPainterPath()
            path.moveTo(mx - 6 * s, my + 4 * s)
            path.quadTo(mx, my - 3 * s, mx + 6 * s, my + 4 * s)
            p.drawPath(path)
        elif expr == 'surprised':
            p.setBrush(QColor(50, 30, 30))
            p.setPen(QPen(QColor(40, 40, 40), 1.5 * s))
            p.drawEllipse(QPointF(mx, my + 2 * s), 4 * s, 5 * s)
        elif expr == 'curious':
            p.setBrush(QColor(50, 30, 30))
            p.setPen(QPen(QColor(40, 40, 40), 1.5 * s))
            p.drawEllipse(QPointF(mx, my + 2 * s), 3 * s, 3.5 * s)
        elif expr == 'thinking':
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(pen)
            path = QPainterPath()
            path.moveTo(mx - 5 * s, my + 2 * s)
            path.quadTo(mx + 2 * s, my + 4 * s, mx + 6 * s, my)
            p.drawPath(path)
        else:
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(pen)
            path = QPainterPath()
            path.moveTo(mx - 6 * s, my)
            path.quadTo(mx, my + 5 * s, mx + 6 * s, my)
            p.drawPath(path)


# ============================================================
#  吉祥物眼睛组件: 基于人物图片，瞳孔跟随鼠标，支持眨眼/表情
# ============================================================
class MascotEyesWidget(QWidget):
    """吉祥物眼睛组件 - 使用人物图片作为背景，瞳孔跟随鼠标移动，支持眨眼和表情动画"""

    # 原图(透明背景, 1684x1798)中的眼睛参数（grabCut抠图后精确测量）
    IMG_LEFT_EYE = (576, 631)      # 左眼瞳孔中心坐标
    IMG_RIGHT_EYE = (1039, 563)    # 右眼瞳孔中心坐标
    IMG_EYE_RADIUS = 99            # 眼睛半径（虹膜+眼白）
    IMG_PUPIL_RADIUS = 32          # 瞳孔半径（略小，移动时露出虹膜）
    IMG_PUPIL_MAX_OFFSET = 36      # 瞳孔最大偏移量

    def __init__(self, parent=None, image_path=None):
        super().__init__(parent)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)

        # 加载图片
        self._image_path = image_path
        self._pixmap = None
        self._scaled_pixmap = None
        self._last_size = None
        self._load_image()

        # 瞳孔位置（相对于眼睛中心的偏移）
        self._lpx = 0.0
        self._lpy = 0.0
        self._rpx = 0.0
        self._rpy = 0.0

        # 眨眼动画
        self._blink = 0.0
        self._blink_phase = 'idle'

        # 表情
        self._expression = 'normal'
        self._bounce = 0.0
        self._bounce_phase = 'idle'

        # 缩放比例（根据当前控件大小计算）
        self._scale = 1.0
        self._img_offset_x = 0.0
        self._img_offset_y = 0.0

        # 眨眼定时器
        self._blink_timer = QTimer(self)
        self._blink_timer.setInterval(3000 + int(random.random() * 4000))
        self._blink_timer.timeout.connect(self._start_blink)
        self._blink_timer.start()

        # 表情定时器
        self._expr_timer = QTimer(self)
        self._expr_timer.setSingleShot(True)
        self._expr_timer.timeout.connect(self._reset_expression)

        # 动画定时器
        self._timer = QTimer(self)
        self._timer.setInterval(16)
        self._timer.timeout.connect(self._tick)
        self._timer.start()

    def _load_image(self):
        """加载吉祥物图片"""
        if self._image_path and os.path.exists(self._image_path):
            self._pixmap = QPixmap(self._image_path)
        else:
            # 尝试在程序目录查找
            base_dir = os.path.dirname(os.path.abspath(__file__))
            for name in ['mascot.png', '吉祥物.png']:
                p = os.path.join(base_dir, name)
                if os.path.exists(p):
                    self._pixmap = QPixmap(p)
                    break
        if self._pixmap is None or self._pixmap.isNull():
            self._pixmap = QPixmap(200, 200)
            self._pixmap.fill(QColor(200, 200, 255))

    def set_expression(self, expr, duration=2000):
        """设置表情"""
        self._expression = expr
        if expr == 'happy':
            self._start_blink()
            self._bounce_phase = 'up'
        self._expr_timer.start(duration)

    def _reset_expression(self):
        self._expression = 'normal'
        self._bounce_phase = 'idle'

    def _start_blink(self):
        if self._blink_phase == 'idle':
            self._blink_phase = 'closing'
        self._blink_timer.setInterval(3000 + int(random.random() * 4000))
        self._blink_timer.start()

    def _get_scaled_eye_params(self):
        """获取缩放后的眼睛参数"""
        if self._pixmap is None or self._pixmap.isNull():
            return (20, 20), (60, 20), 10, 4, 3

        w = self.width()
        h = self.height()
        img_w = self._pixmap.width()
        img_h = self._pixmap.height()

        # 按比例缩放图片以适应控件（contain模式）
        scale = min(w / img_w, h / img_h)
        scaled_w = img_w * scale
        scaled_h = img_h * scale
        offset_x = (w - scaled_w) / 2
        offset_y = (h - scaled_h) / 2

        self._scale = scale
        self._img_offset_x = offset_x
        self._img_offset_y = offset_y

        # 计算缩放后的眼睛位置
        left_x = offset_x + self.IMG_LEFT_EYE[0] * scale
        left_y = offset_y + self.IMG_LEFT_EYE[1] * scale
        right_x = offset_x + self.IMG_RIGHT_EYE[0] * scale
        right_y = offset_y + self.IMG_RIGHT_EYE[1] * scale
        eye_r = self.IMG_EYE_RADIUS * scale
        pupil_r = self.IMG_PUPIL_RADIUS * scale
        max_offset = self.IMG_PUPIL_MAX_OFFSET * scale

        return (left_x, left_y), (right_x, right_y), eye_r, pupil_r, max_offset

    def _tick(self):
        """动画帧更新"""
        if not self.isVisible():
            win = self.window()
            if win is not None and win.isMinimized():
                return

        left_eye, right_eye, eye_r, pupil_r, max_offset = self._get_scaled_eye_params()

        gpos = QCursor.pos()
        pos = self.mapFromGlobal(gpos)
        expr = self._expression

        if expr == 'thinking':
            l_tx = -max_offset * 0.5
            l_ty = -max_offset * 0.8
            r_tx = l_tx
            r_ty = l_ty
        elif expr == 'sad':
            l_tx = 0.0
            l_ty = max_offset * 0.6
            r_tx = 0.0
            r_ty = max_offset * 0.6
        else:
            # 左眼瞳孔跟随鼠标
            ldx = pos.x() - left_eye[0]
            ldy = pos.y() - left_eye[1]
            l_ang = math.atan2(ldy, ldx)
            dist = math.sqrt(ldx * ldx + ldy * ldy)
            if dist > max_offset:
                l_tx = math.cos(l_ang) * max_offset
                l_ty = math.sin(l_ang) * max_offset
            else:
                l_tx = ldx
                l_ty = ldy

            # 右眼瞳孔跟随鼠标
            rdx = pos.x() - right_eye[0]
            rdy = pos.y() - right_eye[1]
            r_ang = math.atan2(rdy, rdx)
            rdist = math.sqrt(rdx * rdx + rdy * rdy)
            if rdist > max_offset:
                r_tx = math.cos(r_ang) * max_offset
                r_ty = math.sin(r_ang) * max_offset
            else:
                r_tx = rdx
                r_ty = rdy

        # 插值平滑移动
        self._lpx += (l_tx - self._lpx) * 0.18
        self._lpy += (l_ty - self._lpy) * 0.18
        self._rpx += (r_tx - self._rpx) * 0.18
        self._rpy += (r_ty - self._rpy) * 0.18

        # 眨眼动画
        if self._blink_phase == 'closing':
            self._blink += 0.20
            if self._blink >= 1.0:
                self._blink = 1.0
                self._blink_phase = 'opening'
        elif self._blink_phase == 'opening':
            self._blink -= 0.15
            if self._blink <= 0.0:
                self._blink = 0.0
                self._blink_phase = 'idle'

        # 弹跳动画
        if self._bounce_phase == 'up':
            self._bounce += 0.10
            if self._bounce >= 1.0:
                self._bounce = 1.0
                self._bounce_phase = 'down'
        elif self._bounce_phase == 'down':
            self._bounce -= 0.06
            if self._bounce <= 0.0:
                self._bounce = 0.0
                self._bounce_phase = 'idle'

        self.update()

    def paintEvent(self, _event):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)

        if self._pixmap is None or self._pixmap.isNull():
            return

        w = self.width()
        h = self.height()

        # 计算缩放后的图片位置（居中显示，保持比例）
        img_w = self._pixmap.width()
        img_h = self._pixmap.height()
        scale = min(w / img_w, h / img_h)
        scaled_w = int(img_w * scale)
        scaled_h = int(img_h * scale)
        x = (w - scaled_w) // 2
        y = (h - scaled_h) // 2 + int(self._bounce * -6)

        # 绘制背景图片
        p.drawPixmap(x, y, scaled_w, scaled_h, self._pixmap)

        # 获取眼睛参数
        left_eye, right_eye, eye_r, pupil_r, max_offset = self._get_scaled_eye_params()
        left_eye = (left_eye[0], left_eye[1] + self._bounce * -6)
        right_eye = (right_eye[0], right_eye[1] + self._bounce * -6)

        expr = self._expression

        # 绘制瞳孔
        self._draw_pupil(p, left_eye[0], left_eye[1], self._lpx, self._lpy, eye_r, pupil_r, expr)
        self._draw_pupil(p, right_eye[0], right_eye[1], self._rpx, self._rpy, eye_r, pupil_r, expr)

    def _draw_pupil(self, p, ex, ey, ox, oy, eye_r, pupil_r, expr):
        """绘制瞳孔"""
        # 眨眼时不绘制瞳孔或只画一条线
        if self._blink > 0.85:
            return

        if expr == 'happy' and self._blink < 0.3:
            # 开心时眼睛弯成月牙，不画瞳孔
            return

        bs = 1.0 - self._blink * 0.25

        # 瞳孔位置
        px = ex + ox
        py = ey + oy

        # 绘制瞳孔阴影（柔和边缘）
        shadow_r = pupil_r * bs * 1.2
        shadow_grad = QRadialGradient(QPointF(px, py), shadow_r)
        shadow_grad.setColorAt(0, QColor(0, 0, 0, 180))
        shadow_grad.setColorAt(0.7, QColor(0, 0, 0, 120))
        shadow_grad.setColorAt(1, QColor(0, 0, 0, 0))
        p.setBrush(shadow_grad)
        p.setPen(Qt.PenStyle.NoPen)
        p.drawEllipse(QPointF(px, py), shadow_r, shadow_r)

        # 绘制瞳孔主体
        p.setBrush(QColor(20, 10, 40, 220))
        p.setPen(Qt.PenStyle.NoPen)
        p.drawEllipse(QPointF(px, py), pupil_r * bs, pupil_r * bs)

        # 绘制瞳孔高光
        hl_r = pupil_r * 0.35 * bs
        hl_x = px + pupil_r * 0.25 * bs
        hl_y = py - pupil_r * 0.3 * bs
        p.setBrush(QColor(255, 255, 255, 200))
        p.drawEllipse(QPointF(hl_x, hl_y), hl_r, hl_r * 0.8)

        # 小高光点
        hl2_r = pupil_r * 0.12 * bs
        hl2_x = px - pupil_r * 0.3 * bs
        hl2_y = py + pupil_r * 0.25 * bs
        p.setBrush(QColor(255, 255, 255, 150))
        p.drawEllipse(QPointF(hl2_x, hl2_y), hl2_r, hl2_r)


