    def _auto_verify(self):
        """后台自动验证卡密，但不自动登录，验证成功后可直接点击登录"""
        card = self.edit.text().strip()
        if not card:
            return

        self._pre_verified = None
        self._pre_verified_card = None
        self._verifying = True
        self._auto_verifying = True

        def verify():
            try:
                result = verify_license_key(card, self.hwid, is_heartbeat=False)
                if result.get("ok"):
                    self._pre_verified = result
                    self._pre_verified_card = card
                    QMetaObject.invokeMethod(self, "_on_pre_verify_success", Qt.ConnectionType.QueuedConnection, Q_ARG(str, result.get("msg", "")))
                else:
                    self._pre_verified = None
                    self._pre_verified_card = None
            finally:
                self._verifying = False
                self._auto_verifying = False
                # 预验证期间用户点击了登录 → 复用本次结果继续登录，避免重复发请求
                if self._pending_login:
                    self._pending_login = False
                    QMetaObject.invokeMethod(self, "_on_pre_verify_settled", Qt.ConnectionType.QueuedConnection)

        threading.Thread(target=verify, daemon=True).start()

    @Slot(str)
    def _on_pre_verify_success(self, msg):
        """后台预验证成功回调"""
        self.status.setText(f"✓ {msg}")
        self.status.setStyleSheet(f"font-size: 13px; color: {COLOR_SUCCESS}; min-height: 22px; margin-top: 6px; margin-bottom: 2px;")

    @Slot()
    def _on_pre_verify_settled(self):
        """预验证线程结束后回调：若期间用户点击了登录，则继续登录流程（复用缓存结果）"""
        self.on_login()

    def on_login(self):
        card = self.edit.text().strip()
        if self._verifying:
            if self._auto_verifying:
                # 预验证进行中：等待其结果并复用，避免重复发请求触发服务器限频
                self._pending_login = True
            self.status.setText("正在验证中，请稍候...")
            return
        if not card:
            self.status.setText("请输入卡密")
            self.eyes.set_expression('sad', 2000)
            return

        self._verifying = True
        self.login_btn.setEnabled(False)
        self.login_btn.setText("验证中...")
        self.status.setText("正在验证...")
        self.eyes.set_expression('curious', 2000)
        self.status.setStyleSheet(f"font-size: 13px; color: {COLOR_PRIMARY}; min-height: 22px; margin-top: 6px; margin-bottom: 2px;")

        def verify():
            try:
                # 仅当缓存结果与当前输入的卡密一致时才复用，否则必须重新验证
                if self._pre_verified and self._pre_verified_card == card:
                    result = self._pre_verified
                else:
                    result = verify_license_key(card, self.hwid, is_heartbeat=False)
                if result.get("ok"):
                    save_card_key(card)
                    QMetaObject.invokeMethod(self, "_on_verify_success", Qt.ConnectionType.QueuedConnection, Q_ARG(str, result.get("msg", "")), Q_ARG(str, result.get("expire", "")))
                else:
                    QMetaObject.invokeMethod(self, "_on_verify_failed", Qt.ConnectionType.QueuedConnection, Q_ARG(str, result.get("msg", "验证失败")))
            finally:
                self._verifying = False

        threading.Thread(target=verify, daemon=True).start()

    @Slot(str, str)
    def _on_verify_success(self, msg, expire):
        self.login_btn.setEnabled(True)
        self.login_btn.setText("登 录")
        self.eyes.set_expression('happy', 3000)
        self.status.setStyleSheet(f"font-size: 13px; color: {COLOR_SUCCESS}; min-height: 22px; margin-top: 6px; margin-bottom: 2px; background: transparent; border: none;")
        self.status.setText(msg)

        global REMAINING_TIME
        if expire:
            REMAINING_TIME = expire
        else:
            REMAINING_TIME = "验证中..."

        display_expire = expire if expire else "验证中..."
        self.toast.show_toast(f"登录成功！剩余：{display_expire}", "success")
        QTimer.singleShot(2000, self.accept)

    @Slot(str)
    def _on_verify_failed(self, msg):
        self.login_btn.setEnabled(True)
        self.login_btn.setText("登 录")
        self.eyes.set_expression('sad', 2000)
        self.status.setStyleSheet(f"font-size: 13px; color: {COLOR_DANGER}; min-height: 22px; margin-top: 6px; margin-bottom: 2px; background: transparent; border: none;")
        self.status.setText(msg)

    def on_unbind(self):
        """解绑按钮处理"""
        card = self.edit.text().strip()
        if not card:
            self.status.setText("请输入卡密")
            self.eyes.set_expression('sad', 2000)
            return

        # 弹出确认对话框
        msg_box = QMessageBox(self)
        msg_box.setIcon(QMessageBox.Icon.Warning)
        msg_box.setWindowTitle("解绑确认")
        msg_box.setText("确认要执行解绑操作吗？")
        msg_box.setInformativeText("⚠️ 注意：解绑定会扣一天时长\n年卡、永久卡不扣时长")
        msg_box.setStandardButtons(QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No)
        msg_box.setDefaultButton(QMessageBox.StandardButton.No)
        msg_box.setMinimumSize(320, 150)
        msg_box.setStyleSheet(f"""
            QMessageBox {{
                background-color: {COLOR_BG};
            }}
            QMessageBox QLabel {{
                color: {COLOR_TEXT};
                font-size: 13px;
            }}
            QPushButton {{
                background-color: {COLOR_PRIMARY};
                color: white;
                border: none;
                border-radius: 6px;
                padding: 8px 24px;
                font-size: 13px;
                font-weight: 600;
                min-width: 80px;
            }}
            QPushButton:hover {{
                background-color: {COLOR_PRIMARY_HOVER};
            }}
        """)

        if msg_box.exec() != QMessageBox.StandardButton.Yes:
            return

        # 执行解绑
        self.unbind_btn.setEnabled(False)
        self.unbind_btn.setText("解绑中...")
        self.status.setText("正在解绑...")
        self.eyes.set_expression('sad', 1500)
        self.status.setStyleSheet(f"font-size: 13px; color: {COLOR_PRIMARY}; min-height: 22px; margin-top: 6px; margin-bottom: 2px;")

        def do_unbind():
            try:
                import urllib.request
                # 构建解绑URL（走当前生效线路，切换后自动走备用）
                card_clean = card.strip().replace(" ", "").upper()
                url = get_api_url("self_unbind", card=card_clean, mac="1")
                with _safe_urlopen(url, timeout=15) as response:
                    # 【F2 解绑响应签名校验】防止中间人伪造"解绑成功"
                    _xsign2 = getattr(response.headers, 'get', lambda *a, **k: '')('X-Sign2', '') if hasattr(response, 'headers') else ''
                    _xhs256 = getattr(response.headers, 'get', lambda *a, **k: '')('X-Hs256', '') if hasattr(response, 'headers') else ''
                    raw_result = response.read().decode('utf-8')
                    result = raw_result
                    _has_sign = ('|sign=' in raw_result) or ('|hs256=' in raw_result) or bool(_xsign2) or bool(_xhs256)
                    if _has_sign:
                        verified = verify_response(raw_result.strip(), _xsign2, _xhs256)
                        if verified == "":
                            # 签名存在但校验失败
                            QMetaObject.invokeMethod(self, "_on_unbind_failed", Qt.ConnectionType.QueuedConnection, Q_ARG(str, "解绑失败：服务器响应签名校验失败，已拦截"))
                            return
                        result = verified

                # 解析结果
                if "成功" in result or "ok" in result.lower() or result.strip() == "1":
                    QMetaObject.invokeMethod(self, "_on_unbind_success", Qt.ConnectionType.QueuedConnection, Q_ARG(str, "解绑成功！"))
                else:
                    QMetaObject.invokeMethod(self, "_on_unbind_failed", Qt.ConnectionType.QueuedConnection, Q_ARG(str, result if result else "解绑失败，请稍后再试"))
            except Exception as e:
                QMetaObject.invokeMethod(self, "_on_unbind_failed", Qt.ConnectionType.QueuedConnection, Q_ARG(str, f"解绑失败：{str(e)}"))

        threading.Thread(target=do_unbind, daemon=True).start()

