    def on_trial(self):
        """免费试用按钮处理"""
        self.trial_btn.setEnabled(False)
        self.trial_btn.setText("处理中...")
        self.status.setText("正在检查试用资格...")
        self.eyes.set_expression('curious', 2000)
        self.status.setStyleSheet(f"font-size: 13px; color: {COLOR_PRIMARY}; min-height: 22px; margin-top: 6px; margin-bottom: 2px;")

        def do_trial():
            manager = CardManager()

            # 先检查是否有未用完的试用时间
            trial_status = manager.check_trial_status()
            if trial_status and trial_status.get("active") and trial_status.get("remaining") > 0:
                remaining_seconds = trial_status["remaining"]
                d = remaining_seconds // 86400
                h = (remaining_seconds % 86400) // 3600
                m = (remaining_seconds % 3600) // 60
                remaining_str = f"{d}天{h}时{m}分"

                global REMAINING_TIME
                REMAINING_TIME = remaining_str

                QMetaObject.invokeMethod(self, "_on_trial_resume", Qt.ConnectionType.QueuedConnection, Q_ARG(str, remaining_str))
                return

            # 检查是否可以激活新试用
            can_use, reason = manager.can_use_trial()

            if not can_use:
                QMetaObject.invokeMethod(self, "_on_trial_failed", Qt.ConnectionType.QueuedConnection, Q_ARG(str, reason))
                return

            success, msg = manager.activate_trial()

            if success:
                QMetaObject.invokeMethod(self, "_on_trial_success", Qt.ConnectionType.QueuedConnection, Q_ARG(str, msg))
            else:
                QMetaObject.invokeMethod(self, "_on_trial_failed", Qt.ConnectionType.QueuedConnection, Q_ARG(str, msg))

        threading.Thread(target=do_trial, daemon=True).start()

