# 3. 全局工具与视觉核心

# 【DPI修复】全局屏幕DPI缩放比例（缓存，避免重复计算）
_screen_dpi_scale = None

def get_screen_dpi_scale():
    """获取屏幕DPI缩放比例（如1.25表示125%缩放）
    用于逻辑坐标与物理像素坐标的转换"""
    global _screen_dpi_scale
    if _screen_dpi_scale is not None:
        return _screen_dpi_scale
    try:
        if sys.platform == 'win32':
            import ctypes
            try:
                # 优先使用 Win8+ API: GetDpiForSystem
                dpi = ctypes.windll.user32.GetDpiForSystem()
                _screen_dpi_scale = dpi / 96.0
            except Exception:
                # 回退到旧版API
                hdc = ctypes.windll.user32.GetDC(0)
                try:
                    LOGPIXELSX = 88
                    dpi = ctypes.windll.gdi32.GetDeviceCaps(hdc, LOGPIXELSX)
                    _screen_dpi_scale = dpi / 96.0
                finally:
                    ctypes.windll.user32.ReleaseDC(0, hdc)
        else:
            _screen_dpi_scale = 1.0
    except Exception:
        _screen_dpi_scale = 1.0
    # 安全范围检查
    if _screen_dpi_scale < 0.5 or _screen_dpi_scale > 5.0:
        _screen_dpi_scale = 1.0
    return _screen_dpi_scale

def logical_to_physical(x, y=None):
    """逻辑坐标转物理像素坐标（乘以DPI缩放比例）"""
    scale = get_screen_dpi_scale()
    if y is None:
        return int(x * scale)
    return int(x * scale), int(y * scale)

def physical_to_logical(x, y=None):
    """物理像素坐标转逻辑坐标（除以DPI缩放比例）"""
    scale = get_screen_dpi_scale()
    if y is None:
        return int(x / scale)
    return int(x / scale), int(y / scale)

# 全局mss实例，避免频繁创建/销毁GDI资源导致句柄泄漏
_global_mss_instance = None
_mss_lock = __import__('threading').Lock()

def _get_mss_instance():
    """获取全局mss实例（线程安全，单例模式，带错误恢复）"""
    global _global_mss_instance
    if _global_mss_instance is None:
        import mss, threading
        with _mss_lock:
            if _global_mss_instance is None:
                _global_mss_instance = mss.mss()
    return _global_mss_instance

def _reset_mss_instance():
    """重置mss实例（当截图异常时调用，强制重建）"""
    global _global_mss_instance
    with _mss_lock:
        if _global_mss_instance is not None:
            try:
                _global_mss_instance.close()
            except Exception:
                pass
            _global_mss_instance = None

# 文件图像缓存，避免每次循环重复读取和解码同一图像文件（LRU策略限制内存）
from collections import OrderedDict as _ODict
_FILE_IMAGE_CACHE = _ODict()
_FILE_IMAGE_CACHE_MAX = 100  # 减少缓存数量，降低内存占用

def _load_image_from_file_cached(image_path: str):
    """从文件加载图像，带LRU缓存。避免在等待循环中每次都重新读取文件"""
    if image_path in _FILE_IMAGE_CACHE:
        _FILE_IMAGE_CACHE.move_to_end(image_path)  # 标记为最近使用
        return _FILE_IMAGE_CACHE[image_path]
    if not image_path or not os.path.exists(image_path):
        return None
    try:
        img_array = np.fromfile(image_path, dtype=np.uint8)
        template = cv2.imdecode(img_array, cv2.IMREAD_COLOR)
        del img_array
        if template is not None:
            # LRU淘汰：超过限制时移除最早使用的
            while len(_FILE_IMAGE_CACHE) >= _FILE_IMAGE_CACHE_MAX:
                _FILE_IMAGE_CACHE.popitem(last=False)
            _FILE_IMAGE_CACHE[image_path] = template
        return template
    except Exception:
        return None

# 通用视觉识别函数 (代码去重与优化，线程安全版本 - 使用PIL替代Qt截屏)
def _grab_screen_pil(x: int, y: int, width: int, height: int, hwnd: int = 0):
    """使用PIL截取屏幕区域，返回BGR格式的numpy数组（线程安全）
    【DPI修复】输入的x,y,width,height是逻辑坐标，内部自动转换为物理像素截图"""
    # 【DPI修复】逻辑坐标转物理像素坐标
    scale = get_screen_dpi_scale()
    px = int(x * scale)
    py = int(y * scale)
    pw = int(width * scale)
    ph = int(height * scale)
    
    # 使用PIL.ImageGrab截屏，支持hwnd指定窗口
    if hwnd and hwnd != 0:
        try:
            import ctypes
            from ctypes import wintypes
            # 获取窗口位置和大小
            rect = wintypes.RECT()
            ctypes.windll.user32.GetWindowRect(hwnd, ctypes.byref(rect))
            win_x, win_y = rect.left, rect.top
            win_w, win_h = rect.right - rect.left, rect.bottom - rect.top
            # 在全屏截图中取窗口区域，使用.copy()确保全屏内存可释放
            full = ImageGrab.grab()
            full_np = cv2.cvtColor(np.array(full), cv2.COLOR_RGB2BGR)
            del full
            bg = full_np[win_y:win_y+win_h, win_x:win_x+win_w].copy()
            del full_np
        except Exception:
            full = ImageGrab.grab()
            bg = cv2.cvtColor(np.array(full), cv2.COLOR_RGB2BGR)
            del full
    else:
        # 使用全局mss实例，避免频繁创建/销毁GDI资源
        try:
            sct = _get_mss_instance()
            monitor = sct.monitors[1]
            screen_w = monitor["width"]
            screen_h = monitor["height"]
            grab_x = max(0, px)
            grab_y = max(0, py)
            grab_w = min(pw, screen_w - grab_x)
            grab_h = min(ph, screen_h - grab_y)
            if grab_w <= 0 or grab_h <= 0:
                return np.zeros((1, 1, 3), dtype=np.uint8)
            region = {"top": grab_y, "left": grab_x, "width": grab_w, "height": grab_h}
            sct_img = sct.grab(region)
            bgra = np.array(sct_img)
            bg = cv2.cvtColor(bgra, cv2.COLOR_BGRA2BGR)
            del bgra, sct_img
        except Exception:
            # mss截图失败时重置实例并回退到ImageGrab
            _reset_mss_instance()
            full = ImageGrab.grab()
            bg = cv2.cvtColor(np.array(full), cv2.COLOR_RGB2BGR)
            del full
    return bg

def _grab_screen_full_pil(hwnd: int = 0):
    """使用全局mss截取全屏，返回BGR格式的numpy数组（线程安全，减少GDI泄漏）"""
    if hwnd and hwnd != 0:
        return _grab_screen_pil(0, 0, 9999, 9999, hwnd)
    try:
        sct = _get_mss_instance()
        monitor = sct.monitors[0]  # monitors[0] 是所有显示器的组合
        sct_img = sct.grab(monitor)
        bgra = np.array(sct_img)
        bg = cv2.cvtColor(bgra, cv2.COLOR_BGRA2BGR)
        del bgra, sct_img
        return bg
    except Exception:
        # mss截图失败时重置实例并回退到ImageGrab
        _reset_mss_instance()
        full = ImageGrab.grab()
        bg = cv2.cvtColor(np.array(full), cv2.COLOR_RGB2BGR)
        del full
        return bg

def perform_image_match(image_path: str, x: int, y: int, width: int, height: int, hwnd: int = 0):
    template = None
    
    # 首先尝试从嵌入图像加载
    if image_path:
        template = get_embedded_image(image_path)
    
    # 如果嵌入图像不存在或加载失败，从文件加载（带缓存）
    if template is None:
        template = _load_image_from_file_cached(image_path)
        if template is None:
            return False, {}, "图像文件不存在或无法读取"

    try:
        roi = None
        # 无窗口句柄时直接截取ROI区域，减少内存占用和GDI压力
        if not hwnd or hwnd == 0:
            roi = _grab_screen_pil(x, y, width, height, hwnd)
        else:
            # 有窗口句柄时仍需先截全屏再裁剪（因为窗口坐标需要转换）
            bg = _grab_screen_full_pil(hwnd)
            x_roi = max(0, min(x, bg.shape[1]))
            y_roi = max(0, min(y, bg.shape[0]))
            w_roi = max(1, min(width, bg.shape[1] - x_roi))
            h_roi = max(1, min(height, bg.shape[0] - y_roi))
            # 使用.copy()确保切片后全屏内存可被释放
            roi = bg[y_roi:y_roi+h_roi, x_roi:x_roi+w_roi].copy()
            del bg  # 现在可以真正释放全屏截图内存
        
        if roi is None or roi.size == 0 or template.shape[0] > roi.shape[0] or template.shape[1] > roi.shape[1]:
            del roi
            return False, {}, "图像尺寸不匹配"

        res = cv2.matchTemplate(roi, template, cv2.TM_CCOEFF_NORMED)
        _, max_val, _, max_loc = cv2.minMaxLoc(res)

        if not hwnd or hwnd == 0:
            # roi 由 _grab_screen_pil 按物理像素截取，max_loc 与模板尺寸均为物理像素，
            # 需除以 DPI 缩放比例转回逻辑坐标，再叠加搜索区左上角逻辑坐标 x/y
            scale = get_screen_dpi_scale()
            target_x = int(x + (max_loc[0] + template.shape[1] // 2) / scale)
            target_y = int(y + (max_loc[1] + template.shape[0] // 2) / scale)
        else:
            target_x = max_loc[0] + x + template.shape[1] // 2
            target_y = max_loc[1] + y + template.shape[0] // 2

        # 显式释放临时图像内存
        del res
        del roi

        return True, {
            "max_val": max_val,
            "target_x": target_x,
            "target_y": target_y
        }, "匹配完成"

    except Exception as e:
        return False, {}, str(e)
    finally:
        # 确保异常路径下临时变量也被释放
        try:
            del res
        except NameError:
            pass
        try:
            del roi
        except NameError:
            pass
        try:
            del bg
        except NameError:
            pass

def check_motion_at(cx: int, cy: int, w: int = 50, h: int = 50, 
                     times: int = 2, threshold: float = 0.03, 
                     interval: float = 0.1, hwnd: int = 0, stop_event=None):
    """
    检测指定中心点周围区域是否有运动
    cx, cy: 中心点坐标
    w, h: 检测区域大小
    times: 检测次数（连续几次有变化才算）
    threshold: 运动阈值（像素变化占比）
    interval: 帧间隔（秒）
    stop_event: 可选 callable，返回 True 时立即中断返回（配合 QThread.isInterruptionRequested）
    返回: (是否在动, 最大变化率)
    """
    try:
        x = max(0, cx - w // 2)
        y = max(0, cy - h // 2)

        prev_frame = None
        max_change = 0.0
        motion_count = 0

        for i in range(times + 1):
            # 【T2 线程优雅退出】每次截图前检查上层 stop_event：中断时立刻退出，不再等到 times 次全部跑完
            if stop_event is not None:
                try:
                    if callable(stop_event) and stop_event():
                        return False, 0.0
                except Exception:
                    pass
            
            # 直接截取ROI区域，减少内存占用
            if not hwnd or hwnd == 0:
                roi = _grab_screen_pil(x, y, w, h, hwnd)
            else:
                bg = _grab_screen_full_pil(hwnd)
                x1 = max(0, min(x, bg.shape[1]))
                y1 = max(0, min(y, bg.shape[0]))
                x2 = min(x + w, bg.shape[1])
                y2 = min(y + h, bg.shape[0])
                if x2 <= x1 or y2 <= y1:
                    del bg
                    return False, 0.0
                roi = bg[y1:y2, x1:x2].copy()
                del bg  # 使用.copy()后才能真正释放全屏截图内存

            if roi is None or roi.size == 0:
                return False, 0.0

            gray = cv2.cvtColor(roi, cv2.COLOR_BGR2GRAY)
            gray = cv2.GaussianBlur(gray, (21, 21), 0)
            del roi  # 释放彩色图像内存

            if prev_frame is not None:
                diff = cv2.absdiff(prev_frame, gray)
                change_ratio = np.sum(diff > 25) / diff.size
                max_change = max(max_change, change_ratio)
                del diff  # 释放差异图像内存

                if change_ratio > threshold:
                    motion_count += 1

            prev_frame = gray
            # 分段 sleep 检查中断，避免 interval 很长时单步卡住
            if interval > 0:
                _step = max(0.02, min(interval / 5, 0.1))
                _slept = 0.0
                while _slept < interval:
                    if stop_event is not None:
                        try:
                            if callable(stop_event) and stop_event():
                                return False, 0.0
                        except Exception:
                            pass
                    time.sleep(_step)
                    _slept += _step

        is_moving = motion_count >= times
        return is_moving, max_change

    except Exception:
        return False, 0.0
    finally:
        try:
            del prev_frame
        except NameError:
            pass
        try:
            del gray
        except NameError:
            pass

# 图色匹配函数（线程安全版本 - 使用PIL替代Qt截屏）
def perform_color_match(color_hex: str, x: int, y: int, width: int, height: int, tolerance: int = 10, hwnd: int = 0, stop_event=None):
    """执行颜色匹配"""
    try:
        if stop_event and stop_event.is_set():
            return False, {"matched": False}, "已停止"
            
        color_hex = color_hex.lstrip('#')
        target_bgr = tuple(int(color_hex[i:i+2], 16) for i in (4, 2, 0))

        # 直接截取ROI区域，减少内存占用
        if not hwnd or hwnd == 0:
            roi = _grab_screen_pil(x, y, width, height, hwnd)
            x_offset, y_offset = x, y
        else:
            bg = _grab_screen_full_pil(hwnd)
            x_roi = max(0, min(x, bg.shape[1]))
            y_roi = max(0, min(y, bg.shape[0]))
            w_roi = max(1, min(width, bg.shape[1] - x_roi))
            h_roi = max(1, min(height, bg.shape[0] - y_roi))
            roi = bg[y_roi:y_roi+h_roi, x_roi:x_roi+w_roi].copy()
            x_offset, y_offset = x_roi, y_roi
            del bg  # 使用.copy()后才能真正释放全屏截图内存
        
        if roi is None or roi.size == 0:
            return False, {"matched": False}, "区域无效"
        
        target_arr = np.array(target_bgr, dtype=np.int32)
        diff = np.sum(np.abs(roi.astype(np.int32) - target_arr), axis=2)
        del target_arr
        match_mask = diff <= tolerance * 3
        ys, xs = np.where(match_mask)
        if len(ys) > 0:
            min_diff = np.min(diff[match_mask])
            min_indices = np.where(diff == min_diff)
            i, j = min_indices[0][0], min_indices[1][0]
            pixel_bgr = tuple(int(v) for v in roi[i, j])
            target_x = x_offset + j
            target_y = y_offset + i
            del diff, roi, match_mask, ys, xs, min_diff, min_indices
            return True, {
                "target_x": int(target_x),
                "target_y": int(target_y),
                "pixel_color": f"#{pixel_bgr[2]:02x}{pixel_bgr[1]:02x}{pixel_bgr[0]:02x}",
                "matched": True
            }, "找到颜色"

        del diff, roi, match_mask, ys, xs
        return False, {"matched": False}, "未找到匹配颜色"
    except Exception as e:
        return False, {}, str(e)
    finally:
        try:
            del diff
        except NameError:
            pass
        try:
            del roi
        except NameError:
            pass
        try:
            del match_mask
        except NameError:
            pass
        try:
            del target_arr
        except NameError:
            pass
        try:
            del bg
        except NameError:
            pass

def perform_multi_color_match(color_hex: str, x: int, y: int, width: int, height: int, offsets: list, similarity: float = 0.8, hwnd: int = 0, stop_event=None):
    """执行多点图色匹配（兼容魔盒FindMultiColor）"""
    try:
        if stop_event and stop_event.is_set():
            return False, {"matched": False}, "已停止"
            
        color_hex = color_hex.lstrip('#')
        target_bgr = tuple(int(color_hex[i:i+2], 16) for i in (4, 2, 0))

        bg = _grab_screen_full_pil(hwnd)
        
        x_roi = max(0, min(x, bg.shape[1]))
        y_roi = max(0, min(y, bg.shape[0]))
        w_roi = max(1, min(width, bg.shape[1] - x_roi))
        h_roi = max(1, min(height, bg.shape[0] - y_roi))
        roi = bg[y_roi:y_roi+h_roi, x_roi:x_roi+w_roi]
        
        target_arr = np.array(target_bgr, dtype=np.int32)
        diff = np.sum(np.abs(roi.astype(np.int32) - target_arr), axis=2)
        max_diff = 255 * 3 * (1 - similarity)
        match_mask = diff <= max_diff
        ys, xs = np.where(match_mask)
        
        for i, j in zip(ys, xs):
            if stop_event and stop_event.is_set():
                return False, {"matched": False}, "已停止"
            
            found_x = x_roi + j
            found_y = y_roi + i
            
            all_match = True
            for offset in offsets:
                dx, dy, offset_color = offset
                check_x = found_x + dx
                check_y = found_y + dy
                
                if check_x < 0 or check_x >= bg.shape[1] or check_y < 0 or check_y >= bg.shape[0]:
                    all_match = False
                    break
                
                offset_color_clean = offset_color.lstrip('#')
                if len(offset_color_clean) != 6:
                    all_match = False
                    break
                
                offset_bgr = tuple(int(offset_color_clean[i:i+2], 16) for i in (4, 2, 0))
                pixel_bgr = tuple(int(v) for v in bg[check_y, check_x])
                
                pixel_diff = sum(abs(p - t) for p, t in zip(pixel_bgr, offset_bgr))
                if pixel_diff > max_diff:
                    all_match = False
                    break
            
            if all_match:
                pixel_bgr = tuple(int(v) for v in roi[i, j])
                del bg, roi, diff, match_mask
                return True, {
                    "target_x": int(found_x),
                    "target_y": int(found_y),
                    "pixel_color": f"#{pixel_bgr[2]:02x}{pixel_bgr[1]:02x}{pixel_bgr[0]:02x}",
                    "matched": True
                }, "找到颜色"

        del bg, roi, diff, match_mask
        return False, {"matched": False}, "未找到匹配颜色"
    except Exception as e:
        return False, {}, str(e)

