class User32Mouse:
    @staticmethod
    def get_cursor_pos() -> Tuple[int, int]:
        if kmbox_mouse_active():
            try:
                return kmbox_manager.get_cursor_pos()
            except Exception:
                pass
        try:
            p = POINT()
            if user32.GetCursorPos(ctypes.byref(p)):
                return (int(p.x), int(p.y))
            return (0, 0)
        except Exception as e:
            return (0, 0)

    @staticmethod
    def absolute_move(x: int, y: int, confirm=True) -> bool:
        if kmbox_mouse_active():
            if kmbox_manager.absolute_move(x, y, confirm):
                if confirm:
                    time.sleep(0.02)
                    current_x, current_y = User32Mouse.get_cursor_pos()
                    if abs(current_x - x) <= 5 and abs(current_y - y) <= 5:
                        return True
                    debug_print(f"[盒子路由] 警告：盒子执行后位置验证失败，当前位置 ({current_x}, {current_y})，目标位置 ({x}, {y})")
                else:
                    return True
        try:
            x, y = int(x), int(y)
            screen_width = user32.GetSystemMetrics(0)
            screen_height = user32.GetSystemMetrics(1)
            user32.mouse_event(
                MOUSEEVENTF_ABSOLUTE | MOUSEEVENTF_MOVE,
                int(x * 65535 // screen_width),
                int(y * 65535 // screen_height),
                0,
                0
            )
            if confirm:
                time.sleep(0.01)
                for _ in range(3):
                    current_x, current_y = User32Mouse.get_cursor_pos()
                    if abs(current_x - x) <= 3 and abs(current_y - y) <= 3:
                        return True
                    user32.mouse_event(
                        MOUSEEVENTF_ABSOLUTE | MOUSEEVENTF_MOVE,
                        int(x * 65535 // screen_width),
                        int(y * 65535 // screen_height),
                        0,
                        0
                    )
                    time.sleep(0.005)
                SetCursorPos(x, y)
                time.sleep(0.005)
            return True
        except Exception as e:
            print(f"绝对移动失败: {str(e)}")
            return False

    @staticmethod
    def relative_move(dx: int, dy: int) -> bool:
        if kmbox_mouse_active():
            if not kmbox_manager.relative_move(dx, dy):
                pass
            else:
                return True
        try:
            dx, dy = int(dx), int(dy)
            user32.mouse_event(MOUSEEVENTF_MOVE, dx, dy, 0, 0)
            return True
        except Exception as e:
            print(f"移动失败: {str(e)}")
            return False

    @staticmethod
    def bezier_move_to(target_x, target_y, amplitude=50, randomness=30, speed=1.0, stop_event=None):
        """贝塞尔曲线模拟真人鼠标移动"""
        target_x, target_y = int(target_x), int(target_y)
        
        if kmbox_mouse_active():
            if kmbox_manager.bezier_move_to(target_x, target_y, amplitude, randomness, speed):
                return True
        
        start_x, start_y = User32Mouse.get_cursor_pos()

        dx = target_x - start_x
        dy = target_y - start_y
        distance = math.sqrt(dx * dx + dy * dy)

        if distance < 3:
            User32Mouse.absolute_move(target_x, target_y)
            return True

        perp_x = -dy / distance
        perp_y = dx / distance

        rand_factor = max(0.0, min(1.0, randomness / 100.0))
        offset1 = amplitude * (1.0 + (random.random() - 0.5) * 2.0 * rand_factor)
        offset2 = amplitude * (1.0 + (random.random() - 0.5) * 2.0 * rand_factor)
        if random.random() > 0.5:
            offset1 = -offset1
        if random.random() > 0.5:
            offset2 = -offset2

        cp1_x = start_x + dx * 0.3 + perp_x * offset1
        cp1_y = start_y + dy * 0.3 + perp_y * offset1
        cp2_x = start_x + dx * 0.7 + perp_x * offset2
        cp2_y = start_y + dy * 0.7 + perp_y * offset2

        num_steps = max(10, min(100, int(distance / 5)))
        total_time = (distance * 0.002) / max(0.1, speed)
        step_delay = total_time / num_steps

        for i in range(1, num_steps + 1):
            if stop_event and stop_event.is_set():
                return False
            t = i / num_steps
            if t < 0.5:
                eased_t = 4 * t * t * t
            else:
                eased_t = 1 - pow(-2 * t + 2, 3) / 2

            u = 1 - eased_t
            px = u*u*u*start_x + 3*u*u*eased_t*cp1_x + 3*u*eased_t*eased_t*cp2_x + eased_t*eased_t*eased_t*target_x
            py = u*u*u*start_y + 3*u*u*eased_t*cp1_y + 3*u*eased_t*eased_t*cp2_y + eased_t*eased_t*eased_t*target_y

            User32Mouse.absolute_move(int(px), int(py), confirm=False)
            time.sleep(step_delay)

        User32Mouse.absolute_move(target_x, target_y, confirm=True)
        return True

    @staticmethod
    def minimum_jerk_move(target_x, target_y, steps=80, noise_min=1.0, noise_max=2.5, pause_chance=0.5, offset_min=1.0, offset_max=2.0, hover_min=100, hover_max=250, speed=1.0, stop_event=None):
        """Minimum-Jerk最小加加速度模型模拟硬件真人操作"""
        target_x, target_y = int(target_x), int(target_y)
        
        if kmbox_mouse_active():
            if kmbox_manager.bezier_move_to(target_x, target_y, 
                                           amplitude=int(noise_max * 10), 
                                           randomness=int(noise_max * 20), 
                                           speed=speed):
                return True
        
        cur_x, cur_y = User32Mouse.get_cursor_pos()

        dx = target_x - cur_x
        dy = target_y - cur_y
        distance = math.sqrt(dx * dx + dy * dy)

        if distance < 3:
            User32Mouse.absolute_move(target_x, target_y)
            return True

        try:
            import numpy as np
            has_np = True
        except ImportError:
            has_np = False

        if noise_min > noise_max:
            noise_min, noise_max = noise_max, noise_min
        if offset_min > offset_max:
            offset_min, offset_max = offset_max, offset_min
        if hover_min > hover_max:
            hover_min, hover_max = hover_max, hover_min

        def get_noise(ratio):
            noise_scale = random.uniform(noise_min, noise_max)
            if has_np:
                if ratio > 0.85:
                    return np.random.normal(0, noise_scale * 0.3)
                else:
                    return np.random.normal(0, noise_scale)
            else:
                if ratio > 0.85:
                    return (random.random() - 0.5) * noise_scale * 0.6
                else:
                    return (random.random() - 0.5) * noise_scale * 2.0

        def get_delay():
            if has_np:
                return np.clip(np.random.normal(10 / speed, 1.5), 7 / speed, 14 / speed)
            else:
                base = 10 / speed
                return max(base - 3, min(base + 3, base + (random.random() - 0.5) * 3))

        points = []
        for i in range(steps):
            t = i / (steps - 1)
            tj = 10 * (t ** 3) - 15 * (t ** 4) + 6 * (t ** 5)
            px = cur_x + (target_x - cur_x) * tj
            py = cur_y + (target_y - cur_y) * tj

            noise_x = get_noise(t)
            noise_y = get_noise(t)
            points.append((round(px + noise_x), round(py + noise_y)))

        pause_idx = -1
        pause_ms = 0
        if distance > 120 and random.random() < pause_chance:
            pause_idx = random.randint(int(steps * 0.4), int(steps * 0.7))
            if has_np:
                pause_ms = int(np.clip(np.random.normal(90, 20), 50, 150))
            else:
                pause_ms = random.randint(50, 150)

        prev_x, prev_y = cur_x, cur_y
        for idx, (px, py) in enumerate(points):
            if stop_event and stop_event.is_set():
                return False

            dx_step = px - prev_x
            dy_step = py - prev_y

            if dx_step != 0 or dy_step != 0:
                # 路由到 kmbox（启用时）或 user32（未启用时）
                User32Mouse.relative_move(int(dx_step), int(dy_step))

            prev_x, prev_y = px, py

            if idx == pause_idx and pause_ms > 0:
                time.sleep(pause_ms / 1000)

            time.sleep(get_delay() / 1000)

        adjust_count = random.randint(3, 5)
        adjust_coords = []
        for _ in range(adjust_count):
            end_offset = random.uniform(offset_min, offset_max)
            if has_np:
                off_x = np.random.normal(0, end_offset)
                off_y = np.random.normal(0, end_offset)
            else:
                off_x = (random.random() - 0.5) * end_offset * 2
                off_y = (random.random() - 0.5) * end_offset * 2
            adjust_coords.append((round(target_x + off_x), round(target_y + off_y)))
        adjust_coords.append((target_x, target_y))

        for px, py in adjust_coords:
            if stop_event and stop_event.is_set():
                return False

            dx_step = px - prev_x
            dy_step = py - prev_y

            if dx_step != 0 or dy_step != 0:
                # 路由到 kmbox（启用时）或 user32（未启用时）
                User32Mouse.relative_move(int(dx_step), int(dy_step))

            prev_x, prev_y = px, py
            time.sleep(get_delay() / 1000)

        if hover_max > 0:
            if has_np:
                actual_hover = np.clip(int(np.random.normal((hover_min + hover_max) / 2, (hover_max - hover_min) / 3)), hover_min, hover_max)
            else:
                actual_hover = random.randint(hover_min, hover_max)
            time.sleep(actual_hover / 1000)

        User32Mouse.absolute_move(target_x, target_y, confirm=True)
        return True

    @staticmethod
    def left_down(x=None, y=None):
        if kmbox_mouse_active():
            if kmbox_manager.left_down(x, y):
                return True
        try:
            if x is not None: User32Mouse.absolute_move(x, y)
            user32.mouse_event(MOUSEEVENTF_LEFTDOWN, 0, 0, 0, 0)
            return True
        except Exception as e:
            return False

