def apply_modern_font(widget):
    font = QFont("Microsoft YaHei", 10)
    font.setWeight(QFont.Weight.DemiBold)
    font.setStyleStrategy(QFont.StyleStrategy.PreferAntialias | QFont.StyleStrategy.PreferQuality)
    widget.setFont(font)

def setup_form_layout(form_layout, label_min_width=80):
    """为QFormLayout设置统一的label宽度和间距，防止按钮/控件重叠"""
    form_layout.setLabelAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
    form_layout.setHorizontalSpacing(12)
    form_layout.setVerticalSpacing(8)
    form_layout.setFieldGrowthPolicy(QFormLayout.FieldGrowthPolicy.ExpandingFieldsGrow)
    form_layout.setFormAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)

def _form_label(text, min_width=80):
    """创建固定宽度的表单Label，防止与输入控件重叠"""
    lbl = QLabel(text)
    lbl.setMinimumWidth(min_width)
    lbl.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
    lbl.setStyleSheet(f"color: {COLOR_TEXT}; font-weight: 500; font-size: 12px;")
    return lbl

# ── 自定义 QProxyStyle：为 QTreeWidget 绘制漂亮的折叠/展开箭头 ──
class TreeArrowStyle(QProxyStyle):
    """自定义风格折叠箭头：紧凑的 > / v 形图标，用主题色"""
    def drawPrimitive(self, element, option, painter, widget):
        if element == QStyle.PrimitiveElement.PE_IndicatorBranch:
            # 不绘制默认的展开/折叠指示器
            return
        super().drawPrimitive(element, option, painter, widget)

    def drawControl(self, element, option, painter, widget):
        if element == QStyle.ControlElement.CE_ItemViewItem:
            # 委托给父类处理基本绘制
            super().drawControl(element, option, painter, widget)

            # 然后在适当位置画箭头
            if widget and isinstance(widget, QTreeWidget):
                item = widget.itemAt(option.rect.center())
                if item and item.childCount() > 0:
                    self._draw_branch_arrow(painter, option, item, widget)
            return
        super().drawControl(element, option, painter, widget)

    def _draw_branch_arrow(self, painter, option, item, tree_widget):
        """绘制展开/折叠箭头 —— chevron 风格（类似 VS Code / Windows 资源管理器）"""
        indent = tree_widget.indentation()
        level = 0
        p = item.parent()
        while p:
            level += 1
            p = p.parent()

        if hasattr(tree_widget, '_INDENT'):
            x = option.rect.left() + 8 + tree_widget._INDENT * level
        else:
            x = option.rect.left() + 8 + indent * level
        y = option.rect.center().y()
        arrow_size = 5

        is_expanded = item.isExpanded()

        painter.save()
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)

        from PySide6.QtGui import QPen, QPainterPath
        from PySide6.QtCore import QPointF

        color = QColor("#6B7280")
        pen = QPen(color, 1.5)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
        painter.setPen(pen)
        painter.setBrush(Qt.BrushStyle.NoBrush)

        if is_expanded:
            # 向下 chevron: ⌄
            path = QPainterPath()
            path.moveTo(x - arrow_size, y - arrow_size * 0.3)
            path.lineTo(x, y + arrow_size * 0.5)
            path.lineTo(x + arrow_size, y - arrow_size * 0.3)
        else:
            # 向右 chevron: >
            path = QPainterPath()
            path.moveTo(x - arrow_size * 0.4, y - arrow_size)
            path.lineTo(x + arrow_size * 0.5, y)
            path.lineTo(x - arrow_size * 0.4, y + arrow_size)

        painter.drawPath(path)
        painter.restore()


def _make_arrow_pixmap(expanded: bool, size=12, color="#6B7280") -> QPixmap:
    """生成下拉箭头 Pixmap（实心三角形，稳定渲染）"""
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.GlobalColor.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    painter.setPen(Qt.PenStyle.NoPen)
    painter.setBrush(QColor(color))
    from PySide6.QtGui import QPainterPath
    path = QPainterPath()
    if expanded:
        # 向下实心三角（常规下拉箭头）
        path.moveTo(size * 0.20, size * 0.36)
        path.lineTo(size * 0.80, size * 0.36)
        path.lineTo(size * 0.50, size * 0.70)
    else:
        # 向右实心三角
        path.moveTo(size * 0.36, size * 0.20)
        path.lineTo(size * 0.36, size * 0.80)
        path.lineTo(size * 0.70, size * 0.50)
    path.closeSubpath()
    painter.drawPath(path)
    painter.end()
    return pixmap

def _make_svg_icon(svg_content, size=16):
    """从 SVG 字符串生成 QIcon"""
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.GlobalColor.transparent)
    from PySide6.QtSvgWidgets import QSvgWidget
    from PySide6.QtSvg import QSvgRenderer
    renderer = QSvgRenderer(svg_content.encode('utf-8'))
    if renderer.isValid():
        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        renderer.render(painter)
        painter.end()
    return QIcon(pixmap)

def _create_icon(draw_func, size=20):
    """用自定义绘制函数创建 QIcon"""
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.GlobalColor.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    draw_func(painter, size)
    painter.end()
    return QIcon(pixmap)

