        def _paint_toggle(event):
            painter = QPainter(self.threaded_cb)
            painter.setRenderHint(QPainter.RenderHint.Antialiasing)
            opt = QStyleOptionButton()
            self.threaded_cb.initStyleOption(opt)
            is_checked = self.threaded_cb.isChecked()
            # 绘制轨道
            track_color = QColor(HW_GREEN if is_checked else HW_TOGGLE_OFF)
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(track_color)
            painter.drawRoundedRect(0, 0, 50, 26, 13, 13)
            # 绘制轨道边框
            painter.setPen(QColor(HW_BORDER))
            painter.setBrush(Qt.BrushStyle.NoBrush)
            painter.drawRoundedRect(0, 0, 50, 26, 13, 13)
            # 绘制旋钮
            knob_x = 26 if is_checked else 2
            knob_color = QColor("#ffffff")
            painter.setPen(Qt.PenStyle.NoPen)
            painter.setBrush(knob_color)
            painter.drawEllipse(knob_x, 3, 20, 20)
            # 旋钮阴影
            if is_checked:
                glow = QColor(HW_GREEN_GLOW)
                painter.setPen(Qt.PenStyle.NoPen)
                painter.setBrush(glow)
                painter.drawEllipse(knob_x, 3, 20, 20)
                painter.setBrush(knob_color)
                painter.drawEllipse(knob_x+1, 4, 18, 18)
            painter.end()
            event.accept()
        self.threaded_cb.paintEvent = _paint_toggle
        self.threaded_cb.toggled.connect(self._on_hw_thread_toggled)
        self.threaded_cb.toggled.connect(self._on_threaded_toggled)
