        self.spin_timeout.setRange(0, 999999); self.spin_timeout.setValue(self.cfg.get("timeout", 5000))
        self.spin_timeout.setSuffix(" ms"); self.spin_timeout.setSpecialValueText("无限等待"); self.spin_timeout.setFixedWidth(90)

        self.combo_timeout_action = QComboBox()
