        self.spin_offset_x.setFixedWidth(62); self.spin_offset_y.setFixedWidth(62)

        # Grid: 第0行=方式+容差，第1行=间隔+超时+超时处理，第2行=偏移XY+动作
        g2_layout.addWidget(QLabel("方式"), 0, 0); g2_layout.addWidget(self.combo_wait_mode, 0, 1)
        g2_layout.addWidget(QLabel("容差"), 0, 2); g2_layout.addWidget(self.spin_tolerance, 0, 3)
        g2_layout.addWidget(QLabel("间隔"), 1, 0); g2_layout.addWidget(self.spin_interval, 1, 1)
        g2_layout.addWidget(QLabel("超时"), 1, 2); g2_layout.addWidget(self.spin_timeout, 1, 3)
        g2_layout.addWidget(self.combo_timeout_action, 1, 4)
