        g2_layout.addWidget(QLabel("偏移Y"), 2, 2); g2_layout.addWidget(self.spin_offset_y, 2, 3)
        g2_layout.addWidget(QLabel("动作"), 2, 4); g2_layout.addWidget(self.combo_click, 2, 5)

        g2.setLayout(g2_layout); layout.addWidget(g2)

        # 第四行：调试工具（紧凑单行）
