        self.edit_varname.setFixedWidth(80)
        self.lbl_debug_status = QLabel("就绪"); self.lbl_debug_status.setFixedWidth(70)
        self.lbl_debug_coords = QLabel("--"); self.lbl_debug_coords.setFixedWidth(100)
        self.lbl_debug_color = QLabel("--"); self.lbl_debug_color.setFixedWidth(80)
        g_debug_layout.addWidget(self.btn_debug)
        g_debug_layout.addWidget(QLabel("变量:")); g_debug_layout.addWidget(self.edit_varname)
        g_debug_layout.addWidget(self.lbl_debug_status)
        g_debug_layout.addWidget(self.lbl_debug_coords)
