        self.combo_action = QComboBox()
        self.combo_action.addItems(list(self.action_map.keys()))
        self.combo_action.setFixedHeight(26)
        self.combo_action.setMinimumWidth(100)
        self.btn_test = QPushButton("🎯 测试")
        self.btn_test.setObjectName("btn_test")
        self.btn_test.setFixedWidth(64)
        self.btn_test.setFixedHeight(26)
        self.btn_test.setCursor(Qt.CursorShape.PointingHandCursor)
        self.btn_test.clicked.connect(self._test_action)
        row0.addWidget(QLabel("名称:"))
        row0.addWidget(self.edit_taskname)
        row0.addSpacing(6)
        row0.addWidget(QLabel("动作:"))
        row0.addWidget(self.combo_action, 1)
        row0.addWidget(self.btn_test)
        layout.addLayout(row0)

        # 第二行：查找范围（XYWH + 框选按钮）
        g1 = QGroupBox("查找范围")
