        g1_layout.setSpacing(6)
        g1_layout.setContentsMargins(8, 4, 8, 4)
        self.spin_x = QSpinBox()
        self.spin_y = QSpinBox()
        self.spin_w = QSpinBox()
        self.spin_h = QSpinBox()
        for w in [self.spin_x, self.spin_y, self.spin_w, self.spin_h]:
            w.setFixedHeight(24)
            w.setFixedWidth(64)
        self.spin_x.setRange(0, 99999)
        self.spin_y.setRange(0, 99999)
        self.spin_w.setRange(1, 99999)
        self.spin_h.setRange(1, 99999)
        self.btn_area = QPushButton("框选")
        self.btn_area.setObjectName("btn_area")
