        self.btn_area.clicked.connect(self._sel_area)
        g1_layout.addWidget(QLabel("X"))
        g1_layout.addWidget(self.spin_x)
        g1_layout.addSpacing(4)
        g1_layout.addWidget(QLabel("Y"))
        g1_layout.addWidget(self.spin_y)
        g1_layout.addSpacing(4)
        g1_layout.addWidget(QLabel("W"))
        g1_layout.addWidget(self.spin_w)
        g1_layout.addSpacing(4)
        g1_layout.addWidget(QLabel("H"))
        g1_layout.addWidget(self.spin_h)
