        # 第三行：动作参数（按下时长 + 抬起后等待 + 击键间隔 合并一行）
        g2 = QGroupBox("动作参数")
        g2_layout = QHBoxLayout()
        g2_layout.setSpacing(6)
        g2_layout.setContentsMargins(8, 4, 8, 4)
        self.spin_duration = QSpinBox()
        self.spin_duration.setRange(1, 999999)
        self.spin_duration.setSuffix(" ms")
