    def _init_data(self):
        self.edit_taskname.setText(self.cfg.get("task_name", "随机多点击"))
        self.spin_duration.setValue(int(self.cfg.get("duration", 50)))
        self.spin_up_delay.setValue(int(self.cfg.get("up_delay", 50)))
        items = self.cfg.get("click_items", [])
        for item in items:
            self._add_row(item.get("x", 0), item.get("y", 0), item.get("action_type", "left_click"))

    def _add_row(self, x=0, y=0, action_type="left_click"):
        row = self.table.rowCount()
        self.table.insertRow(row)
        spin_x = QSpinBox()
        spin_x.setRange(-99999, 99999)
        spin_x.setValue(int(x))
        self.table.setCellWidget(row, 0, spin_x)
        spin_y = QSpinBox()
        spin_y.setRange(-99999, 99999)
        spin_y.setValue(int(y))
        self.table.setCellWidget(row, 1, spin_y)
        combo_action = QComboBox()
        for name in self.action_map.keys():
            combo_action.addItem(name)
        action_name = self.reverse_action_map.get(action_type, "左键单击")
        combo_action.setCurrentText(action_name)
        self.table.setCellWidget(row, 2, combo_action)

    def _add_item(self):
        self._add_row(100, 100, "left_click")
        self.table.selectRow(self.table.rowCount() - 1)

    def _del_item(self):
        row = self.table.currentRow()
        if row >= 0 and self.table.rowCount() > 1:
            self.table.removeRow(row)
        elif self.table.rowCount() <= 1:
            QMessageBox.warning(self, "提示", "至少保留一个点击项")

    def _on_ok(self):
        task_name = self.edit_taskname.text().strip() or "随机多点击"
        click_items = []
        for row in range(self.table.rowCount()):
            spin_x = self.table.cellWidget(row, 0)
            spin_y = self.table.cellWidget(row, 1)
            combo_action = self.table.cellWidget(row, 2)
            x = spin_x.value() if spin_x else 0
            y = spin_y.value() if spin_y else 0
            action_name = combo_action.currentText() if combo_action else "左键单击"
            action_type = self.action_map.get(action_name, "left_click")
            click_items.append({"x": x, "y": y, "action_type": action_type})
        if not click_items:
            QMessageBox.warning(self, "提示", "请至少添加一个点击项")
            return
        cfg = {
            "task_name": task_name,
            "click_items": click_items,
            "duration": self.spin_duration.value(),
            "up_delay": self.spin_up_delay.value(),
        }
        self.saved.emit(cfg)
        self.accept()

    def keyPressEvent(self, event):
        """按F1快捷记录当前鼠标坐标，添加为新的点击项"""
        if event.key() == Qt.Key.Key_F1:
            self._record_current_pos()
            event.accept()
            return
        super().keyPressEvent(event)

    def _record_current_pos(self):
        """记录当前鼠标坐标，添加为新的点击项"""
        global_pos = QCursor.pos()
        x, y = global_pos.x(), global_pos.y()

        # 添加新行
        self._add_row(x, y, "left_click")
        new_row = self.table.rowCount() - 1
        self.table.selectRow(new_row)

        # 高亮反馈
        highlight_style = """
            QSpinBox {
                background-color: #DBEAFE;
                color: #1E40AF;
                font-weight: bold;
            }
        """
        normal_style = ""
        spin_x = self.table.cellWidget(new_row, 0)
        spin_y = self.table.cellWidget(new_row, 1)
        if spin_x:
            spin_x.setStyleSheet(highlight_style)
        if spin_y:
            spin_y.setStyleSheet(highlight_style)
        QTimer.singleShot(500, lambda: (
            spin_x.setStyleSheet(normal_style) if spin_x else None,
            spin_y.setStyleSheet(normal_style) if spin_y else None,
        ))


