        hint.setStyleSheet(f"color: {COLOR_TEXT_SECONDARY}; font-size: 11px; padding: 8px; background-color: #F5F7FA; border-radius: 4px;")
        layout.addWidget(hint)

        btn_row = QHBoxLayout()
