    def _open_key_capture(self):
        """打开按键获取对话框"""
        dialog = KeyCaptureDialog(self)
        if dialog.exec() == QDialog.DialogCode.Accepted:
            key = dialog.get_key()
            if key:
                self.current_key = key
                self._update_ui()

    def _update_ui(self):
        display_text = self.current_key if self.current_key else ""
        self.edit_key.setText(display_text)

    def _save(self):
        if not self.current_key:
            self.current_key = "A"
        config = {
            "key": self.current_key,
            "action": self.combo_action.currentData(),
            "duration": self.spin_duration.value(),
            "up_delay": self.spin_up_delay.value(),
            "remark": self.edit_remark.text() if hasattr(self, 'edit_remark') else ""
        }
        self.saved.emit(config)
        self.accept()

