        self.edit_path.setPlaceholderText("选择参考图...")
        self.edit_path.setStyleSheet("padding: 4px 8px; border: 1px solid #ccc; border-radius: 4px; background: white;")
        self.edit_path.setFixedHeight(28)
        
        self.btn_resource = QPushButton("资源库")
        self.btn_resource.setFixedSize(60, 28)
        self.btn_resource.setCursor(Qt.CursorShape.PointingHandCursor)
        self.btn_resource.clicked.connect(self._sel_img_from_resource)
        self.btn_resource.setEnabled(len(self.screenshots) > 0)
        
        self.btn_path = QPushButton("选择图片")
        self.btn_path.setFixedSize(80, 28)
        self.btn_path.setCursor(Qt.CursorShape.PointingHandCursor)
