        path_layout.addWidget(self.edit_path, 1)
        path_layout.addWidget(self.btn_resource)
        path_layout.addWidget(self.btn_path)
        layout.addLayout(path_layout)
        
        # 已保存截图选择
        self.combo_screenshot = None
        self.thumbnail_label = None
