    def _sel_img_file(self):
        path, _ = QFileDialog.getOpenFileName(self, "选择图片", "", "图片文件 (*.png *.jpg *.bmp)")
        if path:
            self.edit_path.setText(path)
            self._update_thumbnail(path)
    
    def _sel_img_from_resource(self):
        if not self.screenshots:
            return
        items = [s['name'] for s in self.screenshots]
        item, ok = QInputDialog.getItem(self, "选择截图", "截图列表:", items, 0, False)
        if ok and item:
            idx = items.index(item)
            self.combo_screenshot.setCurrentIndex(idx)
            self._on_screenshot_selected(idx)
    
    def _on_screenshot_selected(self, index):
        if 0 <= index < len(self.screenshots):
            s = self.screenshots[index]
            self.edit_path.setText(s['path'])
            self._update_thumbnail(s['path'])
            self.cfg["last_selected_index"] = index
    
    def _update_thumbnail(self, path):
        if not path or not os.path.exists(path) or not self.thumbnail_label:
            return
        pixmap = QPixmap(path)
        if not pixmap.isNull():
            self.thumbnail_label.setPixmap(pixmap.scaled(64, 64, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation))
    
    def _select_screen_area(self):
        try:
            self.setVisible(False)
            QApplication.processEvents()
            
            self._select_dialog = ScreenSelectWindow(self)
            
            def on_selected(rect):
                x, y, w, h = rect
                self.spin_x.setValue(x)
                self.spin_y.setValue(y)
                self.spin_w.setValue(w)
                self.spin_h.setValue(h)
                self.setVisible(True)
                self.raise_()
                self.activateWindow()
                self._select_dialog = None
            
            def on_cancelled():
                self.setVisible(True)
                self.raise_()
                self.activateWindow()
                self._select_dialog = None
            
            self._select_dialog.selected.connect(on_selected)
            self._select_dialog.cancelled.connect(on_cancelled)
        except Exception as e:
            self.setVisible(True)
            QMessageBox.critical(self, "错误", f"区域选择失败：{str(e)}")
    
    def _debug_test(self):
        img_path = self.edit_path.text().strip()
        if not img_path or not os.path.exists(img_path):
            QMessageBox.warning(self, "提示", "请先选择参考图片！")
            return
        
        self.lbl_debug_status.setText("调试中...")
        self.lbl_debug_status.setStyleSheet("color: #E6A23C; font-weight: bold;")
        
        QTimer.singleShot(50, self._do_debug)
    
    def _do_debug(self):
        try:
            img_path = self.edit_path.text().strip()
            threshold = self.spin_threshold.value() / 100.0
            x = self.spin_x.value()
            y = self.spin_y.value()
            w = self.spin_w.value()
            h = self.spin_h.value()
            motion_thresh = self.spin_motion_threshold.value() / 100.0
            motion_times = self.spin_motion_times.value()
            motion_interval = self.spin_motion_interval.value() / 1000.0
            
            hwnd = getattr(self._main_win, 'bound_hwnd', 0) if self._main_win else 0
            
            # 先找图
            success, data, msg = perform_image_match(img_path, x, y, w, h, hwnd=hwnd)
            
            if not success:
                self.lbl_debug_status.setText("失败")
                self.lbl_debug_status.setStyleSheet("color: #F56C6C; font-weight: bold;")
                self.lbl_debug_coords.setText("--")
                self.lbl_debug_motion.setText("运动: --")
                QMessageBox.critical(self, "错误", msg)
                return
            
            max_val = data['max_val']
            target_x = data['target_x']
            target_y = data['target_y']
            
            if max_val < threshold:
                self.lbl_debug_status.setText("未找到")
                self.lbl_debug_status.setStyleSheet("color: #F56C6C; font-weight: bold;")
                self.lbl_debug_coords.setText(f"({target_x}, {target_y})")
                self.lbl_debug_motion.setText(f"相似度:{max_val*100:.1f}%")
                return
            
            # 验证运动
            tw, th = 50, 50
            try:
                tpl = get_embedded_image(img_path)
                if tpl is None and os.path.exists(img_path):
                    arr = np.fromfile(img_path, dtype=np.uint8)
                    tpl = cv2.imdecode(arr, cv2.IMREAD_COLOR)
                if tpl is not None:
                    tw, th = tpl.shape[1], tpl.shape[0]
            except:
                pass
            
            self.lbl_debug_coords.setText(f"({target_x}, {target_y})")
            self.lbl_debug_status.setText("检测运动中...")
            self.lbl_debug_status.setStyleSheet("color: #409EFF; font-weight: bold;")
            
            self._motion_thread = MotionDetectionThread(
                target_x, target_y,
                w=tw, h=th,
                times=motion_times, threshold=motion_thresh,
                interval=motion_interval, hwnd=hwnd
            )
            
            def on_motion_detected(is_moving, motion_ratio):
                self.lbl_debug_motion.setText(f"运动:{motion_ratio*100:.1f}%")
                if is_moving:
                    self.lbl_debug_status.setText("找到动图")
                    self.lbl_debug_status.setStyleSheet("color: #67C23A; font-weight: bold;")
                else:
                    self.lbl_debug_status.setText("图不动")
                    self.lbl_debug_status.setStyleSheet("color: #E6A23C; font-weight: bold;")
                self._motion_thread = None
            
            self._motion_thread.finished.connect(on_motion_detected)
            self._motion_thread.start()
        
        except Exception as e:
            self.lbl_debug_status.setText("错误")
            self.lbl_debug_status.setStyleSheet("color: #F56C6C; font-weight: bold;")
            QMessageBox.critical(self, "错误", f"调试失败：{str(e)}")
    
    def _save(self):
        img_path = self.edit_path.text().strip()
        if not img_path:
            QMessageBox.warning(self, "提示", "请选择参考图片！")
            return
        
        config = {
            "task_name": self.edit_taskname.text(),
            "image_path": img_path,
            "threshold": self.spin_threshold.value(),
            "x": self.spin_x.value(),
            "y": self.spin_y.value(),
            "width": self.spin_w.value(),
            "height": self.spin_h.value(),
            "offset_x": self.spin_offset_x.value(),
            "offset_y": self.spin_offset_y.value(),
            "click_action": self.combo_click.currentText(),
            "motion_threshold": self.spin_motion_threshold.value(),
            "motion_check_times": self.spin_motion_times.value(),
            "motion_interval": self.spin_motion_interval.value(),
            "var_name": self.edit_var.text(),
            "last_selected_index": self.cfg.get("last_selected_index", 0)
        }
        # 立即声明变量，确保其他功能立即可用
        if self._main_win and hasattr(self._main_win, 'variables') and self._main_win.variables:
            self._main_win.variables.declare_from_config(config)
        self.saved.emit(config)
        self.accept()

