        btn_ok.setMinimumHeight(30); btn_ok.setMinimumWidth(80)
        btn_ok.setCursor(Qt.CursorShape.PointingHandCursor)
        btn_ok.setStyleSheet(STYLE_BTN_PRIMARY)
        def save_data():
            data = {
                "var_name": self.edit_varname.text().strip(),
                "format": self.combo_format.currentIndex(),
                "remark": self.remark_input.toPlainText().strip()
            }
            self.saved.emit(data)
            self.accept()
