        l.addWidget(lbl)

        self.radio_success = QRadioButton("上一步成功")
        self.radio_fail = QRadioButton("上一步失败")
        self.radio_success.setStyleSheet(f"font-size: 13px; color: {COLOR_TEXT};")
        self.radio_fail.setStyleSheet(f"font-size: 13px; color: {COLOR_TEXT};")

        cond = self.cfg.get("condition", "上一步成功")
        if cond == "上一步失败":
            self.radio_fail.setChecked(True)
        else:
            self.radio_success.setChecked(True)

        bg = QButtonGroup(self)
        bg.addButton(self.radio_success)
        bg.addButton(self.radio_fail)

