        btn_cancel = QPushButton("取消")
        btn_cancel.setMinimumHeight(30); btn_cancel.setMinimumWidth(80)
        btn_cancel.setCursor(Qt.CursorShape.PointingHandCursor)
        btn_cancel.setStyleSheet(STYLE_BTN_DEFAULT)
