# 变量选择对话框
class VariableSelectDialog(QDialog):
    def __init__(self, parent=None, variables=None):
        super().__init__(parent)
        self.setWindowTitle("选择变量")
        self.setMinimumSize(400, 300)
        apply_window_icon(self)
        apply_modern_font(self)
        self.selected_var = None
        self.variables = variables or []
        self._init_ui()

    def _init_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(16, 16, 16, 12)
        layout.setSpacing(10)
        self.setStyleSheet(f"background-color: {COLOR_BG};")

        # 搜索框
        search_layout = QHBoxLayout()
        self.edit_search = QLineEdit()
        self.edit_search.setPlaceholderText("搜索变量...")
        self.edit_search.setClearButtonEnabled(True)  # 【视觉优化】输入内容后显示×一键清空
        self.edit_search.setStyleSheet(STYLE_INPUT)
        self.edit_search.textChanged.connect(self._filter_vars)
        search_layout.addWidget(self.edit_search)
        layout.addLayout(search_layout)

        # 变量列表
        self.list_vars = QListWidget()
        self.list_vars.setStyleSheet(f"""
            QListWidget {{
                background-color: {COLOR_CARD};
                border: 1px solid {COLOR_BORDER};
                border-radius: 8px;
                font-size: 13px;
            }}
            QListWidget::item {{
                padding: 8px 12px;
                border-bottom: 1px solid {COLOR_BORDER};
            }}
            QListWidget::item:last {{
                border-bottom: none;
            }}
            QListWidget::item:hover {{
                background-color: {COLOR_PRIMARY_LIGHT};
            }}
            QListWidget::item:selected {{
                background-color: {COLOR_PRIMARY};
                color: white;
            }}
        """)
        self.list_vars.itemDoubleClicked.connect(self._on_select)
        layout.addWidget(self.list_vars)

        # 按钮
        btn_layout = QHBoxLayout()
        btn_layout.addStretch()
        btn_ok = QPushButton("确定")
        btn_ok.setMinimumHeight(30)
        btn_ok.setMinimumWidth(80)
        btn_ok.setCursor(Qt.CursorShape.PointingHandCursor)
        btn_ok.setStyleSheet(STYLE_BTN_PRIMARY)
        btn_ok.clicked.connect(self._on_select)
        btn_cancel = QPushButton("取消")
        btn_cancel.setMinimumHeight(30)
        btn_cancel.setMinimumWidth(80)
        btn_cancel.setCursor(Qt.CursorShape.PointingHandCursor)
        btn_cancel.setStyleSheet(STYLE_BTN_DEFAULT)
        btn_cancel.clicked.connect(self.reject)
        btn_layout.addWidget(btn_ok)
        btn_layout.addWidget(btn_cancel)
        layout.addLayout(btn_layout)

        # 填充变量列表
        self._populate_vars()

    def _populate_vars(self):
        self.list_vars.clear()
        for var in self.variables:
            self.list_vars.addItem(var)

    def _filter_vars(self, text):
        for i in range(self.list_vars.count()):
            item = self.list_vars.item(i)
            item.setHidden(text.lower() not in item.text().lower())

    def _on_select(self):
        items = self.list_vars.selectedItems()
        if items:
            self.selected_var = items[0].text()
            self.accept()

# 增强版变量选择对话框
class VarSelectDialog(QDialog):
    """增强版变量选择对话框 - 完整显示变量名和值"""
    def __init__(self, parent=None, var_data=None, title="选择变量", show_clear=False):
        super().__init__(parent)
        self.setWindowTitle(title)
        self.setMinimumSize(480, 380)
        self.resize(520, 420)
        # 设置窗口标志：标准对话框
        self.setWindowFlags(
            Qt.WindowType.Dialog | 
            Qt.WindowType.WindowContextHelpButtonHint |
            Qt.WindowType.WindowCloseButtonHint
        )
        apply_window_icon(self)
        apply_modern_font(self)
        self.selected_var = None
        self.selected_label = None
        self.var_data = var_data or []
        self.show_clear = show_clear
        self._init_ui()

    def _init_ui(self):
        layout = QVBoxLayout(self)
        layout.setContentsMargins(16, 16, 16, 12)
        layout.setSpacing(10)
        self.setStyleSheet(f"background-color: {COLOR_BG};")

        # 搜索框
        self.edit_search = QLineEdit()
        self.edit_search.setPlaceholderText("搜索变量名称...")
        self.edit_search.setClearButtonEnabled(True)  # 【视觉优化】输入内容后显示×一键清空
        self.edit_search.setStyleSheet(STYLE_INPUT)
        self.edit_search.textChanged.connect(self._filter_vars)
        layout.addWidget(self.edit_search)

        # 使用 QTreeWidget 显示变量名和值
        self.tree = QTreeWidget()
        self.tree.setHeaderLabels(["变量名称", "当前值"])
        self.tree.header().setStretchLastSection(True)
        self.tree.setColumnWidth(0, 220)
        self.tree.setStyleSheet(f"""
            QTreeWidget {{
                background-color: {COLOR_CARD};
                border: 1px solid {COLOR_BORDER};
                border-radius: 8px;
                font-size: 13px;
                outline: none;
            }}
            QTreeWidget::item {{
                padding: 6px 8px;
                border-bottom: 1px solid {COLOR_BORDER};
            }}
            QTreeWidget::item:hover {{
                background-color: {COLOR_PRIMARY_LIGHT};
            }}
            QTreeWidget::item:selected {{
                background-color: {COLOR_PRIMARY};
                color: white;
            }}
            QHeaderView::section {{
                background-color: {COLOR_BG};
                color: {COLOR_TEXT};
                font-weight: bold;
                padding: 6px;
                border: none;
                border-bottom: 2px solid {COLOR_BORDER};
            }}
        """)
        self.tree.itemDoubleClicked.connect(self._on_select)
        layout.addWidget(self.tree)

        # 底部按钮
        btn_layout = QHBoxLayout()
        btn_layout.addStretch()

        btn_clear = None
        if self.show_clear:
            btn_clear = QPushButton("清除绑定")
            btn_clear.setMinimumHeight(30)
            btn_clear.setCursor(Qt.CursorShape.PointingHandCursor)
            btn_clear.setStyleSheet(STYLE_BTN_DEFAULT)
            btn_clear.clicked.connect(self._on_clear)
            btn_layout.addWidget(btn_clear)

        btn_ok = QPushButton("确定")
        btn_ok.setMinimumHeight(30)
        btn_ok.setMinimumWidth(80)
        btn_ok.setCursor(Qt.CursorShape.PointingHandCursor)
        btn_ok.setStyleSheet(STYLE_BTN_PRIMARY)
        btn_ok.clicked.connect(self._on_select)

        btn_cancel = QPushButton("取消")
        btn_cancel.setMinimumHeight(30)
        btn_cancel.setMinimumWidth(80)
        btn_cancel.setCursor(Qt.CursorShape.PointingHandCursor)
        btn_cancel.setStyleSheet(STYLE_BTN_DEFAULT)
        btn_cancel.clicked.connect(self.reject)

        btn_layout.addWidget(btn_ok)
        btn_layout.addWidget(btn_cancel)
        layout.addLayout(btn_layout)

        self._populate_vars()

    def _populate_vars(self):
        self.tree.clear()
        for item_data in self.var_data:
            label = item_data.get("label", "")
            value = item_data.get("value", "")
            data = item_data.get("data", None)
            item = QTreeWidgetItem([label, str(value)])
            item.setData(0, Qt.ItemDataRole.UserRole, data)
            self.tree.addTopLevelItem(item)

        if self.tree.topLevelItemCount() == 0:
            item = QTreeWidgetItem(["(暂无变量)", ""])
            item.setFlags(item.flags() & ~Qt.ItemFlag.ItemIsSelectable)
            self.tree.addTopLevelItem(item)

        # 默认选中第一项
        if self.tree.topLevelItemCount() > 0:
            self.tree.setCurrentItem(self.tree.topLevelItem(0))

    def _filter_vars(self, text):
        text = text.lower()
        for i in range(self.tree.topLevelItemCount()):
            item = self.tree.topLevelItem(i)
            item.setHidden(text not in item.text(0).lower())

    def _on_select(self):
        items = self.tree.selectedItems()
        if items:
            label = items[0].text(0)
            if label == "(暂无变量)":
                QMessageBox.information(self, "提示", "暂无可选变量")
                return
            self.selected_var = items[0].data(0, Qt.ItemDataRole.UserRole)
            self.selected_label = label
            self.accept()

    def _on_clear(self):
        self.selected_var = ('clear', '')
        self.selected_label = "清除变量绑定"
        self.accept()

    @staticmethod
    def get_var_selection(parent, main_win, axis=None, show_clear=False):
        """静态方法：获取变量选择结果
        返回: (selected_data, selected_label) 或 (None, None)
        """
        if not main_win:
            QMessageBox.information(parent, "提示", "无法获取主窗口引用")
            return None, None
        
        if not hasattr(main_win, 'variables'):
            QMessageBox.information(parent, "提示", "暂无可选变量")
            return None, None
        
        variables = main_win.variables
        
        if not variables:
            QMessageBox.information(parent, "提示", "暂无可选变量")
            return None, None

        # 确保变量已声明
        if hasattr(variables, 'declare_from_dialog'):
            variables.declare_from_dialog(parent)

        var_data = []
        for var_name, var_value in variables.items():
            if var_value is None:
                display_value = "运行时获取"
            elif isinstance(var_value, (int, float)):
                display_value = str(var_value)
            elif isinstance(var_value, str) and var_value.isdigit():
                display_value = var_value
            else:
                display_value = str(var_value) if var_value else "运行时获取"
            var_data.append({
                "label": var_name,
                "value": display_value,
                "data": ('var', var_name)
            })
        
        # 添加全局坐标
        if hasattr(main_win, 'global_coordinates') and main_win.global_coordinates:
            for coord in main_win.global_coordinates:
                if all(k in coord for k in ['name', 'x', 'y']):
                    var_data.append({
                        "label": coord['name'],
                        "value": f"坐标({coord['x']}, {coord['y']})",
                        "data": ('coord', coord['x'] if axis == 'x' else coord['y'])
                    })

        title = f"选择{axis.upper()}坐标来源" if axis else "选择变量"
        dlg = VarSelectDialog(parent, var_data, title, show_clear)
        
        # 设置为窗口模态，确保正确交互
        dlg.setWindowModality(Qt.WindowModality.WindowModal)
        
        result = dlg.exec()
        
        if result == QDialog.DialogCode.Accepted and dlg.selected_var is not None:
            return dlg.selected_var, dlg.selected_label
        return None, None

