    def _load_config(self):
        if self.cfg.get("audio_file") or self.cfg.get("audio_original"):
            display_name = self.cfg.get("audio_original") or self.cfg.get("audio_file")
            self.lbl_audio.setText(f"已选择: {display_name}")
            self.lbl_audio.setStyleSheet("color: #67C23A; padding: 6px; background: #f0f9eb; border: 1px solid #ddd; border-radius: 4px;")
            self.btn_preview.setEnabled(True)
        self.edit_remark.setText(self.cfg.get("remark", ""))
        self.btn_color.setStyleSheet(f"background-color: #{self._current_color}; border: 1px solid #ddd; border-radius: 4px;")

    def _get_audio_dir(self):
        if self._main_win and hasattr(self._main_win, 'audio_dir') and self._main_win.audio_dir:
            return self._main_win.audio_dir
        return ""

    def _unique_audio_name(self, audio_dir, basename):
        candidate = basename
        name, ext = os.path.splitext(basename)
        i = 1
        while os.path.exists(os.path.join(audio_dir, candidate)):
            candidate = f"{name}_{i}{ext}"
            i += 1
        return candidate

    def _select_audio(self):
        file_path, _ = QFileDialog.getOpenFileName(
            self, "选择音频文件", "",
            "音频文件 (*.wav *.mp3 *.flac *.ogg *.m4a);;WAV 文件 (*.wav);;所有文件 (*.*)"
        )
        if not file_path:
            return

        audio_dir = self._get_audio_dir()
        if not audio_dir:
            QMessageBox.warning(self, "提示", "当前流程未初始化，无法保存音频")
            return

        try:
            os.makedirs(audio_dir, exist_ok=True)
            fname = self._unique_audio_name(audio_dir, os.path.basename(file_path))
            dest = os.path.join(audio_dir, fname)
            shutil.copy2(file_path, dest)

            self.cfg["audio_file"] = fname
            self.cfg["audio_path"] = file_path
            self.cfg["audio_original"] = os.path.basename(file_path)

            self.lbl_audio.setText(f"已选择: {os.path.basename(file_path)}")
            self.lbl_audio.setStyleSheet("color: #67C23A; padding: 6px; background: #f0f9eb; border: 1px solid #ddd; border-radius: 4px;")
            self.btn_preview.setEnabled(True)
            _stop_audio_mci()
            self.btn_stop.setEnabled(False)
        except Exception as e:
            QMessageBox.warning(self, "保存音频失败", f"无法将音频保存到流程目录：\n{str(e)}")

    def _resolve_audio_path(self):
        audio_file = self.cfg.get("audio_file", "")
        audio_dir = self._get_audio_dir()
        if audio_file and audio_dir:
            p = os.path.join(audio_dir, audio_file)
            if os.path.exists(p):
                return p
        audio_path = self.cfg.get("audio_path", "")
        if audio_path and os.path.exists(audio_path):
            return audio_path
        return ""

    def _preview_audio(self):
        path = self._resolve_audio_path()
        if not path:
            QMessageBox.warning(self, "提示", "音频文件不存在")
            return
        ok, err = _play_audio_file_mci(path, volume=self.spin_volume.value(), loop=1, wait=False)
        if not ok:
            QMessageBox.warning(self, "试听失败", err)
            return
        self.btn_stop.setEnabled(True)

    def _stop_preview(self):
        _stop_audio_mci()
        self.btn_stop.setEnabled(False)

    def _select_color(self):
        color = QColorDialog.getColor(QColor(f"#{self._current_color}"), self)
        if color.isValid():
            self._current_color = color.name()
            self.btn_color.setStyleSheet(f"background-color: #{color.name()}; border: 1px solid #ddd; border-radius: 4px;")

    def _on_ok(self):
        cfg = {
            "task_name": self.edit_name.text() or "播放音频",
            "audio_file": self.cfg.get("audio_file", ""),
            "audio_path": self.cfg.get("audio_path", ""),
            "audio_original": self.cfg.get("audio_original", ""),
            "volume": self.spin_volume.value(),
            "loop": self.spin_loop.value(),
            "wait_finish": self.chk_wait.isChecked(),
            "remark": self.edit_remark.text(),
            "remark_color": self._current_color,
        }
        if not cfg["audio_file"] and not cfg["audio_path"]:
            QMessageBox.warning(self, "提示", "请先选择音频文件")
            return
        self.saved.emit(cfg)
        self.accept()


