        self.spin_threshold.setRange(1, 255)
        self.spin_threshold.setSuffix(" 像素")
        self.spin_threshold.setValue(self.cfg.get("threshold", 30))
        param_layout.addWidget(self.spin_threshold, 0, 1)

        param_layout.addWidget(QLabel("检测间隔:"), 0, 2)
        self.spin_interval = QSpinBox()
        self.spin_interval.setRange(100, 5000)
        self.spin_interval.setSuffix(" ms")
        self.spin_interval.setValue(self.cfg.get("interval", 500))
