        save_group = QGroupBox("保存结果")
        save_layout = QVBoxLayout(save_group)

        self.chk_save = QCheckBox("保存监测结果到变量")
        self.chk_save.setChecked(self.cfg.get("save_to_var", False))
        self.chk_save.toggled.connect(self._on_save_toggled)
        save_layout.addWidget(self.chk_save)

        var_layout = QHBoxLayout()
        var_layout.addWidget(QLabel("变量名:"))
        self.edit_var = QLineEdit(self.cfg.get("var_name", "监测结果"))
        self.edit_var.setEnabled(self.cfg.get("save_to_var", False))
        var_layout.addWidget(self.edit_var, 1)
        save_layout.addLayout(var_layout)
