        def _get_main_window():
            if hasattr(self, 'variables') and hasattr(self, 'current_flow_id'):
                return self
            parent = self.parent()
            while parent is not None:
                if hasattr(parent, 'variables') and hasattr(parent, 'current_flow_id'):
                    return parent
                parent = parent.parent() if hasattr(parent, 'parent') else None
            return None
        
        selected_var_name = None
        
        def _refresh_trees():
            nonlocal selected_var_name
            selected_var_name = None
            
            for tree in [tree_global, tree_flow]:
                tree.clear()
            
            main_win = _get_main_window()
            if not main_win or not hasattr(main_win, 'variables') or not main_win.variables:
                for tree in [tree_global, tree_flow]:
                    empty_item = QTreeWidgetItem(tree)
                    empty_item.setText(0, "无变量")
                    empty_item.setForeground(0, QColor("#C0C4CC"))
                _update_buttons()
                return
            
            global_count = 0
            flow_count = 0
            
            var_groups = {}
            
            for var_name, var_value in main_win.variables.items():
                if isinstance(var_value, dict):
                    data_type = var_value.get('data_type', '任意类型')
                    var_category = var_value.get('category', '全局变量')
                    display_value = str(var_value.get('value', var_value.get('initial_value', '')))
                else:
                    if isinstance(var_value, bool):
                        data_type = '布尔'
                    elif isinstance(var_value, int):
                        data_type = '整数'
                    elif isinstance(var_value, float):
                        data_type = '浮点数'
                    else:
                        data_type = '文本'
                    var_category = '全局变量'
                    display_value = str(var_value)
                
                base_name = var_name
                suffix = ''
                if '_识别度' in var_name:
                    base_name = var_name.replace('_识别度', '')
                    suffix = '识别度'
                elif '_坐标x' in var_name:
                    base_name = var_name.replace('_坐标x', '')
                    suffix = '坐标x'
                elif '_坐标y' in var_name:
                    base_name = var_name.replace('_坐标y', '')
                    suffix = '坐标y'
                
                if base_name not in var_groups:
                    var_groups[base_name] = {
                        'category': var_category,
                        'base_value': None,
                        'items': []
                    }
                
                if not suffix:
                    var_groups[base_name]['base_value'] = {
                        'name': var_name,
                        'value': var_value,
                        'data_type': data_type,
                        'display_value': display_value
                    }
                else:
                    var_groups[base_name]['items'].append({
                        'name': var_name,
                        'suffix': suffix,
                        'value': var_value,
                        'data_type': data_type,
                        'display_value': display_value
                    })
            
            for base_name, group in var_groups.items():
                var_category = group['category']
                base_info = group['base_value']
                extra_items = group['items']
                
                tree = tree_global if var_category == '全局变量' else tree_flow
                
                if base_info:
                    var_name = base_info['name']
                    data_type = base_info['data_type']
                    display_value = base_info['display_value']
                else:
                    var_name = base_name
                    data_type = '复合'
                    display_value = ''
                
                parent_item = QTreeWidgetItem(tree)
                parent_item.setText(0, f"  {var_name} ({data_type})")
                parent_item.setData(0, Qt.ItemDataRole.UserRole, var_name)
                parent_item.setData(0, Qt.ItemDataRole.UserRole + 1, display_value)
                parent_item.setExpanded(False)
                
                if extra_items:
                    for extra in extra_items:
                        child_item = QTreeWidgetItem(parent_item)
                        child_text = f"    {extra['suffix']}: {extra['display_value']}"
                        child_item.setText(0, child_text)
                        child_item.setData(0, Qt.ItemDataRole.UserRole, extra['name'])
                        child_item.setData(0, Qt.ItemDataRole.UserRole + 1, extra['display_value'])
                else:
                    child_item = QTreeWidgetItem(parent_item)
                    child_text = f"    值: {display_value}"
                    child_item.setText(0, child_text)
                    child_item.setData(0, Qt.ItemDataRole.UserRole, var_name)
                    child_item.setData(0, Qt.ItemDataRole.UserRole + 1, display_value)
                
                if var_category == '全局变量':
                    global_count += 1
                elif var_category == '流程变量':
                    flow_count += 1
            
            if global_count == 0:
                empty_item = QTreeWidgetItem(tree_global)
                empty_item.setText(0, "无变量")
                empty_item.setForeground(0, QColor("#C0C4CC"))
            
            if flow_count == 0:
                empty_item = QTreeWidgetItem(tree_flow)
                empty_item.setText(0, "无变量")
                empty_item.setForeground(0, QColor("#C0C4CC"))
            
            _update_buttons()
        
        def _update_buttons():
            nonlocal selected_var_name
            has_selection = selected_var_name is not None
            btn_ok.setEnabled(has_selection)
            btn_del_var.setEnabled(has_selection)
        
        def _on_tree_item_selected():
            nonlocal selected_var_name
            current_tree = tab_widget.currentWidget()
            if isinstance(current_tree, QTreeWidget):
                selected_items = current_tree.selectedItems()
                if selected_items:
                    item = selected_items[0]
                    var_name = item.data(0, Qt.ItemDataRole.UserRole)
                    if var_name:
                        selected_var_name = var_name
                        _update_buttons()
                        return
            
            selected_var_name = None
            _update_buttons()
        
        tree_global.itemSelectionChanged.connect(_on_tree_item_selected)
        tree_flow.itemSelectionChanged.connect(_on_tree_item_selected)
        
        # 设置右键菜单策略
        tree_global.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        tree_flow.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        
        def _show_context_menu(position):
            nonlocal selected_var_name
            menu = QMenu()
            
            # 获取当前树（通过信号发送者）
            sender_tree = dlg.sender()
            if not sender_tree:
                return
            
            # 获取点击的项
            item = sender_tree.itemAt(position)
            if item and item.data(0, Qt.ItemDataRole.UserRole):
                # 有变量项被点击，显示修改和删除选项
                var_name = item.data(0, Qt.ItemDataRole.UserRole)
                selected_var_name = var_name
                _update_buttons()
                
                action_edit = QAction("修改变量", dlg)
                action_edit.triggered.connect(lambda checked, vn=var_name: _show_add_var_dialog(vn))
                menu.addAction(action_edit)
                
                action_delete = QAction("删除变量", dlg)
                action_delete.triggered.connect(_delete_variables)
                menu.addAction(action_delete)
            else:
                # 点击空白区域，显示新增选项
                action_add = QAction("新增变量", dlg)
                action_add.triggered.connect(lambda: _show_add_var_dialog(None))
                menu.addAction(action_add)
            
            menu.exec(QCursor.pos())
        
        tree_global.customContextMenuRequested.connect(_show_context_menu)
        tree_flow.customContextMenuRequested.connect(_show_context_menu)
        
        def _filter_variables():
            keyword = search_input.text().strip()
            for tree in [tree_global, tree_flow]:
                for i in range(tree.topLevelItemCount()):
                    item = tree.topLevelItem(i)
                    var_name = item.data(0, Qt.ItemDataRole.UserRole)
                    if var_name:
                        if keyword:
                            item.setHidden(keyword.lower() not in var_name.lower())
                        else:
                            item.setHidden(False)
                    else:
                        # "无变量"提示项
                        item.setHidden(False)
        
        search_input.textChanged.connect(_filter_variables)
        
