        grad = QLinearGradient(0, 0, self.width(), self.height())
        grad.setColorAt(0.0, QColor(214, 238, 252))
        grad.setColorAt(0.45, QColor(226, 220, 252))
        grad.setColorAt(1.0, QColor(236, 228, 253))
