    def eventFilter(self, obj, event):
        if event.type() == QEvent.Type.Enter:
            expr = self._hover_map.get(id(obj))
            if expr and not self.home_eyes._expr_timer.isActive():
                self.home_eyes.set_expression(expr, 1200)
        return super().eventFilter(obj, event)

    def _position_home_eyes(self):
        """将浮动眼睛定位到工具栏中间空白区域（不影响布局）"""
        if not hasattr(self, 'home_eyes'):
            return
        cat_right = self.cat_drop_button.geometry().right()
        zone_left = self.btn_script_zone.geometry().left()
        mid_x = (cat_right + zone_left) // 2
        eyes_x = mid_x - self.home_eyes.width() // 2
        # 垂直方向：让眼睛在工具栏区域居中（工具栏约y=20, 高32px）
        eyes_y = 20 + (32 - 90) // 2  # = -9
        self.home_eyes.move(eyes_x, eyes_y)
        self.home_eyes.raise_()

    def _on_home_crosshair_toggled(self, state):
        """首页准心开关（同步到主窗口的 _toggle_crosshair）"""
        if not self.main_window:
            return
        # 同步主窗口的准心 checkbox 状态，避免两个控件不一致
        if hasattr(self.main_window, 'crosshair_checkbox') and self.main_window.crosshair_checkbox is not None:
            try:
                self.main_window.crosshair_checkbox.blockSignals(True)
                self.main_window.crosshair_checkbox.setCheckState(Qt.CheckState(state))
            finally:
                self.main_window.crosshair_checkbox.blockSignals(False)
        # 调用主窗口的准心切换
        if hasattr(self.main_window, '_toggle_crosshair'):
            self.main_window._toggle_crosshair(state)

    # ──────────────────── 数据 ────────────────────
    # flow_index.json 永远是纯 list（dict of flows），与项目其他模块 100% 兼容；
    # 分类信息存放在独立的 flow_categories.json（字符串数组）。

    def _read_categories(self):
        """读 flow_categories.json -> list[str]；不存在返回空列表"""
        cats = []
        try:
            if os.path.exists(self.categories_file):
                with open(self.categories_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                if isinstance(data, list):
                    cats = [str(x) for x in data if isinstance(x, str) and x.strip()]
        except Exception:
            cats = []
        return cats

    def _write_categories(self, cats):
        try:
            os.makedirs(os.path.dirname(self.categories_file), exist_ok=True)
            with open(self.categories_file, 'w', encoding='utf-8') as f:
                json.dump(cats, f, ensure_ascii=False, indent=2)
            return True
        except Exception:
            return False

    def _load_flow_index(self):
        """读 flow_index.json -> list[dict]"""
        flows = []
        try:
            if os.path.exists(self.flow_index_file):
                with open(self.flow_index_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                # 兼容：如果有人不小心又写成 dict，按 flows 读出来
                if isinstance(data, dict):
                    data = data.get("flows", [])
                if isinstance(data, list):
                    flows = [x for x in data if isinstance(x, dict) and 'id' in x]
        except Exception:
            flows = []
        return flows

    def _save_flow_index(self, flows):
        """把 flows 数组写回 flow_index.json（永远纯 list 格式）"""
        try:
            os.makedirs(os.path.dirname(self.flow_index_file), exist_ok=True)
            tmp = self.flow_index_file + ".tmp"
            with open(tmp, 'w', encoding='utf-8') as f:
                json.dump(flows, f, ensure_ascii=False, indent=2)
            os.replace(tmp, self.flow_index_file)
            return True
        except Exception:
            return False

    def _show_toast(self, text, duration=1000):
        """显示一个轻量浮动提示，duration 毫秒后自动消失"""
        if not hasattr(self, '_toast_label') or self._toast_label is None:
            self._toast_label = QLabel(self)
            self._toast_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            self._toast_label.setStyleSheet(f"""
                QLabel {{
                    background: rgba(0, 0, 0, 180);
                    color: white;
                    font-size: 13px;
                    font-weight: 600;
                    padding: 8px 24px;
                    border-radius: 8px;
                }}
            """)
            self._toast_label.hide()
        self._toast_label.setText(text)
        self._toast_label.adjustSize()
        # 居中显示（软件中心点）
        x = (self.width() - self._toast_label.width()) // 2
        y = (self.height() - self._toast_label.height()) // 2
        self._toast_label.move(x, y)
        self._toast_label.raise_()
        self._toast_label.show()
        # 定时关闭
        if hasattr(self, '_toast_timer') and self._toast_timer:
            self._toast_timer.stop()
        self._toast_timer = QTimer(self)
        self._toast_timer.setSingleShot(True)
        self._toast_timer.timeout.connect(self._toast_label.hide)
        self._toast_timer.start(duration)

    def refresh_flows(self):
        """重新加载项目列表 + 刷新分类下拉框"""
        self.flow_list.clear()
        flows = self._load_flow_index()
        raw_cats = self._read_categories()
        seen = set()
        unique_cats = []
        for c in raw_cats:
            if c not in seen:
                unique_cats.append(c); seen.add(c)
        self._categories = ["全部项目"] + unique_cats

        flows_sorted = sorted(
            flows,
            key=lambda x: x.get('updated_at', x.get('created_at', '')),
            reverse=True
        )

        for info in flows_sorted:
            item = QListWidgetItem()
            item.setData(Qt.ItemDataRole.UserRole, info)
            item.setSizeHint(QSize(0, 50))
            self.flow_list.addItem(item)

        self.stat_label.setText(f"共 {len(flows_sorted)} 个项目")
        self._refresh_category_bar()
        self._filter_flows(self.search_edit.text() if hasattr(self, 'search_edit') else "")
        self._apply_selection_state()
        # 空列表时显示中心提示
        self._update_empty_hint()

    def _update_empty_hint(self):
        """项目列表为空时在中心显示提示"""
        visible_count = sum(1 for i in range(self.flow_list.count()) if not self.flow_list.item(i).isHidden())
        if visible_count == 0:
            self.empty_hint_label.setGeometry(self.flow_list.rect())
            self.empty_hint_label.show()
        else:
            self.empty_hint_label.hide()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self, 'empty_hint_label') and self.empty_hint_label.isVisible():
            self.empty_hint_label.setGeometry(self.flow_list.rect())
        self._position_home_eyes()

    def _filter_flows(self, keyword):
        kw = (keyword or "").strip().lower()
        cur = self._current_category
        for i in range(self.flow_list.count()):
            item = self.flow_list.item(i)
            info = item.data(Qt.ItemDataRole.UserRole) or {}
            name = str(info.get('name', ''))
            desc = str(info.get('description', ''))
            cat = str(info.get('category', '') or '')
            hide_kw = kw != "" and (kw not in name.lower() and kw not in desc.lower())
            hide_cat = (cur != "__all__") and (cat != cur)
            item.setHidden(hide_kw or hide_cat)
        # 过滤后更新空提示
        self._update_empty_hint()

    def _apply_selection_state(self):
        """【delegate 模式】delegate 自己处理选中态，此方法留空兼容"""
        pass

    # ──────────────────── 分类管理（下拉框版本） ────────────────────
    @staticmethod
    def _truncate4(text):
        """按钮文字永远只显示前四个字（中文/英文/数字都按字符计 4 个）"""
        if text is None:
            return ""
        s = str(text)
        # 去掉空格和 ▾ 后再截断，避免用户分类名本身带这些符号干扰
        s = s.replace("▾", "").replace("▼", "").strip()
        return s[:4]

    def _current_category_label(self):
        if self._current_category == "__all__":
            return "全部项目"
        return self._current_category

    def _update_cat_drop_label(self):
        if hasattr(self, 'cat_drop_button') and self.cat_drop_button:
            # 永远只显示四个字（去掉 ▾ 图标）
            display = self._truncate4(self._current_category_label())
            self.cat_drop_button.setText(display)

    def _refresh_category_bar(self):
        """下拉框版本：仅刷新按钮文字（当前分类）"""
        self._update_cat_drop_label()

    def _on_category_clicked(self, cat_name, btn=None):
        """兼容旧回调"""
        if cat_name == "全部项目":
            self._current_category = "__all__"
        else:
            self._current_category = cat_name
        self._update_cat_drop_label()
        self._filter_flows(self.search_edit.text() if hasattr(self, 'search_edit') else "")

    def _build_category_menu(self):
        """生成下拉菜单（与图中风格一致：只显示分类列表 + 右侧数量 + 底部新建/删除）

        菜单结构：
          ✓ 全部项目                 83   ← 选中态：✓ 紫色加粗；右侧数字=该分类项目数
          ──────────────────────────────
            逆战手游                   5
            逆战端游                   3
            稳定数据                  12
            咸鱼                       1
            传奇脚本                  17
          ──────────────────────────────
          ＋  新建分类
          ✕  删除分类  ─┬─
                         ├─ 逆战手游
                         └─ 传奇脚本
        """
        menu = QMenu(self)
        flows = self._load_flow_index()
        cat_acts_map = {}   # action -> category_key (str)
        del_acts_map = {}   # action -> category_name (str)
        new_cat_act = None

        total_count = len(flows)
        user_cats = [c for c in self._categories if c != "全部项目"]

        def _count_in_cat(cat_key):
            if cat_key == "__all__":
                return total_count
            return len([f for f in flows if str(f.get('category', '') or '') == cat_key])

        def _add_cat_action(cat_key, label):
            """追加一行分类 action（左=标签，右=数量），并映射到 cat_acts_map"""
            count = _count_in_cat(cat_key)
            if cat_key == "__all__":
                is_selected = (self._current_category == "__all__")
            else:
                is_selected = (self._current_category == cat_key)
            prefix = "✓ " if is_selected else "　 "  # 中文全角空格对齐
            # 简单右对齐数量：标签和数量之间用多空格填充（Qt 对纯文本菜单不支持直接双列对齐）
            count_str = str(count)
            # 按中文宽度估算：固定 26 个英文字符宽度作为"标签区"，数字右对齐到 3 位 + 两空格边距
            label_display = f"{prefix}{label}"
            pad_len = max(1, 30 - HomePageWidget._visual_len(label_display))
            pad = " " * pad_len
            text = f"{label_display}{pad}{count_str}"
            act = menu.addAction(text)
            # 字体
            font = act.font()
            font.setBold(is_selected)
            if is_selected:
                font.setPointSize(font.pointSize() + 1 if font.pointSize() > 0 else 11)
            act.setFont(font)
            # 颜色
            if is_selected:
                try:
                    from PySide6.QtGui import QColor as _QC
                    act.setForeground(_QC(COLOR_PRIMARY))
                except Exception:
                    pass
            cat_acts_map[act] = cat_key
            return act

        # 1) 全部项目
        _add_cat_action("__all__", "全部项目")
        menu.addSeparator()

        # 2) 用户分类
        if not user_cats:
            empty = menu.addAction("    （暂无自定义分类）")
            empty.setEnabled(False)
        else:
            for cat in user_cats:
                _add_cat_action(cat, cat)

        menu.addSeparator()

        # 3) 底部：新建分类
        new_cat_act = menu.addAction("＋  新建分类")
        nf = new_cat_act.font()
        nf.setBold(False); new_cat_act.setFont(nf)

        # 4) 删除分类（仅当有用户分类时）
        if user_cats:
            del_sub = menu.addMenu("✕  删除分类")
            for cat in user_cats:
                a = del_sub.addAction(cat)
                del_acts_map[a] = cat

        flow_acts_map = {}  # 现在菜单里没有项目项，保持空 dict 兼容外层分发
        return menu, cat_acts_map, flow_acts_map, new_cat_act, del_acts_map

    @staticmethod
    def _visual_len(s):
        """估算字符串的显示宽度：中文/全角=2，其它=1。用于对齐数量列。"""
        w = 0
        for ch in s:
            code = ord(ch)
            if ch == "✓":
                w += 2
            elif (
                (0x1100 <= code <= 0x115F) or
                (0x2E80 <= code <= 0x303E) or
                (0x3041 <= code <= 0x33FF) or
                (0x3400 <= code <= 0x4DBF) or
                (0x4E00 <= code <= 0x9FFF) or
                (0xA000 <= code <= 0xA4CF) or
                (0xAC00 <= code <= 0xD7A3) or
                (0xF900 <= code <= 0xFAFF) or
                (0xFE30 <= code <= 0xFE4F) or
                (0xFF01 <= code <= 0xFF60) or
                (0xFFE0 <= code <= 0xFFE6)
            ):
                w += 2
            else:
                w += 1
        return w

    def _show_category_dropdown(self):
        """点击下拉按钮：弹出菜单并处理用户选择"""
        menu, cat_map, flow_map, new_cat_act, del_map = self._build_category_menu()
        chosen = menu.exec(self.cat_drop_button.mapToGlobal(QPoint(0, self.cat_drop_button.height())))
        if chosen is None:
            return
        # 1) 新建分类
        if chosen == new_cat_act:
            self._add_category_interactive()
            return
        # 2) 删除分类
        if chosen in del_map:
            self._delete_category(del_map[chosen])
            return
        # 3) 切换分类（过滤）
        if chosen in cat_map:
            self._current_category = cat_map[chosen]
            self._update_cat_drop_label()
            self._filter_flows(self.search_edit.text() if hasattr(self, 'search_edit') else "")
            return
        # 4) 直接打开项目
        if chosen in flow_map:
            f = flow_map[chosen]
            if not f or not f.get('id'):
                return
            encrypted = bool(f.get('encrypted', f.get('readonly', False)))
            if encrypted:
                QMessageBox.warning(self, "加密脚本", f"「{f.get('name','')}」是加密脚本，无法编辑。\n\n仅支持加载运行。")
                return
            self.flow_selected.emit(f['id'])

    def _add_category_interactive(self):
        name, ok = QInputDialog.getText(self, "新建分类", "请输入分类名称:")
        if not ok:
            return
        name = name.strip()
        if not name:
            return
        cats = self._read_categories()
        if name in cats or name == "全部项目":
            QMessageBox.information(self, "分类已存在", f"已存在同名分类「{name}」")
            return
        cats.append(name)
        if self._write_categories(cats):
            self._categories = ["全部项目"] + cats
            self._current_category = name
            self._refresh_category_bar()
            self._filter_flows(self.search_edit.text() if hasattr(self, 'search_edit') else "")

    def _delete_category(self, cat_name):
        if cat_name == "全部项目":
            return
        ans = QMessageBox.question(
            self, "删除分类",
            f"删除分类「{cat_name}」？\n\n该分类下的项目将自动保留，在「全部项目」中可见。"
        )
        if ans != QMessageBox.StandardButton.Yes:
            return
        cats = self._read_categories()
        if cat_name not in cats:
            return
        cats = [c for c in cats if c != cat_name]
        # 清空该分类下项目的 category 字段
        flows = self._load_flow_index()
        changed = False
        for x in flows:
            if isinstance(x, dict) and x.get('category') == cat_name:
                x['category'] = ""
                changed = True
        self._write_categories(cats)
        if changed:
            self._save_flow_index(flows)
        if self._current_category == cat_name:
            self._current_category = "__all__"
        self._categories = ["全部项目"] + cats
        self._refresh_category_bar()
        self.refresh_flows()

    def _move_flow_to_category(self, flow_info, cat_name):
        if not flow_info or not flow_info.get('id'):
            return
        flows = self._load_flow_index()
        # 如果目标分类不是空且不在现有分类里，自动新增
        if cat_name and cat_name not in [c for c in self._categories if c != "全部项目"]:
            cats = self._read_categories()
            if cat_name not in cats:
                cats.append(cat_name)
                self._write_categories(cats)
                self._categories = ["全部项目"] + cats
        changed = False
        for x in flows:
            if isinstance(x, dict) and x.get('id') == flow_info['id']:
                x['category'] = cat_name
                changed = True
                break
        if changed:
            self._save_flow_index(flows)
        # 【修复】保存滚动位置，刷新后恢复，避免列表跳回顶部
        scroll_pos = self.flow_list.verticalScrollBar().value()
        self._refresh_category_bar()
        self.refresh_flows()
        self.flow_list.verticalScrollBar().setValue(scroll_pos)
        # 显示"移动成功"提示，1秒后自动消失
        if changed:
            self._show_toast("移动成功")

    # ──────────────────── 事件 ────────────────────
    def _on_item_double_clicked(self, index):
        item = self.flow_list.itemFromIndex(index)
        if not item:
            return
        info = item.data(Qt.ItemDataRole.UserRole) or {}
        fid = info.get('id')
        if not fid:
            return
        # 加密脚本（encrypted 字段为 True 或 readonly 为 True）提示无法编辑
        encrypted = bool(info.get('encrypted', info.get('readonly', False)))
        if encrypted:
            QMessageBox.warning(self, "加密脚本", f"「{info.get('name','')}」是加密脚本，无法编辑。\n\n仅支持加载运行。")
            return
        self.flow_selected.emit(fid)

    def _show_context_menu(self, pos):
        item = self.flow_list.itemAt(pos)
        if not item:
            return
        self.flow_list.setCurrentItem(item)
        info = item.data(Qt.ItemDataRole.UserRole) or {}

        menu = QMenu(self)
        act_open = menu.addAction("打开并进入编辑")
        act_rename = menu.addAction("重命名")
        act_desc = menu.addAction("编辑简介")
        act_delete = menu.addAction("彻底删除")
        menu.addSeparator()
        act_settings = menu.addAction("设置")
        act_export = menu.addAction("导出项目")
        menu.addSeparator()
        act_run_hk = menu.addAction("启动快捷键")
        act_stop_hk = menu.addAction("停止快捷键")
        act_del_hk = menu.addAction("删除快捷键")
        # 禁用/启用快捷键（保留配置，仅切换生效状态）
        cur_info = self._get_flow_info(info.get('id')) or info
        _saved_hk = cur_info.get('_disabled_hotkeys') or {}
        _hk_disabled = (not cur_info.get('run_hotkey') and not cur_info.get('stop_hotkey')) and bool(_saved_hk)
        act_toggle_hk = menu.addAction("启用快捷键" if _hk_disabled else "禁用快捷键")
        menu.addSeparator()

        # ─── 「移动到分类」子菜单 ───
        move_menu = QMenu("移动到分类", self)
        act_clear_cat = move_menu.addAction("取消分类（不归类）")
        move_menu.addSeparator()
        user_cats = [c for c in self._categories if c != "全部项目"]
        cat_actions = {}
        for c in user_cats:
            a = move_menu.addAction(c)
            cat_actions[a] = c
        move_menu.addSeparator()
        act_new_cat = move_menu.addAction("＋  新建分类并移动…")
        menu.addMenu(move_menu)

        menu.addSeparator()
        act_copy = menu.addAction("拷贝项目")
        act_run_count = menu.addAction("设置运行次数")

        chosen = menu.exec(self.flow_list.mapToGlobal(pos))
        if chosen == act_open:
            if info.get('id'):
                encrypted = bool(info.get('encrypted', info.get('readonly', False)))
                if encrypted:
                    QMessageBox.warning(self, "加密脚本", f"「{info.get('name','')}」是加密脚本，无法编辑。\n\n仅支持加载运行。")
                    return
                self.flow_selected.emit(info['id'])
        elif chosen == act_rename:
            self._rename_flow(info)
        elif chosen == act_desc:
            self._edit_description(info)
        elif chosen == act_delete:
            self._delete_flow(info)
        elif chosen == act_settings:
            self._menu_edit_settings(info)
        elif chosen == act_export:
            self._menu_export_flow(info)
        elif chosen == act_run_hk:
            self._menu_set_flow_hotkey(info, 'run')
        elif chosen == act_stop_hk:
            self._menu_set_flow_hotkey(info, 'stop')
        elif chosen == act_del_hk:
            self._menu_delete_flow_hotkeys(info)
        elif chosen == act_toggle_hk:
            self._menu_toggle_flow_hotkeys(info)
        elif chosen == act_copy:
            self._menu_copy_flow(info)
        elif chosen == act_run_count:
            self._menu_set_run_count(info)
        elif chosen == act_clear_cat:
            self._move_flow_to_category(info, "")
        elif chosen in cat_actions:
            self._move_flow_to_category(info, cat_actions[chosen])
        elif chosen == act_new_cat:
            name, ok = QInputDialog.getText(self, "新建分类并移动", "请输入新分类名称:")
            if ok and name.strip():
                self._move_flow_to_category(info, name.strip())

    def _show_item_menu(self, info, item_rect):
        """行内三点菜单：内容与右键菜单一致，弹出位置在三点按钮下方"""
        menu = QMenu(self)
        act_open = menu.addAction("打开并进入编辑")
        act_rename = menu.addAction("重命名")
        act_desc = menu.addAction("编辑简介")
        act_delete = menu.addAction("彻底删除")
        menu.addSeparator()
        act_settings = menu.addAction("设置")
        act_export = menu.addAction("导出项目")
        menu.addSeparator()
        act_run_hk = menu.addAction("启动快捷键")
        act_stop_hk = menu.addAction("停止快捷键")
