    def _make_card(self, title, accent, head_widget=None):
        card = QFrame()
        card.setStyleSheet(f"""
            QFrame {{
                background-color: {accent};
                border: 1px solid {COLOR_BORDER};
                border-radius: 12px;
            }}
        """)
        v = QVBoxLayout(card)
        v.setContentsMargins(16, 13, 16, 16)
        v.setSpacing(10)

        head = QHBoxLayout()
        head.setSpacing(6)
        lbl = QLabel(title)
        lbl.setStyleSheet("font-size: 13px; font-weight: 700; color: #1D2129; background: transparent; border: none;")
        head.addWidget(lbl)
        head.addStretch(1)
        if head_widget is not None:
            head.addWidget(head_widget)
        v.addLayout(head)

        content = QVBoxLayout()
        content.setSpacing(10)
        v.addLayout(content)
        return card, content

    def _copy_brackets(self):
        QApplication.clipboard().setText("【】")
        self.lbl_status.setText("已复制【】到剪贴板，粘贴后在括号内填入要监测的文字")
        self.lbl_status.setStyleSheet("color: #059669; font-size: 12px; background: transparent; border: none;")

