    def _delete_rule_row(self):
        row = self.table_rules.currentRow()
        if row < 0:
            QMessageBox.information(self, "提示", "请先选中要删除的规则行")
            return
        self.table_rules.removeRow(row)

    def _collect_rules(self):
        rules = []
        for row in range(self.table_rules.rowCount()):
            te = self.table_rules.cellWidget(row, 0)
            mc = self.table_rules.cellWidget(row, 1)
            ac = self.table_rules.cellWidget(row, 2)
            ke = self.table_rules.cellWidget(row, 3)
            he = self.table_rules.cellWidget(row, 4)
            action = ac.currentText() if ac else "左键点击"
            hold = 0.5
            if he:
                try:
                    hold = float(he.text().strip() or "0.5")
                except ValueError:
                    hold = 0.5
            rules.append(RuleItem(
                target_text=(te.text() if te else "").strip(),
                match_mode=(mc.currentText() if mc else "包含该文字"),
                action_type=action,
                key_name=(ke.text() if ke else "").strip(),
                hold_time=hold,
            ))
        return rules

    def _remove_empty_rows(self):
        for row in range(self.table_rules.rowCount() - 1, -1, -1):
            te = self.table_rules.cellWidget(row, 0)
            if not te or not te.text().strip():
                self.table_rules.removeRow(row)

    def _fmt_num(self, v):
        if isinstance(v, float) and v.is_integer():
            return str(int(v))
        return str(v)

    def _apply_config(self, cfg):
        self._remove_empty_rows()
        for r in cfg.rules:
            self._add_rule_row(r)
        self.edit_interval.setText(self._fmt_num(cfg.interval))
        self.edit_cooldown.setText(self._fmt_num(cfg.cooldown))
        self._set_combo(self.combo_loop, cfg.loop_mode)
        if cfg.region is not None:
            self.region = cfg.region
            self._update_region_label()

    def _set_combo(self, combo, text):
        i = combo.findText(text)
        if i >= 0:
            combo.setCurrentIndex(i)

    def _parse_clicked(self):
        rule = self.edit_rule.toPlainText().strip()
        if not rule:
            QMessageBox.warning(self, "提示", "请先输入自然语言规则")
            return
        cfg, err = parse_natural_language(rule)
        if err:
            self.lbl_status.setText("解析失败：" + err)
            self.lbl_status.setStyleSheet("color: #DC2626; font-size: 12px;")
        else:
            self._apply_config(cfg)
            self.lbl_status.setText("已追加 %d 条规则，当前共 %d 条，可修改下方列表后点“生成脚本”" % (len(cfg.rules), self.table_rules.rowCount()))
            self.lbl_status.setStyleSheet("color: #059669; font-size: 12px;")

    def _update_region_label(self):
        if self.region:
            self.lbl_region.setText("(%d,%d) - (%d,%d)" % tuple(self.region))
            self.btn_region.setText("修改框选区域")
        else:
            self.lbl_region.setText("全屏")
            self.btn_region.setText("框选区域")

    def _select_region(self):
        overlay = _RegionSelectOverlay(self)
        overlay.exec()
        if overlay.selected_rect is not None:
            r = overlay.selected_rect
            self.region = (r.x(), r.y(), r.x() + r.width(), r.y() + r.height())
            self._update_region_label()
        overlay.deleteLater()

    def _clear_region(self):
        self.region = None
        self._update_region_label()

    def _preview_ocr(self):
        import requests
        import base64
        import io
        from PIL import ImageGrab
        options_url = "http://127.0.0.1:1224/api/ocr/get_options"
        ocr_url = "http://127.0.0.1:1224/api/ocr"
        try:
            r = requests.get(options_url, timeout=3)
            if r.status_code != 200:
                raise RuntimeError("未连接")
        except Exception:
            QMessageBox.warning(self, "提示", "未连接 Umi-OCR，请先打开 Umi-OCR 并开启 HTTP 服务")
            return
        try:
            img = ImageGrab.grab(bbox=self.region) if self.region else ImageGrab.grab()
            buf = io.BytesIO()
            img.save(buf, format="PNG")
            b64 = base64.b64encode(buf.getvalue()).decode("utf-8")
            resp = requests.post(
                ocr_url,
                json={"base64": b64, "options": {"data.format": "dict"}},
                timeout=15,
                proxies={"http": None, "https": None},
            )
            resp.raise_for_status()
            res = resp.json()
            items = res.get("data") if (res.get("code") == 100 and isinstance(res.get("data"), list)) else []
        except Exception as exc:
            QMessageBox.warning(self, "错误", "OCR 识别失败：%s" % exc)
            return
        texts = [(it.get("text") or "").strip() for it in items if (it.get("text") or "").strip()]
        if not texts:
            QMessageBox.information(self, "提示", "未识别到文字")
            return
        sel, ok = QInputDialog.getItem(self, "OCR 识别结果", "选择要监测的文字（回填到当前选中行）:", texts, 0, False)
        if ok and sel:
            row = self.table_rules.currentRow()
            if row < 0:
                self._add_rule_row()
                row = self.table_rules.rowCount() - 1
            target_edit = self.table_rules.cellWidget(row, 0)
            if target_edit is not None:
                target_edit.setText(sel)
            self.table_rules.setCurrentCell(row, 0)

    def _test_ocr(self):
        import requests, base64, io
        from PIL import ImageGrab
        options_url = "http://127.0.0.1:1224/api/ocr/get_options"
        ocr_url = "http://127.0.0.1:1224/api/ocr"
        try:
            r = requests.get(options_url, timeout=3)
            if r.status_code != 200:
                raise RuntimeError("服务未就绪")
        except Exception:
            QMessageBox.warning(self, "测试识别", "未连接 Umi-OCR，请先开启 OCR 软件并启动 HTTP 服务")
            return
        try:
            img = ImageGrab.grab(bbox=self.region) if self.region else ImageGrab.grab()
            if img.mode != "RGB":
                img = img.convert("RGB")
            buf = io.BytesIO()
            img.save(buf, format="JPEG", quality=80)
            b64 = base64.b64encode(buf.getvalue()).decode("utf-8")
            resp = requests.post(
                ocr_url,
                json={"base64": b64, "options": {"data.format": "dict"}},
                timeout=15,
                proxies={"http": None, "https": None},
            )
            resp.raise_for_status()
            res = resp.json()
            items = res.get("data") if (res.get("code") == 100 and isinstance(res.get("data"), list)) else []
        except Exception as exc:
            QMessageBox.warning(self, "测试识别", "OCR 识别失败：%s" % exc)
            return
        texts = [(it.get("text") or "").strip() for it in items if (it.get("text") or "").strip()]
        if not texts:
            QMessageBox.information(self, "测试识别", "识别成功，但未识别到任何文字")
        else:
            QMessageBox.information(self, "测试识别", "识别成功，共 %d 条文字：\n%s" % (len(texts), "\n".join(texts)))

    def _confirm(self):
        rule = self.edit_rule.toPlainText().strip()
        # 若用户只填了自然语言但列表为空，先自动解析一次
        if rule and self.table_rules.rowCount() == 0:
            cfg, err = parse_natural_language(rule)
            if err:
                QMessageBox.warning(self, "解析错误", err)
                return
            self._apply_config(cfg)

        rules = [r for r in self._collect_rules() if r.target_text]
        if not rules:
            QMessageBox.warning(self, "参数错误", "请至少填写一条“目标文字”规则")
            return
        try:
            interval = float(self.edit_interval.text().strip() or "1")
            cooldown = float(self.edit_cooldown.text().strip() or "0")
        except ValueError:
            QMessageBox.warning(self, "参数错误", "轮询间隔/冷却时间必须是数字")
            return

        cfg = RuleConfig(
            rules=rules,
            interval=interval,
            cooldown=cooldown,
            loop_mode=self.combo_loop.currentText(),
            region=self.region,
        )
        code = render_python_code(cfg)
        self.saved.emit({
            "task_name": self.edit_taskname.text().strip() or "文字生脚本",
            "code": code,
            "return_type": "stdout",
            "save_to_variable": "",
        })
        self.accept()


