    @Slot()
    def toggle_key_recording(self):
        """切换录制状态 (F4) - 根据设置支持键盘和/或鼠标录制"""
        if not self._enable_key_recording and not self._enable_mouse_recording and not self._enable_full_recording:
            if self.log_window:
                self.log_window.add_log("录制功能已禁用，请在设置中开启", "WARNING")
            return
        
        was_recording = self.recording_keys or self.recording_mouse
        
        if was_recording:
            self.recording_keys = False
            self.recording_mouse = False
            
            with self.key_event_lock:
                for key_name in list(self.pressed_keys.keys()):
                    press_info = self.pressed_keys.pop(key_name)
                    press_time = press_info['time']
                    press_task = press_info.get('task')
                    
                    release_time = time.perf_counter()
                    self._last_key_event_time = release_time
                    hold_duration = int((release_time - press_time) * 1000)
                    
                    if press_task:
                        QMetaObject.invokeMethod(self, "_update_task_delay",
                                                Qt.ConnectionType.QueuedConnection,
                                                Q_ARG(QTreeWidgetItem, press_task),
                                                Q_ARG(int, hold_duration))
                    
                    QMetaObject.invokeMethod(self, "_insert_key_task",
                                            Qt.ConnectionType.QueuedConnection,
                                            Q_ARG(str, key_name),
                                            Q_ARG(str, "release"),
                                            Q_ARG(int, 0),
                                            Q_ARG(int, 0))
                self.pressed_keys.clear()
            
            key_count = len(self._key_records)
            mouse_count = len(self._mouse_records)
            
            if self.log_window:
                log_msg = "录制已关闭"
                if key_count > 0:
                    log_msg += f"，键盘事件: {key_count}个"
                if mouse_count > 0:
                    log_msg += f"，鼠标事件: {mouse_count}个"
                self.log_window.add_log(log_msg, "INFO")
            
            # 停止批量定时器，立即刷新待处理的移动任务
            if self._move_batch_timer is not None and self._move_batch_timer.isActive():
                self._move_batch_timer.stop()
            self._flush_move_batch()
            
            if self._enable_key_recording:
                self._validate_key_records()
        else:
            # 完整录制模式：同时开启键盘+鼠标+鼠标移动
            if self._enable_full_recording:
                self.recording_keys = True
                self.recording_mouse = True
            else:
                self.recording_keys = self._enable_key_recording
                self.recording_mouse = self._enable_mouse_recording
            
            with self.key_event_lock:
                self.pressed_keys.clear()
                self._key_records = []
                self._mouse_records = []
                self._last_key_event_time = None
                self._last_mouse_move_time = None
                self._recording_start_time = time.perf_counter()
                self._pending_tasks = []
            
            if self.log_window:
                log_msg = "录制已开启"
                if self._enable_full_recording:
                    log_msg += "（完整录制：键盘+鼠标点击+鼠标移动）"
                elif self.recording_keys and self.recording_mouse:
                    log_msg += "（键盘+鼠标点击）"
                elif self.recording_keys:
                    log_msg += "（仅键盘）"
                elif self.recording_mouse:
                    log_msg += "（仅鼠标点击）"
                log_msg += " - 按F4关闭"
                self.log_window.add_log(log_msg, "INFO")
    
    def _validate_key_records(self):
        """验证录制数据的完整性和准确性"""
        if not self._key_records:
            return
        
        errors = []
        warnings = []
        
        # 检查每个事件的完整性
        for i, record in enumerate(self._key_records):
            # 检查必需字段
            required_fields = ['type', 'key', 'timestamp', 'delay_ms']
            for field in required_fields:
                if field not in record:
                    errors.append(f"事件 {i}: 缺少必需字段 '{field}'")
            
            # 检查事件类型
            if record.get('type') not in ['keydown', 'keyup']:
                errors.append(f"事件 {i}: 无效的事件类型 '{record.get('type')}'")
            
            # 检查按键名称
            if not record.get('key'):
                errors.append(f"事件 {i}: 按键名称为空")
            
            # 检查时间戳
            if record.get('timestamp') is None or record.get('timestamp') < 0:
                errors.append(f"事件 {i}: 无效的时间戳")
            
            # 检查延迟时间
            if record.get('delay_ms') is None or record.get('delay_ms') < 0:
                warnings.append(f"事件 {i}: 延迟时间异常 ({record.get('delay_ms')})")
        
        # 检查按键事件配对（keydown应该有对应的keyup）
        pressed_keys = {}
        for i, record in enumerate(self._key_records):
            if record['type'] == 'keydown':
                if record['key'] in pressed_keys:
                    warnings.append(f"事件 {i}: 按键 '{record['key']}' 重复按下，上次按下在事件 {pressed_keys[record['key']]}")
                pressed_keys[record['key']] = i
            elif record['type'] == 'keyup':
                if record['key'] not in pressed_keys:
                    warnings.append(f"事件 {i}: 按键 '{record['key']}' 抬起但未记录按下")
                else:
                    del pressed_keys[record['key']]
        
        # 检查是否有未抬起的按键
        if pressed_keys:
            for key, event_idx in pressed_keys.items():
                warnings.append(f"按键 '{key}' 在事件 {event_idx} 按下后未抬起")
        
        # 输出验证结果
        if self.log_window:
            if errors:
                self.log_window.add_log(f"录制数据验证发现 {len(errors)} 个错误", "ERROR")
                for error in errors:
                    self.log_window.add_log(f"  - {error}", "ERROR")
            if warnings:
                self.log_window.add_log(f"录制数据验证发现 {len(warnings)} 个警告", "WARNING")
                for warning in warnings[:5]:  # 最多显示5个警告
                    self.log_window.add_log(f"  - {warning}", "WARNING")
            if not errors and not warnings:
                self.log_window.add_log("录制数据验证通过，数据完整准确", "INFO")

    @Slot()
    def record_action(self):
        """F5 记录相对坐标，从录制器移植"""
        # 核心逻辑：第一次按 F5 一定记录相对初始位置的偏移
        QMetaObject.invokeMethod(self, "_record_action_threadsafe", 
                                 Qt.ConnectionType.QueuedConnection)

    @Slot()
    def record_color(self):
        """F7 记录当前鼠标位置的颜色"""
        pos = QCursor.pos()
        screen = QApplication.primaryScreen()
        if screen:
            pixmap = screen.grabWindow(0, pos.x(), pos.y(), 1, 1)
            img = pixmap.toImage()
            if img.valid(0, 0):
                color = img.pixelColor(0, 0)
                color_hex = color.name()
                if self.log_window:
                    self.log_window.add_log(f"F7按下：当前颜色 {color_hex} 在位置 ({pos.x()}, {pos.y()})", "INFO")
                # 插入颜色任务
                self._insert_record_to_tree("color", {
                    "color": color_hex,
                    "x": pos.x(),
                    "y": pos.y(),
                    "content": f"颜色 {color_hex} 在 ({pos.x()}, {pos.y()})"
                })

    @Slot()
    def _record_action_threadsafe(self):
        """F5 记录相对坐标 - 基于方向键移动的虚拟坐标（仅记录方向键移动量）"""
        now = datetime.now().strftime("%H:%M:%S.%f")[:-3]
        
        # 计算相对上一次记录的偏移（只包含方向键移动量，不含物理鼠标移动）
        dx = self.virtual_x - self.last_recorded_virtual[0]
        dy = self.virtual_y - self.last_recorded_virtual[1]
        
        # 保存记录的偏移，用于F6回正
        self.recorded_offset = (dx, dy)
        
        # 更新上一次记录时的虚拟坐标
        self.last_recorded_virtual = (self.virtual_x, self.virtual_y)
        
        # 格式化显示坐标
        content = f"相对坐标  X:{dx} Y:{dy}"
        
        if self.log_window: 
            self.log_window.add_log(f"F5按下：已记录坐标: {content} | 虚拟坐标 ({self.virtual_x},{self.virtual_y})", "INFO")
        
        # 插入鼠标任务，使用相对坐标
        self._insert_record_to_tree("mouse", {
            "dx": dx, "dy": dy, "content": content
        })
    


    @Slot()
    def reset_position(self):
        """F6: 回正坐标，回到原点坐标，使用虚拟坐标来回正"""
        if not self.origin_set or self.origin_pos is None:
            if self.log_window:
                self.log_window.add_log("F6按下：原点坐标未设置，无法回正", "WARNING")
            return
            
        # 用虚拟坐标计算回正的移动量
        dx = -self.virtual_x
        dy = -self.virtual_y
        
        # 执行移动
        try:
            mouse.relative_move(dx, dy)
            
            # 重置虚拟坐标和last_recorded_virtual为0
            self.virtual_x = 0
            self.virtual_y = 0
            self.last_recorded_virtual = (0, 0)
            
            # 回正后，把当前位置设置为新的原点
            new_pos = QCursor.pos()
            self.origin_pos = (new_pos.x(), new_pos.y())
            
            # 记录到编辑区
            content = f"相对坐标  X:{dx} Y:{dy}"
            self._insert_record_to_tree("mouse", {
                "dx": dx, "dy": dy, "content": content
            })
            
            if self.log_window:
                self.log_window.add_log(f"F6按下：已回正到原点 ({self.origin_pos[0]}, {self.origin_pos[1]})，新原点已设置", "INFO")
        except Exception as e:
            if self.log_window:
                self.log_window.add_log(f"回正失败: {str(e)}", "ERROR")

    def get_readable_key(self, key):
        """转换按键为可读名称，从录制器移植"""
        try:
            if hasattr(key, 'char') and key.char is not None:
                return key.char.upper()
            special = {
                Key.space: "Space", Key.enter: "Enter",
                Key.backspace: "Backspace", Key.tab: "Tab",
                Key.esc: "Esc", Key.shift: "Shift",
                Key.shift_l: "Shift", Key.shift_r: "Shift",
                Key.ctrl: "Ctrl", Key.ctrl_l: "Ctrl", Key.ctrl_r: "Ctrl",
                Key.alt: "Alt", Key.alt_l: "Alt", Key.alt_r: "Alt",
                Key.cmd: "Win", Key.cmd_l: "Win", Key.cmd_r: "Win",
                Key.delete: "Delete", Key.insert: "Insert"
            }
            if key in special: return special[key]
            key_str = str(key).replace("Key.", "")
            # 处理左右修饰键，统一为不带后缀的名称
            if key_str.lower() in ('ctrl_l', 'ctrl_r'):
                return "Ctrl"
            if key_str.lower() in ('shift_l', 'shift_r'):
                return "Shift"
            if key_str.lower() in ('alt_l', 'alt_r'):
                return "Alt"
            if key_str.lower() in ('cmd_l', 'cmd_r'):
                return "Win"
            return key_str.capitalize()
        except:
            return str(key)

    # 【修复2】确保 adjust_speed 方法存在且参数正确
    @Slot(int)
    def adjust_speed(self, delta_percent):
        """【修改】调整鼠标移动速度（按百分比）"""
        new_percent = self.speed_percent + delta_percent
        # 限制范围：1% - 500%
        new_percent = max(1, min(500, new_percent))
        
        if new_percent != self.speed_percent:
            self.speed_percent = new_percent
            # 【修改】同时更新日志窗口的速度标签（显示百分比）
            if self.log_window:
                self.log_window.update_speed(self.speed_percent)
                self.log_window.add_log(f"鼠标移动速度已调整为: {self.speed_percent}%", "INFO")

    @Slot(int)
    def _insert_delay_task(self, delay_ms):
        """插入固定等待任务（用于录制时显示动作之间的间隔）"""
        tree = self._get_current_tree()
        if not tree or delay_ms <= 0:
            return
        
        display_name = f"⏱️ 等待 {delay_ms}ms"
        color = QColor(107, 114, 128)  # 灰色
        bg_color = QColor(250, 250, 250)  # 浅灰背景
        
        item = QTreeWidgetItem()
        cfg = {
            "type": "fixed",
            "value": delay_ms,
        }
        item.setData(0, Qt.ItemDataRole.UserRole, {"type": "delay", "config": cfg})
        item.setText(0, display_name)
        item.setForeground(0, QBrush(color))
        item.setBackground(0, bg_color)
        
        tree.addTopLevelItem(item)
        self.update_task_numbers()
        self.mark_dirty()
        
        if self.log_window:
            self.log_window.add_log(f"已录制: {display_name}", "INFO")
    
    @Slot(str, str, int, int)
    def _insert_key_task(self, key_name, action, duration=0, delay_ms=0):
        """插入按键任务（按下/抬起/点击）"""
        tree = self._get_current_tree()
        if not tree: return

        # 【合并优化】如果是抬起动作，检查最后一个任务是否是同一按键的按下
        # 如果是，说明中间没有其他操作，合并为一行点击任务
        if action == "release":
            last_idx = tree.topLevelItemCount() - 1
            if last_idx >= 0:
                last_item = tree.topLevelItem(last_idx)
                last_data = last_item.data(0, Qt.ItemDataRole.UserRole)
                if isinstance(last_data, dict):
                    last_cfg = last_data.get('config', {})
                    if (last_cfg.get('key') == key_name and
                            last_cfg.get('action') == 'press'):
                        # 合并：从按下任务中提取延迟，duration直接使用传入的hold_duration
                        press_delay_ms = last_cfg.get('delay_ms', 0)
                        # 删除按下任务
                        tree.takeTopLevelItem(last_idx)
                        self.update_task_numbers()
                        # 改为插入click任务
                        action = "click"
                        # duration已经是hold_duration，无需再从last_cfg读取
                        delay_ms = press_delay_ms

        # 确定显示文本和颜色
        if action == "press":
            # 按下事件：初始不显示时间，抬起时更新为按住时间
            display_name = f"⌨️ 按下 {key_name}"
            color = QColor(34, 197, 94)  # 绿色
            bg_color = QColor(240, 255, 240)
        elif action == "release":
            # 抬起事件不显示任何时间信息
            display_name = f"⌨️ 抬起 {key_name}"
            color = QColor(239, 68, 68)  # 红色
            bg_color = QColor(255, 240, 240)
        else:  # click
            delay_text = f" +{delay_ms}ms" if delay_ms > 0 else ""
            display_name = f"⌨️ 点击 {key_name}"
            if duration > 0:
                display_name += f" (点击{duration}毫秒抬起)"
            display_name += delay_text
            color = QColor(139, 92, 246)  # 紫色
            bg_color = QColor(252, 245, 255)
        
        item = QTreeWidgetItem()
        cfg = {
            "key": key_name,
            "action": action,
            "duration": duration,
            "delay_ms": delay_ms  # 【新增】保存延迟时间
        }
        item.setData(0, Qt.ItemDataRole.UserRole, {"type": "key", "config": cfg})
        item.setText(0, display_name)
        item.setForeground(0, QBrush(color))
        item.setBackground(0, bg_color)
        
        tree.addTopLevelItem(item)
        self.update_task_numbers()
        self.mark_dirty()
        
        # 【关键修改】如果是按下事件，更新pressed_keys中的任务引用
        if action == "press":
            with self.key_event_lock:
                if key_name in self.pressed_keys:
                    self.pressed_keys[key_name]['task'] = item
        
        if self.log_window:
            self.log_window.add_log(f"已录制: {display_name}", "INFO")
    
    @Slot(int, int, str, int)
    def _insert_mouse_task(self, x, y, button, delay_ms=0):
        """插入鼠标录制任务（仅记录终点坐标，默认录制为点击操作）"""
        tree = self._get_current_tree()
        if not tree:
            return
        
        action_type_map = {
            "left": "left_click",
            "right": "right_click",
            "middle": "middle_click"
        }
        action_type = action_type_map.get(button, "left_click")
        
        display_name = f"🖱️ {button}键点击 ({x}, {y})"
        if delay_ms > 0:
            display_name += f" +{delay_ms}ms"
        color = QColor(59, 130, 246)  # 蓝色
        bg_color = QColor(239, 246, 255)
        
        item = QTreeWidgetItem()
        cfg = {
            "action_type": action_type,
            "duration": 0.05,
            "interval": 50,
            "move_type": "absolute",
            "scroll_delta": 120,
            "task_name": "鼠标操作",
            "x": x,
            "y": y,
            "delay_ms": delay_ms
        }
        item.setData(0, Qt.ItemDataRole.UserRole, {"type": "mouse_action", "config": cfg})
        item.setText(0, display_name)
        item.setForeground(0, QBrush(color))
        item.setBackground(0, bg_color)
        
        tree.addTopLevelItem(item)
        self.update_task_numbers()
        self.mark_dirty()
        
        mouse_record = {
            'type': 'mouse_click',
            'button': button,
            'x': x,
            'y': y,
            'timestamp': time.perf_counter(),
            'delay_ms': delay_ms,
            'absolute_time_ms': int((time.perf_counter() - self._recording_start_time) * 1000) if self._recording_start_time else 0
        }
        self._mouse_records.append(mouse_record)
        
        if self.log_window:
            self.log_window.add_log(f"已录制: {display_name}", "INFO")
    
    @Slot(int, int, int)
    def _insert_mouse_move_task(self, x, y, delay_ms=0):
        """插入鼠标移动任务（完整录制模式）- 优化版：批量更新UI"""
        tree = self._get_current_tree()
        if not tree:
            return
        
        delay_text = f" +{delay_ms}ms" if delay_ms > 0 else ""
        display_name = f"🖱️ 鼠标移动到 ({x}, {y}){delay_text}"
        
        item = QTreeWidgetItem()
        cfg = {
            "action_type": "none",
            "move_type": "absolute",
            "x": x,
            "y": y,
            "duration": 0,
            "interval": 50,
            "scroll_delta": 0,
            "task_name": f"鼠标移动到({x},{y})",
            "delay_ms": delay_ms
        }
        item.setData(0, Qt.ItemDataRole.UserRole, {"type": "mouse_action", "config": cfg})
        item.setText(0, display_name)
        item.setForeground(0, QBrush(QColor(168, 85, 247)))
        item.setBackground(0, QColor(252, 245, 255))
        
        # 批量添加：禁用UI更新，直接添加item（不每次滚动，由批量更新统一滚动）
        tree.setUpdatesEnabled(False)
        tree.addTopLevelItem(item)
        tree.setUpdatesEnabled(True)
        
        # 批量延迟更新任务编号和脏标记（避免每次移动都遍历整个树）
        self._pending_move_count += 1
        if self._move_batch_timer is None:
            from PySide6.QtCore import QTimer
            self._move_batch_timer = QTimer(self)
            self._move_batch_timer.setSingleShot(True)
            self._move_batch_timer.timeout.connect(self._flush_move_batch)
        if not self._move_batch_timer.isActive():
            self._move_batch_timer.start(500)  # 500ms后批量更新
    
    def _flush_move_batch(self):
        """批量刷新鼠标移动录制的UI更新"""
        if self._pending_move_count > 0:
            self.update_task_numbers()
            self.mark_dirty()
            tree = self._get_current_tree()
            if tree and tree.topLevelItemCount() > 0:
                tree.scrollToItem(tree.topLevelItem(tree.topLevelItemCount() - 1))
            if self.log_window:
                self.log_window.add_log(f"已录制 {self._pending_move_count} 个鼠标移动步骤", "INFO")
            self._pending_move_count = 0
    
    @Slot(QTreeWidgetItem, int)
    def _update_task_delay(self, item, hold_duration):
        """更新任务项的按住时间显示"""
        if not item:
            return
        
        # 获取当前配置
        data = item.data(0, Qt.ItemDataRole.UserRole)
        if not isinstance(data, dict):
            return
        
        cfg = data.get('config', {})
        key_name = cfg.get('key', '')
        action = cfg.get('action', '')
        
        # 保存按住时间，但不要覆盖间隔延迟(delay_ms)
        cfg['duration'] = hold_duration
        
        # 更新显示文本（按下事件同时显示按住时间和间隔延迟）
        if action == "press":
            delay_text = f" +{cfg.get('delay_ms', 0)}ms" if cfg.get('delay_ms', 0) > 0 else ""
            display_name = f"⌨️ 按下 {key_name} {hold_duration}ms{delay_text}"
            item.setText(0, display_name)
        
        # 更新配置数据
        item.setData(0, Qt.ItemDataRole.UserRole, {"type": "key", "config": cfg})

    def _insert_record_to_tree(self, rec_type, data):
        """将录制内容插入到任务树，兼容原有任务格式"""
        tree = self._get_current_tree()
        if not tree: return
        
        item = QTreeWidgetItem()
        
        if rec_type == "mouse":
            # 插入鼠标移动任务，强制使用相对坐标
            dx = data['dx']
            dy = data['dy']
            content = data['content']
            
            cfg = {
                "task_name": content,
                "action_type": "none", # 先只移动
                "move_type": "relative", # 强制相对
                "x": dx, # 存dx
                "y": dy, # 存dy
                "duration": 50
            }
            item.setData(0, Qt.ItemDataRole.UserRole, {"type": "mouse_action", "config": cfg})
            item.setText(0, f"🖱️ {content}")
            item.setForeground(0, QBrush(QColor(245, 158, 11)))
        elif rec_type == "color":
            # 插入颜色任务
            color = data['color']
            x = data['x']
            y = data['y']
            content = data['content']
            
            # 使用绝对坐标模式
            cfg = {
                "color_value": color,
                "task_name": content,
                "x": x, "y": y, "width": 100, "height": 100,  # 搜索范围
                "click_action": "无操作",
                "move_type": "absolute"  # 使用绝对坐标
            }
            item.setData(0, Qt.ItemDataRole.UserRole, {"type": "color", "config": cfg})
            item.setText(0, f"🌈 {content}")
            item.setForeground(0, QBrush(QColor(156, 39, 176)))

        tree.addTopLevelItem(item)
        self.update_task_numbers()
        self.mark_dirty()

    def _start_global_hotkey_listener(self):
        """启动独立的全局快捷键监听线程，整合录制功能与原有快捷键
        修复：运行快捷键从用户配置 custom_run_hotkey 读取，而非固定 F2
        增强：添加完善的启动确认和异常处理"""
        self._ctrl_pressed = False  # 跟踪 Ctrl 键状态

        # 读取用户配置的运行快捷键
        try:
            settings = load_settings()
            self._custom_run_hotkey = settings.get("custom_run_hotkey", "F2")
            self._custom_stop_hotkey = settings.get("custom_stop_hotkey", "F3")
        except Exception:
            self._custom_run_hotkey = "F2"
            self._custom_stop_hotkey = "F3"

        def _hotkey_matches(run_hotkey, key):
            """判断当前按下的 key 是否匹配用户配置的运行快捷键"""
            if not run_hotkey:
                return key == Key.f2
            hk = run_hotkey.strip()
            # 鼠标按键判断
            if hk.startswith("鼠标"):
                return False  # 鼠标在 on_click 中处理
            low = hk.lower()
            # F1~F24
            try:
                from pynput.keyboard import KeyCode as _KC
            except Exception:
                _KC = None
            if hk.upper().startswith("F") and hk[1:].isdigit():
                fn = int(hk[1:])
                try:
                    return key == getattr(Key, f"f{fn}")
                except Exception:
                    return False
            # 单字母/数字
            if len(hk) == 1:
                try:
                    if isinstance(key, _KC) and hasattr(key, "char") and key.char:
                        return key.char.lower() == hk.lower()
                    if isinstance(key, _KC) and hasattr(key, "vk"):
                        # 大写字母 A-Z: vk 65-90，数字 0-9: 48-57
                        if hk.isalpha() and key.vk == ord(hk.upper()):
                            return True
                        if hk.isdigit() and key.vk == ord(hk):
                            return True
                except Exception:
                    pass
                return False
            # 其他常见键
            key_map = {
                "space": (Key.space,), "enter": (Key.enter,), "return": (Key.enter,),
                "esc": (Key.esc,), "escape": (Key.esc,), "tab": (Key.tab,),
                "backspace": (Key.backspace,), "left": (Key.left,), "up": (Key.up,),
                "right": (Key.right,), "down": (Key.down,), "home": (Key.home,),
                "end": (Key.end,),
            }
            if low in key_map:
                return key in key_map[low]
            return False

        def on_press(key):
            try:
                # 跟踪 Ctrl 键状态
                if key == Key.ctrl_l or key == Key.ctrl_r:
                    self._ctrl_pressed = True

                # 检测 Ctrl+X 截图 - 多种方式检测确保可靠
                if self._ctrl_pressed:
                    # 方式1: 通过 char 检测
                    if isinstance(key, KeyCode) and hasattr(key, 'char') and key.char == 'x':
                        QMetaObject.invokeMethod(self, "_take_screenshot", Qt.ConnectionType.QueuedConnection)
                        return True  # 阻止系统剪切操作
                    # 方式2: 通过 vk 码检测 (X键是88)
                    if isinstance(key, KeyCode) and hasattr(key, 'vk') and key.vk == 88:
                        QMetaObject.invokeMethod(self, "_take_screenshot", Qt.ConnectionType.QueuedConnection)
                        return True  # 阻止系统剪切操作

                # 【第1层专用】项目独立快捷键启动（第1层时默认F2/F3不生效）
                if hasattr(self, 'layer_stack') and self.layer_stack.currentIndex() == 0:
                    try:
                        if os.path.exists(self.flow_index_file):
                            with open(self.flow_index_file, 'r', encoding='utf-8') as _f:
                                _flow_index = json.load(_f)
                            for _item in _flow_index:
                                if isinstance(_item, dict) and _item.get('run_hotkey'):
                                    if _hotkey_matches(_item['run_hotkey'], key):
                                        _fid = _item.get('id', '')
                                        if _fid:
                                            QMetaObject.invokeMethod(self, "_on_flow_hotkey_run",
                                                Qt.ConnectionType.QueuedConnection,
                                                Q_ARG(str, _fid))
                                            return True
                    except Exception:
                        pass

                # 【最高优先级】处理启动/停止快捷键 - 自定义启动/停止快捷键
                # 作为Windows API RegisterHotKey的备用方案，确保后台也能响应
                if _hotkey_matches(self._custom_run_hotkey, key):
                    # 启动快捷键: 运行流程
                    QMetaObject.invokeMethod(self, "_on_run_hotkey", Qt.ConnectionType.QueuedConnection)
                    return True  # 让事件继续传递给系统
                elif _hotkey_matches(self._custom_stop_hotkey, key):
                    # 停止快捷键: 停止流程
                    QMetaObject.invokeMethod(self, "_stop_flow", Qt.ConnectionType.QueuedConnection)
                    return True  # 让事件继续传递给系统

                # 【最高优先级】处理录制器的功能按键
                # F4: 切换按键录制
                if key == Key.f4:
                    QMetaObject.invokeMethod(self, "toggle_key_recording", Qt.ConnectionType.QueuedConnection)
                    return True  # 让事件继续传递给系统
                # F5: 记录相对坐标
                elif key == Key.f5:
                    QMetaObject.invokeMethod(self, "record_action", Qt.ConnectionType.QueuedConnection)
                    return True  # 让事件继续传递给系统
                # F6: 回正坐标（回到原点）
                elif key == Key.f6:
                    QMetaObject.invokeMethod(self, "reset_position", Qt.ConnectionType.QueuedConnection)
                    return True  # 让事件继续传递给系统
                # F7: 记录颜色
                elif key == Key.f7:
                    QMetaObject.invokeMethod(self, "record_color", Qt.ConnectionType.QueuedConnection)
                    return True  # 让事件继续传递给系统


                # 处理方向键控制鼠标：按住持续移动
                dir_map = {Key.up:(0, -1), Key.down:(0, 1),
                           Key.left:(-1, 0), Key.right:(1, 0)}
                if key in dir_map:
                    # 第一次移动时记录原点坐标
                    if not self.origin_set:
                        pos = QCursor.pos()
                        self.origin_pos = (pos.x(), pos.y())
                        self.origin_set = True
                        if self.log_window:
                            self.log_window.add_log(f"原点坐标已设置: ({self.origin_pos[0]}, {self.origin_pos[1]})", "INFO")

                    # 计算当前速度（整数）
                    speed = int(self.base_speed * (self.speed_percent / 100.0))
                    if speed < 1:
                        speed = 1
                    dx, dy = dir_map[key][0] * speed, dir_map[key][1] * speed

                    # 【修复】用实际移动差值更新虚拟坐标，确保记录准确
                    # 记录移动前的实际位置
                    before_pos = QCursor.pos()
                    before_x = before_pos.x()
                    before_y = before_pos.y()
                    
                    # 执行移动
                    move_ok = False
                    try:
                        mouse.relative_move(dx, dy)
                        move_ok = True
                    except:
                        pass
                    
                    # 移动成功后，用实际位置差值更新虚拟坐标
                    # 这样虚拟坐标 = 历次方向键移动的实际位移之和
                    # 物理鼠标移动不会影响虚拟坐标（不触发方向键事件就不算）
                    if move_ok:
                        after_pos = QCursor.pos()
                        actual_dx = after_pos.x() - before_x
                        actual_dy = after_pos.y() - before_y
                        self.virtual_x += actual_dx
                        self.virtual_y += actual_dy
                    
                    return True  # 让事件继续传递给系统

                # 【修复】处理速度调整：更健壮的 +/- 键检测
                # 1. 尝试检测小键盘 (VK code)
                if isinstance(key, KeyCode):
                    if key.vk == 107:  # 小键盘 +
                        QMetaObject.invokeMethod(self, "adjust_speed", Qt.ConnectionType.QueuedConnection,
                                                Q_ARG(int, 1)) # 【修改】+1%
                        return True  # 让事件继续传递给系统
                    elif key.vk == 109:  # 小键盘 -
                        QMetaObject.invokeMethod(self, "adjust_speed", Qt.ConnectionType.QueuedConnection,
                                                Q_ARG(int, -1)) # 【修改】-1%
                        return True  # 让事件继续传递给系统
                    # 检测主键盘的 =/+ (通常在退格键旁边) 和 -/_
                    elif key.vk == 187: # 主键盘 =/+ (US layout)
                        QMetaObject.invokeMethod(self, "adjust_speed", Qt.ConnectionType.QueuedConnection,
                                                Q_ARG(int, 1))
                        return True  # 让事件继续传递给系统
                    elif key.vk == 189: # 主键盘 -/_
                        QMetaObject.invokeMethod(self, "adjust_speed", Qt.ConnectionType.QueuedConnection,
                                                Q_ARG(int, -1))
                        return True  # 让事件继续传递给系统

                # 2. 尝试检测 char (适用于某些输入法/布局)
                try:
                    if key.char == '+':
                        QMetaObject.invokeMethod(self, "adjust_speed", Qt.ConnectionType.QueuedConnection,
                                                Q_ARG(int, 1))
                        return True  # 让事件继续传递给系统
                    if key.char == '-':
                        QMetaObject.invokeMethod(self, "adjust_speed", Qt.ConnectionType.QueuedConnection,
                                                Q_ARG(int, -1))
                        return True  # 让事件继续传递给系统
                except AttributeError:
                    pass

                # 然后处理原有全局快捷键
                # F1: 记录坐标 (鼠标配置用)
                if key == Key.f1:
                    QMetaObject.invokeMethod(self, "_on_global_f1_pressed", Qt.ConnectionType.QueuedConnection)
                    return True  # 让事件继续传递给系统
                # 运行快捷键：读取用户配置 custom_run_hotkey，不再固定 F2
                if _hotkey_matches(getattr(self, "_custom_run_hotkey", "F2"), key):
                    QMetaObject.invokeMethod(self, "_on_run_hotkey", Qt.ConnectionType.QueuedConnection)
                    return True  # 让事件继续传递给系统
                # F3: 停止
                elif key == Key.f3:
                    QMetaObject.invokeMethod(self, "_stop_flow", Qt.ConnectionType.QueuedConnection)
                    return True  # 让事件继续传递给系统
                # F12: 显示/隐藏主窗口（用于隐藏托盘图标后恢复窗口）
                elif key == Key.f12:
                    QMetaObject.invokeMethod(self, "_toggle_window_visibility", Qt.ConnectionType.QueuedConnection)
                    return True  # 让事件继续传递给系统

                # 【核心】如果正在录制，处理所有按键的按下
                elif self.recording_keys:
                    key_name = self.get_readable_key(key)

                    # W键自动记录相对坐标：按下W时，先把累积的方向键移动量记录为相对坐标任务
                    # 然后清空记录基准，继续录制W键本身
                    if key_name == 'W':
                        dx = self.virtual_x - self.last_recorded_virtual[0]
                        dy = self.virtual_y - self.last_recorded_virtual[1]
                        if dx != 0 or dy != 0:
                            # 有相对移动，先记录相对坐标（通过invokeMethod保证插入顺序在W键之前）
                            QMetaObject.invokeMethod(self, "_record_action_threadsafe",
                                                     Qt.ConnectionType.QueuedConnection)

                    with self.key_event_lock:
                        if key_name not in self.pressed_keys:
                            # 【高精度录制】使用perf_counter获取毫秒级时间戳
                            press_time = time.perf_counter()
                            
                            # 【修复】计算与上一个事件的间隔延迟
                            delay_ms = 0
                            if self._last_key_event_time is not None:
                                delay_ms = int((press_time - self._last_key_event_time) * 1000)
                            
                            # 更新上一个事件时间
                            self._last_key_event_time = press_time
                            
                            # 记录完整的按键事件
                            event_record = {
                                'type': 'keydown',
                                'key': key_name,
                                'timestamp': press_time,
                                'delay_ms': delay_ms,
                                'absolute_time_ms': int((press_time - self._recording_start_time) * 1000) if self._recording_start_time else 0
                            }
                            self._key_records.append(event_record)
                            
                            # 存储按下时间和任务项引用（任务项稍后在_insert_key_task中更新）
                            self.pressed_keys[key_name] = {
                                'time': press_time,
                                'task': None
                            }
                            
                            # 【修改】先插入等待任务（与上一事件的间隔），再插入按键动作
                            if delay_ms > 0 and self._enable_interval_delay:
                                QMetaObject.invokeMethod(self, "_insert_delay_task",
                                                        Qt.ConnectionType.QueuedConnection,
                                                        Q_ARG(int, delay_ms))
                            
                            # 插入"按下"任务（初始不显示时间，抬起时更新）
                            QMetaObject.invokeMethod(self, "_insert_key_task",
                                                    Qt.ConnectionType.QueuedConnection,
                                                    Q_ARG(str, key_name),
                                                    Q_ARG(str, "press"),
                                                    Q_ARG(int, 0),
                                                    Q_ARG(int, 0))
                    return True  # 让事件继续传递给系统

            except Exception as e:
                print(f"[快捷键] on_press 异常: {e}")
            return True  # 让所有事件都继续传递给系统

        def on_release(key):
            try:
                # 重置 Ctrl 键状态
                if key == Key.ctrl_l or key == Key.ctrl_r:
                    self._ctrl_pressed = False

                # 【核心】如果正在录制，处理按键的抬起
                if self.recording_keys:
                    key_name = self.get_readable_key(key)
                    with self.key_event_lock:
                        if key_name in self.pressed_keys:
                            # 获取按下时间和对应的任务项
                            press_info = self.pressed_keys.pop(key_name)
                            press_time = press_info['time']
                            press_task = press_info.get('task')
                            
                            # 【高精度录制】使用perf_counter获取毫秒级时间戳
                            release_time = time.perf_counter()
                            
                            # 【修复】计算与上一个事件的间隔延迟
                            delay_ms = 0
                            if self._last_key_event_time is not None:
                                delay_ms = int((release_time - self._last_key_event_time) * 1000)
                            
                            # 更新上一个事件时间
                            self._last_key_event_time = release_time
                            
                            # 计算按住时间
                            hold_duration = int((release_time - press_time) * 1000)
                            
                            # 记录完整的按键事件
                            event_record = {
                                'type': 'keyup',
                                'key': key_name,
                                'timestamp': release_time,
                                'delay_ms': delay_ms,
                                'hold_duration_ms': hold_duration,
                                'absolute_time_ms': int((release_time - self._recording_start_time) * 1000) if self._recording_start_time else 0
                            }
                            self._key_records.append(event_record)
                            
                            # 【关键修改】回溯更新按下事件的按住时间
                            if press_task:
                                QMetaObject.invokeMethod(self, "_update_task_delay",
                                                        Qt.ConnectionType.QueuedConnection,
                                                        Q_ARG(QTreeWidgetItem, press_task),
                                                        Q_ARG(int, hold_duration))
                            
                            # 插入"抬起"任务（传入hold_duration供合并时使用）
                            QMetaObject.invokeMethod(self, "_insert_key_task",
                                                    Qt.ConnectionType.QueuedConnection,
                                                    Q_ARG(str, key_name),
                                                    Q_ARG(str, "release"),
                                                    Q_ARG(int, hold_duration),
                                                    Q_ARG(int, 0))
            except Exception as e:
                print(f"[快捷键] on_release 异常: {e}")
            return True  # 让所有事件都继续传递给系统

        def on_mouse_click(x, y, button, pressed):
            """鼠标点击监听：用于用户配置了鼠标按钮作为运行快捷键 + 鼠标录制"""
            try:
                if pressed:
                    run_hotkey = getattr(self, "_custom_run_hotkey", "F2")
                    if run_hotkey and run_hotkey.startswith("鼠标"):
                        want = run_hotkey[2:].lower()
                        btn_str = str(button).replace("Button.", "").lower()
                        if want == btn_str or want == btn_str.replace("button.", ""):
                            QMetaObject.invokeMethod(self, "_on_run_hotkey", Qt.ConnectionType.QueuedConnection)
                
                if getattr(self, 'recording_mouse', False) and pressed:
                    btn_name = str(button).replace("Button.", "")
                    # 【修复】计算与上一个事件的间隔延迟
                    click_time = time.perf_counter()
                    delay_ms = 0
                    if self._last_key_event_time is not None:
                        delay_ms = int((click_time - self._last_key_event_time) * 1000)
                    self._last_key_event_time = click_time
                    
                    # 【修改】先插入等待任务（与上一事件的间隔），再插入鼠标动作
                    if delay_ms > 0 and self._enable_interval_delay:
                        QMetaObject.invokeMethod(self, "_insert_delay_task",
                                                Qt.ConnectionType.QueuedConnection,
                                                Q_ARG(int, delay_ms))
                    
                    QMetaObject.invokeMethod(self, "_insert_mouse_task",
                                            Qt.ConnectionType.QueuedConnection,
                                            Q_ARG(int, x),
                                            Q_ARG(int, y),
                                            Q_ARG(str, btn_name),
                                            Q_ARG(int, 0))
            except Exception as e:
                print(f"[快捷键] on_mouse_click 异常: {e}")

        def on_mouse_move(x, y):
            """鼠标移动监听：完整录制模式下记录鼠标移动轨迹"""
            try:
                if not getattr(self, '_enable_full_recording', False):
                    return
                if not getattr(self, 'recording_mouse', False):
                    return
                
                move_time = time.perf_counter()
                
                # 节流：避免过于密集的移动事件
                if self._last_mouse_move_time is not None:
                    elapsed_ms = int((move_time - self._last_mouse_move_time) * 1000)
                    if elapsed_ms < self._mouse_move_throttle_ms:
                    # 跳过过于密集的移动事件，但不更新 _last_key_event_time
                    # 这样下一个事件（按键/点击）的延迟会正确计算
                        return
                
                # 计算与上一个事件的间隔延迟
                delay_ms = 0
                if self._last_key_event_time is not None:
                    delay_ms = int((move_time - self._last_key_event_time) * 1000)
                self._last_key_event_time = move_time
                self._last_mouse_move_time = move_time
                
                QMetaObject.invokeMethod(self, "_insert_mouse_move_task",
                                        Qt.ConnectionType.QueuedConnection,
                                        Q_ARG(int, x),
                                        Q_ARG(int, y),
                                        Q_ARG(int, delay_ms if self._enable_interval_delay else 0))
            except Exception as e:
                print(f"[快捷键] on_mouse_move 异常: {e}")

        def listen_hotkeys():
            """快捷键监听线程主函数 - 添加完善的异常处理和日志"""
            try:
                from pynput.mouse import Listener as MouseListener
                from pynput.keyboard import Listener as KeyListener

                key_listener = KeyListener(on_press=on_press, on_release=on_release, suppress=False)
                key_listener.start()
                self._hotkey_key_listener = key_listener

                time.sleep(0.1)

                if key_listener.is_alive():
                    print(f"[快捷键] 键盘监听线程已启动，运行快捷键: {getattr(self, '_custom_run_hotkey', 'F2')}")
                else:
                    print(f"[快捷键] 键盘监听线程启动失败！")
                    return

                mouse_listener = None
                try:
                    mouse_listener = MouseListener(on_click=on_mouse_click, on_move=on_mouse_move)
                    mouse_listener.start()
                    self._hotkey_mouse_listener = mouse_listener
                    run_hotkey = getattr(self, "_custom_run_hotkey", "F2")
                    if run_hotkey and run_hotkey.startswith("鼠标"):
                        print(f"[快捷键] 鼠标快捷键监听已启动: {run_hotkey}")
                    else:
                        print(f"[快捷键] 鼠标监听器已启动（用于鼠标录制+移动录制）")
                except Exception as e:
                    print(f"[快捷键] 启动鼠标监听器失败: {e}")

                while getattr(self, '_hotkey_thread', None) is not None:
                    time.sleep(0.5)

            except Exception as e:
                print(f"[快捷键] listen_hotkeys 线程异常: {e}")
                import traceback
                traceback.print_exc()

        # 标记线程为启动状态
        self._hotkey_thread_started = False
        self._hotkey_thread = threading.Thread(target=listen_hotkeys, daemon=True)
        self._hotkey_thread.start()

        # 使用QTimer检查线程启动状态，避免阻塞UI
        self._hotkey_startup_check_count = 0
        def _check_hotkey_startup():
            self._hotkey_startup_check_count += 1
            if hasattr(self, '_hotkey_thread') and self._hotkey_thread.is_alive():
                self._hotkey_thread_started = True
                print(f"[快捷键] 全局快捷键监听线程已成功启动")
                return
            if self._hotkey_startup_check_count >= 10:
                print(f"[快捷键] 警告：快捷键监听线程可能未正常启动")
                return
            QTimer.singleShot(50, _check_hotkey_startup)
        QTimer.singleShot(50, _check_hotkey_startup)

    def _restart_hotkey_listener(self):
        """重启全局快捷键监听线程（含重新注册 Windows 全局热键）"""
        try:
            # 先停止旧的 pynput 监听器（避免重启时创建重复监听器）
            for attr in ('_hotkey_key_listener', '_hotkey_mouse_listener'):
                listener = getattr(self, attr, None)
                if listener is not None:
                    try:
                        if listener.is_alive():
                            listener.stop()
                    except Exception:
                        pass
                    setattr(self, attr, None)
            # 设置 _hotkey_thread = None 让旧线程的 while 循环退出
            self._hotkey_thread = None
        except Exception:
            pass
        # 重新注册 Windows API 全局热键（释放旧键、绑定新键，避免旧 F3 仍被占用）
        try:
            self._unregister_windows_hotkeys()
        except Exception:
            pass
        self._register_windows_hotkeys()
        # 重新启动监听
        self._start_global_hotkey_listener()

    def _refresh_hotkey_buttons(self):
        """根据用户配置更新启动/停止按钮文字与提示"""
        try:
            settings = load_settings()
            run_hk = settings.get("custom_run_hotkey", "F2")
            stop_hk = settings.get("custom_stop_hotkey", "F3")
        except Exception:
            run_hk, stop_hk = "F2", "F3"
        self._custom_run_hotkey = run_hk
        self._custom_stop_hotkey = stop_hk
        if hasattr(self, 'btn_start'):
            self.btn_start.setText(f" {run_hk}启动 ")
            self.btn_start.setToolTip(f"启动流程 ({run_hk})")
        if hasattr(self, 'btn_stop'):
            self.btn_stop.setText(f" {stop_hk}停止 ")
            self.btn_stop.setToolTip(f"停止流程 ({stop_hk})")

