                self.log_window.add_log(f"{task_num_tag}{indent}🖱️ {box_route_tag}执行鼠标动作：{click_action}", "INFO")
                if hwnd and not foreground_mouse:
                    WindowUtils.send_mouse_move(hwnd, target_x, target_y)
