    @staticmethod
    def extract_save_var_names(config):
        if not config or not isinstance(config, dict):
            return set()
        var_names = set()
        
        # 1. 明确的保存变量字段
        explicit_keys = [
            "save_to_variable",
            "save_var",
            "var_name",
            "random_var_name",
            "var_base",
            "color_var_ref",
            "save_pos_to",
            "save_to",
            "save_to_var_name",
        ]
        for key in explicit_keys:
            v = config.get(key, "")
            if v and isinstance(v, str) and v.strip():
                var_names.add(v.strip())
        
        # 2. save_to_var 开关 + var_name
        if config.get("save_to_var"):
            var_field = config.get("var_name", "") or config.get("save_to_var_name", "")
            if var_field and isinstance(var_field, str) and var_field.strip():
                var_names.add(var_field.strip())
        
        # 3. save_random_to_var 开关
        if config.get("save_random_to_var"):
            rand_var = config.get("random_var_name", "")
            if rand_var and isinstance(rand_var, str) and rand_var.strip():
                var_names.add(rand_var.strip())
        
        # 4. 扫描所有包含变量名特征的字段
        skip_keys = {"var_type", "var_category", "var_value", "task_name", "remark", "remark_color", "text"}
        for key in list(config.keys()):
            if not isinstance(key, str) or key in skip_keys:
                continue
            key_lower = key.lower()
            # 检查是否是变量名相关的键
            is_var_key = any(kw in key_lower for kw in [
                "var", "save", "result", "match", "coords", "pos",
                "output", "value", "base", "ref"
            ])
            if is_var_key:
                v = config.get(key, "")
                if v and isinstance(v, str) and v.strip() and len(v.strip()) <= 50:
                    # 排除明显不是变量名的值
                    val = v.strip()
                    if val and not val.startswith("#") and not val.startswith("rgb"):
                        # 排除颜色值和坐标值等
                        if val and len(val) <= 30 and not val.isdigit():
                            var_names.add(val)
        
        return var_names

    def _declare_vars_from_config(self, config):
        if hasattr(self, 'variables') and self.variables:
            var_names = self.extract_save_var_names(config)
            if var_names:
                self.variables.declare_vars(var_names)
                print(f"[变量声明] 从配置中声明变量: {var_names}")
                print(f"[变量声明] 当前所有变量: {self.variables.keys()}")
            else:
                _name = ""
                if isinstance(config, dict):
                    _name = config.get("task_name") or config.get("type") or ""
                print(f"[变量声明] 配置中没有可提取的变量名{'（' + str(_name) + '）' if _name else ''}")
        else:
            print(f"[变量声明] variables 属性不存在或为 None")

    def _declare_all_vars_from_tasks(self):
        if not hasattr(self, 'variables') or not self.variables:
            return
        all_var_names = set()

        def collect_from_item(item):
            data = item.data(0, Qt.ItemDataRole.UserRole)
            if data and isinstance(data, dict):
                config = data.get("config", {})
                if config:
                    var_names = self.extract_save_var_names(config)
                    all_var_names.update(var_names)
            for i in range(item.childCount()):
                collect_from_item(item.child(i))

        if hasattr(self, 'tab_widget'):
            for tab_index in range(self.tab_widget.count()):
                widget = self.tab_widget.widget(tab_index)
                if widget:
                    tree = widget.findChild(TaskTreeWidget)
                    if tree:
                        for i in range(tree.topLevelItemCount()):
                            collect_from_item(tree.topLevelItem(i))

        if all_var_names:
            self.variables.declare_vars(all_var_names)

    def _insert_task(self, tree, data, target_item, pos):
        item = QTreeWidgetItem()
        item.setData(0, Qt.ItemDataRole.UserRole, data)
        task_index = None
        if pos == "Below" and not target_item: task_index = tree.topLevelItemCount() + 1
        elif pos == "Below" and target_item and not target_item.parent(): task_index = tree.indexOfTopLevelItem(target_item) + 2
        self._render(item, data, task_index=task_index)
        config = data.get("config", {}) if data else {}
        self._declare_vars_from_config(config)
        
        # 插入逻辑保持简单，TreeWidget的dropEvent已经处理了复杂逻辑
        if target_item:
            # 这里的逻辑主要给右键菜单用
            if pos == "OnItem":
                target_item.addChild(item)
                target_item.setExpanded(True)
            else:
                parent = target_item.parent()
                if parent:
                    parent.insertChild(parent.indexOfChild(target_item) + 1, item)
                else:
                    tree.insertTopLevelItem(tree.indexOfTopLevelItem(target_item) + 1, item)
        else:
            tree.addTopLevelItem(item)
            
        tree.invalidate_cache()
        self.update_task_numbers()
        self.mark_dirty()

