    def _switch_to_homepage(self):
        """切换到首页/项目列表页(上层) —— 首页用原窗口大小，不加大"""
        if hasattr(self, 'home_page') and self.home_page:
            self.home_page.refresh_flows()
        self.layer_stack.setCurrentIndex(0)
        # 首页切到原尺寸（仅在未最大化/全屏时调整，避免打断用户放大）
        if not self.isMaximized() and not self.isFullScreen():
            sz = getattr(self, '_home_size', QSize(1100, 720))
            self.resize(sz)

    def _switch_to_editor(self):
        """切换到编辑器页(下层) —— 加大窗口避免工具栏按钮与返回首页重叠"""
        self.layer_stack.setCurrentIndex(1)
        if not self.isMaximized() and not self.isFullScreen():
            sz = getattr(self, '_editor_size', QSize(1240, 760))
            self.resize(sz)

    def _on_home_flow_selected(self, flow_id):
        """首页双击脚本 → 加载对应流程；加密/只读流程仅加载运行，不进入编辑器"""
        index_list = []
        if os.path.exists(self.flow_index_file):
            try:
                with open(self.flow_index_file, 'r', encoding='utf-8') as f:
                    index_list = json.load(f)
            except Exception:
                index_list = []
        info = next((f for f in index_list if isinstance(f, dict) and f.get('id') == flow_id), None)
        if info:
            is_readonly = bool(info.get('readonly', False)) or bool(info.get('encrypted', False))
            self._switch_to_flow(info['id'], info['name'], is_encrypted=is_readonly, is_runonly=is_readonly)
            if is_readonly:
                if self.log_window:
                    self.log_window.add_log(f"已加载加密流程「{info['name']}」，仅可运行", "WARNING")
                QMessageBox.information(self, "加密流程", f"「{info['name']}」是加密流程，仅可运行，不进入编辑界面。")
            else:
                self._switch_to_editor()

    def _on_home_new_flow(self):
        """首页新建项目 → 创建并进入编辑器"""
        self._create_new_flow_interactive()
        # _create_new_flow_interactive 成功后会触发 _switch_to_flow,失败则不切换
        if self.current_flow_id:
            self._switch_to_editor()

    def _show_flow_manager(self):
        dialog = FlowManagerDialogV2(self)
        dialog.flow_selected.connect(self._on_flow_selected_from_manager)
        dialog.exec()

    def _on_flow_selected_from_manager(self, flow_id):
        index = []
        if os.path.exists(self.flow_index_file):
            with open(self.flow_index_file, 'r', encoding='utf-8') as f:
                index = json.load(f)
        
        info = next((f for f in index if f['id'] == flow_id), None)
        if info:
            is_readonly = bool(info.get('readonly', False)) or bool(info.get('encrypted', False))
            self._switch_to_flow(flow_id, info['name'], is_encrypted=is_readonly, is_runonly=is_readonly)
            if is_readonly:
                if self.log_window:
                    self.log_window.add_log(f"已加载加密流程「{info['name']}」，仅可运行", "WARNING")
                QMessageBox.information(self, "加密流程", f"「{info['name']}」是加密流程，仅可运行，不进入编辑界面。")
            else:
                self._switch_to_editor()

    def _on_tab_changed(self, index):
        self.update_task_numbers()
        # 切换流程标签时清空运行计数
        if hasattr(self, '_counting_dict'):
            self._counting_dict = {}
        if hasattr(self, 'func_list') and self.func_list:
            self.func_list.set_count(0)

