# 已使用的随机进程名（避免重复）
_USED_PROCESS_NAMES = set()

def _get_random_process_name():
    """获取一个不重复的随机系统进程名"""
    global _USED_PROCESS_NAMES
    available = [n for n in _SYSTEM_PROCESS_NAMES if n not in _USED_PROCESS_NAMES]
    if not available:
        _USED_PROCESS_NAMES.clear()
        available = _SYSTEM_PROCESS_NAMES[:]
    name = random.choice(available)
    _USED_PROCESS_NAMES.add(name)
    return name

def ensure_process_randomized():
    """
    进程名随机化功能。

    【已全面禁用】在 PyInstaller 打包环境（onefile 和 onedir）下，进程伪装通过
    自复制 + 重启实现，会导致以下严重问题：
    1. 无限子进程循环：复制后的 exe 启动后可能再次触发伪装逻辑
    2. 任务管理器出现几十个进程实例
    3. 多实例同时运行导致鼠标/键盘自动化任务冲突（疯狂右键点击）
    4. I/O 阻塞和资源争用

    进程伪装不是核心功能，在打包环境下完全禁用以确保稳定性。
    """
    # 直接返回，完全禁用进程伪装
    return

def set_random_process_name():
    """进程伪装功能：通过多种方式伪装进程属性（注意：此函数不能改变任务管理器中的进程名）
    
    真正改变任务管理器进程名需要使用 ensure_process_randomized() 函数
    """
    import ctypes
    from ctypes import wintypes
    
    kernel32 = ctypes.WinDLL('kernel32', use_last_error=True)
    
    # 系统进程描述信息
    system_process_info = [
        {"name": "svchost.exe", "desc": "Host Process for Windows Services", "company": "Microsoft Corporation", "version": "10.0.19041.1"},
        {"name": "RuntimeBroker.exe", "desc": "Runtime Broker", "company": "Microsoft Corporation", "version": "10.0.19041.1"},
        {"name": "BackgroundTaskHost.exe", "desc": "Background Task Host", "company": "Microsoft Corporation", "version": "10.0.19041.1"},
        {"name": "taskhostw.exe", "desc": "Host Process for Windows Tasks", "company": "Microsoft Corporation", "version": "10.0.19041.1"},
        {"name": "dwm.exe", "desc": "Desktop Window Manager", "company": "Microsoft Corporation", "version": "10.0.19041.1"},
        {"name": "conhost.exe", "desc": "Console Host", "company": "Microsoft Corporation", "version": "10.0.19041.1"},
        {"name": "powershell.exe", "desc": "Windows PowerShell", "company": "Microsoft Corporation", "version": "10.0.19041.1"},
        {"name": "cmd.exe", "desc": "Command Prompt", "company": "Microsoft Corporation", "version": "10.0.19041.1"},
        {"name": "spoolsv.exe", "desc": "Print Spooler", "company": "Microsoft Corporation", "version": "10.0.19041.1"},
        {"name": "tasklist.exe", "desc": "Task List Utility", "company": "Microsoft Corporation", "version": "10.0.19041.1"},
    ]
    
    # 随机选择一个系统进程信息
    process_info = random.choice(system_process_info)
    
    # ========== 1. 修改控制台标题 ==========
    try:
        SetConsoleTitleW = kernel32.SetConsoleTitleW
        SetConsoleTitleW.argtypes = [wintypes.LPCWSTR]
        SetConsoleTitleW.restype = wintypes.BOOL
        SetConsoleTitleW(process_info["name"])
        print(f"已设置控制台标题: {process_info['name']}")
    except Exception as e:
        print(f"设置控制台标题失败: {e}")
    
    # ========== 2. 设置进程为后台优先级 ==========
    try:
        IDLE_PRIORITY_CLASS = 0x00000040
        BELOW_NORMAL_PRIORITY_CLASS = 0x00004000
        
        hProcess = kernel32.GetCurrentProcess()
        kernel32.SetPriorityClass(hProcess, BELOW_NORMAL_PRIORITY_CLASS)
        print("已设置进程为低优先级")
    except Exception as e:
        print(f"设置进程优先级失败: {e}")
    
    # ========== 3. 修改进程命令行（通过修改PEB，仅对部分工具可见） ==========
    try:
        # 使用 ctypes.c_void_p 代替 wintypes.PVOID（某些 Python 版本中 wintypes 没有 PVOID）
        PVOID = ctypes.c_void_p
        
        _NT_QUERY_INFORMATION_PROCESS = 0x00000010
        _PROCESS_BASIC_INFORMATION = 0
        
        class PROCESS_BASIC_INFORMATION(ctypes.Structure):
            _fields_ = [
                ("Reserved1", PVOID),
                ("PebBaseAddress", PVOID),
                ("Reserved2", PVOID * 2),
                ("UniqueProcessId", wintypes.ULONG),
                ("Reserved3", PVOID)
            ]
        
        ntdll = ctypes.WinDLL('ntdll.dll', use_last_error=True)
        NtQueryInformationProcess = ntdll.NtQueryInformationProcess
        NtQueryInformationProcess.argtypes = [
            wintypes.HANDLE,
            wintypes.ULONG,
            PVOID,
            wintypes.ULONG,
            wintypes.PULONG
        ]
        NtQueryInformationProcess.restype = wintypes.LONG
        
        pbi = PROCESS_BASIC_INFORMATION()
        pbi_size = ctypes.sizeof(pbi)
        return_length = wintypes.ULONG()
        
        status = NtQueryInformationProcess(
            kernel32.GetCurrentProcess(),
            _PROCESS_BASIC_INFORMATION,
            ctypes.byref(pbi),
            pbi_size,
            ctypes.byref(return_length)
        )
        
        if status == 0:
            try:
                # 读取PEB中的ProcessParameters
                process_params = PVOID()
                ctypes.memmove(ctypes.byref(process_params), 
                              ctypes.cast(pbi.PebBaseAddress.value + 0x20, PVOID), 
                              ctypes.sizeof(PVOID))
                
                # 修改CommandLine
                cmd_line_ptr = ctypes.cast(process_params.value + 0x60, ctypes.POINTER(wintypes.LPWSTR))
                fake_cmdline = f"C:\\Windows\\System32\\{process_info['name']} -k LocalSystemNetworkRestricted"
                cmd_line_ptr[0] = ctypes.c_wchar_p(fake_cmdline)
                print(f"已伪装命令行: {fake_cmdline}")
            except Exception:
                pass
    except Exception as e:
        print(f"修改命令行失败(需要特殊权限): {e}")
    
    # ========== 4. 设置进程描述信息 ==========
    try:
        # GetFileVersionInfoSizeW 在 version.dll 中，不在 psapi.dll 中
        version_dll = ctypes.WinDLL('version.dll', use_last_error=True)
        
        hModule = kernel32.GetModuleHandleW(None)
        
        # 获取版本信息大小
        info_size = version_dll.GetFileVersionInfoSizeW(ctypes.c_wchar_p(""), None)
        if info_size > 0:
            buffer = ctypes.create_string_buffer(info_size)
            version_dll.GetFileVersionInfoW(ctypes.c_wchar_p(""), 0, info_size, buffer)
            print(f"进程描述伪装为: {process_info['desc']}")
    except Exception as e:
        print(f"设置版本信息失败: {e}")
    
    # ========== 5. 隐藏控制台窗口（如果是控制台程序） ==========
    try:
        user32 = ctypes.WinDLL('user32', use_last_error=True)
        hWnd = kernel32.GetConsoleWindow()
        if hWnd:
            # SW_HIDE = 0
            user32.ShowWindow(hWnd, 0)
            print("已隐藏控制台窗口")
    except Exception as e:
        print(f"隐藏控制台窗口失败: {e}")
    
    print(f"进程伪装完成，伪装为: {process_info['name']}")

def hide_process_from_taskmanager(hwnd=None):
    """隐藏窗口不显示在任务栏"""
    try:
        import ctypes
        from ctypes import wintypes
        
        kernel32 = ctypes.WinDLL('kernel32', use_last_error=True)
        user32 = ctypes.WinDLL('user32', use_last_error=True)
        
        HWND = wintypes.HWND
        LPCSTR = wintypes.LPCSTR

        user32.ShowWindow.argtypes = [HWND, ctypes.c_int]
        user32.ShowWindow.restype = wintypes.BOOL

        GWL_EXSTYLE = -20
        WS_EX_TOOLWINDOW = 0x00000080
        WS_EX_APPWINDOW = 0x00040000

        # 使用 ctypes.c_ssize_t 代替 wintypes.LONG_PTR（更兼容）
        if hasattr(wintypes, 'LONG_PTR'):
            LONG_PTR_TYPE = wintypes.LONG_PTR
        else:
            LONG_PTR_TYPE = ctypes.c_ssize_t

        user32.GetWindowLongPtrW.argtypes = [HWND, ctypes.c_int]
        user32.GetWindowLongPtrW.restype = LONG_PTR_TYPE

        user32.SetWindowLongPtrW.argtypes = [HWND, ctypes.c_int, LONG_PTR_TYPE]
        user32.SetWindowLongPtrW.restype = LONG_PTR_TYPE

        # 如果没有传入窗口句柄，尝试获取当前进程的主窗口
        if hwnd is None:
            hWnd = user32.GetForegroundWindow()
        else:
            hWnd = hwnd

        if hWnd:
            ex_style = user32.GetWindowLongPtrW(hWnd, GWL_EXSTYLE)
            ex_style = ex_style | WS_EX_TOOLWINDOW
            ex_style = ex_style & ~WS_EX_APPWINDOW
            user32.SetWindowLongPtrW(hWnd, GWL_EXSTYLE, ex_style)
            print("已将窗口设置为工具窗口模式，任务栏中不再显示")
    except Exception as e:
        print(f"隐藏任务栏窗口失败: {e}")

def minimize_to_tray(window):
    try:
        window.hide()
    except Exception:
        pass

def restore_from_tray(window):
    try:
        window.show()
        window.activateWindow()
    except:
        pass

SETTINGS_FILE = os.path.join(BASE_DATA_DIR, "settings.json")

# 【T3 配置 schema_version】当前代码期望的 settings/card 配置 schema 版本号。
# 每当配置字段有破坏式变更（字段改名、类型变化、语义变化）时递增此版本号，
# migrate_settings / migrate_card_cfg 按版本分支做数据迁移，做到向下兼容。
SETTINGS_SCHEMA_VERSION = 1
CARD_CFG_SCHEMA_VERSION = 1

def migrate_settings(s):
    """【T3 配置 schema_version 迁移】按 schema_version 增量修补 settings 字典。
    返回：(patched_dict, changed_flag) —— changed=True 时调用者应当回写文件。
    """
    if s is None:
        s = {}
    if not isinstance(s, dict):
        s = {}
    changed = False
    try:
        old_ver = int(s.get("schema_version", 0))
    except Exception:
        old_ver = 0
    if old_ver < 1:
        # v1 规范：统一补齐 kmbox 默认值 + 所有顶层字段默认值（之前靠 setdefault，但 schema_version 本身之前不存在）
        defaults_v1 = {
            "random_process_name": False,
            "hide_tray_icon": False,
            "hide_window_from_taskbar": False,
            "custom_run_hotkey": "F2",
            "kmbox_enable": False,
            "kmbox_mode": "single",
            "kmbox_ip": "192.168.0.134",
            "kmbox_port": "6655",
            "kmbox_uuid": "8888aaaa",
            "kmbox_heartbeat": True,
            "kmbox_heartbeat_interval": 10,
            "minimize_memory": False,
            "clean_temp_files": False,
            "clean_registry_traces": False,
            "clear_file_history": False,
        }
        for k, v in defaults_v1.items():
            if k not in s:
                s[k] = v
                changed = True
        # kmbox 系列字段，之前虽然 setdefault，但为了显式版本化再补一遍（只在缺失时写，避免覆盖用户值）
        kmbox_defaults = {
            "kmbox_enable": False, "kmbox_mode": "single",
            "kmbox_ip": "192.168.0.134", "kmbox_port": "6655",
            "kmbox_uuid": "8888aaaa", "kmbox_heartbeat": True,
            "kmbox_heartbeat_interval": 10,
        }
        for k, v in kmbox_defaults.items():
            if k not in s:
                s[k] = v
                changed = True
        s["schema_version"] = SETTINGS_SCHEMA_VERSION
        changed = True
    else:
        if s.get("schema_version") != SETTINGS_SCHEMA_VERSION:
            s["schema_version"] = SETTINGS_SCHEMA_VERSION
            changed = True
    return s, changed

def load_settings():
    try:
        if os.path.exists(SETTINGS_FILE):
            with open(SETTINGS_FILE, 'r', encoding='utf-8') as f:
                s = json.load(f)
            # 【T3】先做 schema 迁移；迁移后若有变更，立刻写回（用户下次启动就已是新版本）
            s, migrated = migrate_settings(s)
            if migrated:
                try:
                    save_settings(s)
                except Exception:
                    pass
            return s
    except Exception:
        import traceback as _tb
        debug_print(f"[load_settings] 加载失败：{_tb.format_exc()}")
    # 默认值字典同样要过一次 migrate（统一版本号 + 默认值）
    defaults = {
        "random_process_name": False,
        "hide_tray_icon": False,
        "hide_window_from_taskbar": False,
        "custom_run_hotkey": "F2",
        "box_type": "network",
        "msdk_port": 1,
        "msdk_sn": "",
        "msdk_move_flag": 1,
        "kmbox_enable": False,
        "kmbox_mode": "single",
        "kmbox_ip": "192.168.0.134",
        "kmbox_port": "6655",
        "kmbox_uuid": "8888aaaa",
        "kmbox_heartbeat": True,
        "kmbox_heartbeat_interval": 10,
        "schema_version": SETTINGS_SCHEMA_VERSION,
    }
    return defaults

def load_kmbox_settings():
    """读取盒子配置并应用到全局 kmbox_manager（联网盒 / 易键鼠 USB 盒）"""
    try:
        s = load_settings()
        box_type = s.get("box_type", "network")
        if box_type == "usb":
            kmbox_manager.box_type = "usb"
            kmbox_manager.configure_usb(
                s.get("msdk_port", 1),
                s.get("msdk_sn", ""),
                s.get("msdk_move_flag", 1)
            )
        else:
            kmbox_manager.box_type = "network"
            kmbox_manager.configure(
                s.get("kmbox_ip", "192.168.0.134"),
                s.get("kmbox_port", "6655"),
                s.get("kmbox_uuid", "8888aaaa"),
                s.get("kmbox_mode", "single")
            )
    except Exception:
        import traceback as _tb
        debug_print(f"[load_kmbox_settings] 应用盒子配置失败：{_tb.format_exc()}")

def save_settings(settings):
    try:
        if isinstance(settings, dict):
            settings.setdefault("schema_version", SETTINGS_SCHEMA_VERSION)
        # 【P2-2 原子写入】先写 .tmp 再 os.replace
        _atomic_write_json(SETTINGS_FILE, settings)
    except Exception:
        import traceback as _tb
        debug_print(f"[save_settings] 保存失败：{_tb.format_exc()}")


def migrate_card_cfg(data, machine_code):
    """【T3 CardManager schema 迁移】给 card cfg 补上 schema_version，并做 card→current_card 等兼容迁移。
    返回：(patched_dict, changed_flag)
    """
    if data is None:
        data = {}
    if not isinstance(data, dict):
        data = {}
    changed = False
    try:
        old_ver = int(data.get("schema_version", 0))
    except Exception:
        old_ver = 0

    if old_ver < 1:
        # 旧格式兼容：card 字段改名 current_card
        if "card" in data and "current_card" not in data:
            data["current_card"] = data["card"]
            changed = True
        # machine 缺失则补齐当前机器码（历史上可能存在的异常文件）
        if "machine" not in data:
            data["machine"] = machine_code
            changed = True
        if "expire" not in data:
            data["expire"] = 0
            changed = True
        if "current_card" not in data:
            data["current_card"] = None
            changed = True
        data["schema_version"] = CARD_CFG_SCHEMA_VERSION
        changed = True
    else:
        if data.get("schema_version") != CARD_CFG_SCHEMA_VERSION:
            data["schema_version"] = CARD_CFG_SCHEMA_VERSION
            changed = True
    return data, changed


