    def _on_box_type_changed(self, checked):
        usb = self.radio_box_usb.isChecked()
        self.usb_section.setVisible(usb)
        # 只禁用联网盒专属参数（单双机模式/IP/端口/UUID/测试），启用开关与心跳对两种盒子都有效
        network_controls = [
            self.radio_kmbox_single, self.radio_kmbox_dual,
            self.edit_kmbox_ip, self.edit_kmbox_port, self.edit_kmbox_uuid,
            self.btn_kmbox_test,
        ]
        for w in network_controls:
            w.setEnabled(not usb)
        self.adjustSize()

    def _scan_usb_boxes(self):
        self.lbl_usb_status.setText("正在扫描...")
        self.lbl_usb_status.setStyleSheet(f"color: {COLOR_WARNING}; font-size: 12px;")
        QApplication.processEvents()
        boxes = kmbox_manager.scan_usb_boxes()
        self.combo_usb_boxes.clear()
        self._usb_box_ports = []
        if not boxes:
            self.lbl_usb_status.setText("❌ 未扫描到盒子")
            self.lbl_usb_status.setStyleSheet(f"color: {COLOR_DANGER}; font-size: 12px;")
            return
        for box in boxes:
            sn = box.get('sn') or ''
            label = f"端口 {box['port']}" + (f" ｜ 序列号 {sn}" if sn else "")
            self.combo_usb_boxes.addItem(label, box['port'])
            self._usb_box_ports.append((box['port'], sn))
        saved_sn = self.settings.get("msdk_sn", "")
        saved_port = self.settings.get("msdk_port", 1)
        idx = -1
        if saved_sn:
            for i, (p, s) in enumerate(self._usb_box_ports):
                if s == saved_sn:
                    idx = i
                    break
        if idx < 0:
            for i, (p, s) in enumerate(self._usb_box_ports):
                if p == saved_port:
                    idx = i
                    break
        if idx >= 0:
            self.combo_usb_boxes.setCurrentIndex(idx)
        self.lbl_usb_status.setText(f"✅ 已扫描到 {len(boxes)} 个盒子")
        self.lbl_usb_status.setStyleSheet(f"color: {COLOR_SUCCESS}; font-size: 12px;")

    def _test_kmbox_connection(self):
        """测试连接 kmbox 联网盒子（后台线程执行，避免 UI 主线程卡死）"""
        ip = self.edit_kmbox_ip.text().strip()
        port = self.edit_kmbox_port.text().strip()
        uuid = self.edit_kmbox_uuid.text().strip()
        mode = "dual" if self.radio_kmbox_dual.isChecked() else "single"
        if not (ip and port and uuid):
            self.lbl_kmbox_status.setText("❌ 参数不完整")
            self.lbl_kmbox_status.setStyleSheet(f"color: {COLOR_DANGER}; font-size: 12px; padding: 4px 10px;")
            return
        if getattr(self, '_kmbox_testing', False):
            return
        self._kmbox_testing = True
        self._kmbox_test_result = None
        self.lbl_kmbox_status.setText("正在连接...")
        self.lbl_kmbox_status.setStyleSheet(f"color: {COLOR_WARNING}; font-size: 12px; padding: 4px 10px;")
        kmbox_manager.configure(ip, port, uuid, mode)
        kmbox_manager.enabled = False
        # 「测试连接」固定测试联网盒(kmboxNet)：全局 box_type 可能仍是 usb，
        # 若直接 connect() 会路由到易键鼠 USB 盒，导致“没插联网盒也显示连接成功”。
        prev_box_type = kmbox_manager.box_type
        prev_connected = kmbox_manager.connected
        kmbox_manager.box_type = 'network'
        kmbox_manager.connected = False

        def _worker():
            try:
                ok, msg = kmbox_manager.connect()
            except Exception as e:
                ok, msg = False, str(e)
            finally:
                kmbox_manager.box_type = prev_box_type
                if not ok:
                    kmbox_manager.connected = False
                else:
                    kmbox_manager.connected = prev_connected
            self._kmbox_test_result = (ok, msg)

        threading.Thread(target=_worker, daemon=True).start()
        if not hasattr(self, '_kmbox_test_timer') or self._kmbox_test_timer is None:
            self._kmbox_test_timer = QTimer(self)
            self._kmbox_test_timer.timeout.connect(self._poll_kmbox_test)
        self._kmbox_test_timer.start(150)

    def _poll_kmbox_test(self):
        """轮询后台测试连接线程结果并更新状态"""
        if self._kmbox_test_result is None:
            return
        ok, msg = self._kmbox_test_result
        self._kmbox_test_result = None
        self._kmbox_testing = False
        if self._kmbox_test_timer is not None:
            self._kmbox_test_timer.stop()
        if ok:
            self.lbl_kmbox_status.setText("✅ 连接成功")
            self.lbl_kmbox_status.setStyleSheet(f"color: {COLOR_SUCCESS}; font-size: 12px; padding: 4px 10px;")
        else:
            self.lbl_kmbox_status.setText("❌ 失败")
            self.lbl_kmbox_status.setStyleSheet(f"color: {COLOR_DANGER}; font-size: 12px; padding: 4px 10px;")
            kmbox_manager.connected = False

    def _save(self):
        kmbox_mode = "dual" if self.radio_kmbox_dual.isChecked() else "single"
        box_type = "usb" if self.radio_box_usb.isChecked() else "network"
        usb_port = self.settings.get("msdk_port", 1)
        usb_sn = self.settings.get("msdk_sn", "")
        if box_type == "usb":
            data = self.combo_usb_boxes.currentData()
            if data is not None:
                usb_port = int(data)
                ci = self.combo_usb_boxes.currentIndex()
                if 0 <= ci < len(self._usb_box_ports):
                    usb_sn = self._usb_box_ports[ci][1] or usb_sn
        s = load_settings()
        s.update({
            "box_type": box_type,
            "msdk_port": usb_port,
            "msdk_sn": usb_sn,
            "kmbox_enable": self.chk_kmbox_enable.isChecked(),
            "kmbox_mode": kmbox_mode,
            "kmbox_ip": self.edit_kmbox_ip.text().strip(),
            "kmbox_port": self.edit_kmbox_port.text().strip(),
            "kmbox_uuid": self.edit_kmbox_uuid.text().strip(),
            "kmbox_heartbeat": self.chk_kmbox_heartbeat.isChecked(),
            "kmbox_heartbeat_interval": self.spin_kmbox_hb_interval.value(),
        })
        save_settings(s)
        load_kmbox_settings()
        # 【修复】保存时绝不在 UI 主线程同步连接盒子：
        #   没插盒子时 kmNet.init() 可能长时间阻塞，导致界面永久无响应。
        #   启用连接的动作延迟到对话框关闭后，由主窗口在后台线程异步执行。
        if not s.get("kmbox_enable"):
            kmbox_manager.set_enabled(False)
        self.accept()


