        type_layout = QVBoxLayout()
        type_layout.setSpacing(6)
        
        self.radio_normal = QRadioButton("📄 无密码导出")
        self.radio_encrypted = QRadioButton("🔐 加密导出")
        self.radio_runonly = QRadioButton("⚡ 仅可运行导出")
