    def _select_box1_area(self):
        """框选1 - 选取起点区域"""
        self.select_box_num = 1
        self.setVisible(False)
        QApplication.processEvents()
        self.select_window = ScreenSelectWindow(self)
        self.select_window.selected.connect(self._on_box_selected)
        self.select_window.cancelled.connect(self._on_box_cancelled)

    def _select_box2_area(self):
        """框选2 - 选取终点区域"""
        self.select_box_num = 2
        self.setVisible(False)
        QApplication.processEvents()
        self.select_window = ScreenSelectWindow(self)
        self.select_window.selected.connect(self._on_box_selected)
        self.select_window.cancelled.connect(self._on_box_cancelled)

    def _on_box_selected(self, rect):
        x, y, w, h = rect
        area_str = f"{x},{y},{w},{h}"
        is_box1 = (self.select_box_num == 1)
        if is_box1:
            self.cfg['box1_area'] = area_str
        else:
            self.cfg['box2_area'] = area_str
        
        # 先恢复对话框显示
        self.setVisible(True)
        self.raise_()
        self.activateWindow()
        
        # 清理引用
        if hasattr(self, 'select_window'):
            self.select_window = None
        
        # OCR识别放到后台线程执行，避免阻塞主线程导致卡死
        def ocr_in_background():
            try:
                import base64
                import requests
                import cv2
                import numpy as np
                from PIL import ImageGrab
                
                img = ImageGrab.grab(bbox=(x, y, x + w, y + h))
                img_cv = cv2.cvtColor(np.array(img), cv2.COLOR_RGB2BGR)
                _, buf = cv2.imencode(".jpg", img_cv, [cv2.IMWRITE_JPEG_QUALITY, 95])
                b64_data = base64.b64encode(buf).decode("utf-8")

                res = _safe_post(OCR_API, json={"base64": b64_data}, timeout=15)
                if res.status_code == 200:
                    data = res.json().get("data", [])
                    coord_pattern = re.compile(r'[\(（]?\s*(\d+)\s*[,：:]\s*(\d+)\s*[\)）]?')
                    result = []
                    for item in data:
                        text = item.get("text", "").strip()
                        match = coord_pattern.search(text)
                        if match:
                            coord_x = int(match.group(1))
                            coord_y = int(match.group(2))
                            result.append((text, coord_x, coord_y))
                    
                    if result:
                        all_x = [item[1] for item in result]
                        all_y = [item[2] for item in result]
                        left_x = min(all_x)
                        right_y = max(all_y)
                        coord_str = f"{left_x},{right_y}"
                        # 通过信号在主线程更新UI
                        QMetaObject.invokeMethod(self, "_update_coord_from_ocr", 
                            Qt.ConnectionType.QueuedConnection,
                            Q_ARG(str, coord_str),
                            Q_ARG(bool, is_box1))
            except Exception:
                pass

        import threading
        threading.Thread(target=ocr_in_background, daemon=True).start()

    def _on_box_cancelled(self):
        self.setVisible(True)
        self.raise_()
        self.activateWindow()
        if hasattr(self, 'select_window'):
            self.select_window = None
    
    def _select_coord_file(self):
        """选择本地坐标文件"""
        path, _ = QFileDialog.getOpenFileName(
            self, "选择坐标文件",
            os.path.join(os.path.expanduser("~"), "Desktop"),
            "文本文件 (*.txt);;所有文件 (*.*)"
        )
        if path:
            self.coord_file_path = path
            # 清空终点输入框，表示使用文件模式
            self.target_coord_edit.setText("")
            self.target_coord_edit.setPlaceholderText("使用文件: " + os.path.basename(path))
    
    def eventFilter(self, obj, event):
        """事件过滤器 - 处理F1快捷键获取当前鼠标坐标"""
        if event.type() == QEvent.Type.KeyPress:
            if event.key() == Qt.Key.Key_F1:
                # 获取当前鼠标位置
                cursor_pos = QCursor.pos()
                x, y = cursor_pos.x(), cursor_pos.y()
                # 检查是否是方向输入框
                if obj in self.dir_edits.values():
                    obj.setText(f"{x},{y}")
                    return True
        return super().eventFilter(obj, event)
    
    @Slot(str, bool)
    def _update_coord_from_ocr(self, coord_str, is_box1):
        """OCR识别完成后更新坐标输入框（后台线程回调，必须通过信号槽在主线程执行）"""
        # 只更新起点坐标，终点需要用户手动输入
        if is_box1:
            self.current_coord_edit.setText(coord_str)
    
    def _show_var_select_dialog(self, target_edit, title):
        """显示变量选择对话框 - 使用增强版"""
        selected_data, selected_label = VarSelectDialog.get_var_selection(
            self, self, axis=None, show_clear=False
        )
        
        if selected_data is None:
            return
        
        source_type, val = selected_data
        if source_type == 'var':
            target_edit.setText(val)
            if hasattr(self.variables, 'declare_var'):
                self.variables.declare_var(val)
    
    def _on_ok(self):
        config = self.get_config()
        # 立即声明变量，确保其他功能立即可用
        if hasattr(self.variables, 'declare_from_config'):
            self.variables.declare_from_config(config)
        self.saved.emit(config)
        self.accept()
    
    def get_config(self):
        config = {
            'box1_area': self.cfg.get('box1_area', ''),
            'box2_area': self.cfg.get('box2_area', ''),
            'current_coord': self.current_coord_edit.text(),
            'target_coord': self.target_coord_edit.text(),
            'offset': self.offset_edit.text(),
            'output_var': self.output_var_edit.text(),
            'click_type': self.click_type_combo.currentText(),
        }
        
        # 保存最大迭代次数
        try:
            config['max_iterations'] = int(self.max_iterations_edit.text())
        except:
            config['max_iterations'] = 50
        
        # 随机延迟配置
        config['delay_min'] = self.delay_min_edit.text()
        config['delay_max'] = self.delay_max_edit.text()
        
        # 窗口激活配置
        config['enable_win_activate'] = self.win_activate_group.isChecked()
        config['win_activate_coord'] = self.win_activate_edit.text()
        config['win_activate_click'] = self.win_activate_click_combo.currentText()
        config['win_delay'] = self.win_delay_edit.text()
        
        # 保存8方向配置
        for d in self.DIRECTIONS:
            config[f'coord_{d}'] = self.dir_edits[d].text()
            config[f'enable_{d}'] = self.dir_checkboxes[d].isChecked()
        
        # 本地坐标文件
        config['coord_file'] = getattr(self, 'coord_file_path', '')
        
        return config

