    def _select_box1_area(self):
        """框选起点区域"""
        self.setVisible(False)
        QApplication.processEvents()
        self.select_window = ScreenSelectWindow(self)
        self.select_window.selected.connect(self._on_box1_selected)
        self.select_window.cancelled.connect(self._on_box_cancelled)
    
    def _on_box1_selected(self, rect):
        """框选完成"""
        x, y, w, h = rect
        self.cfg['box1_area'] = f"{x},{y},{w},{h}"
        self.setVisible(True)
        self.raise_()
        self.activateWindow()
        
        if hasattr(self, 'select_window'):
            self.select_window = None
        
        # OCR识别
        def ocr_in_background():
            try:
                import base64
                import requests
                import cv2
                import numpy as np
                from PIL import ImageGrab
                
                img = ImageGrab.grab(bbox=(x, y, x + w, y + h))
                img_cv = cv2.cvtColor(np.array(img), cv2.COLOR_RGB2BGR)
                _, buf = cv2.imencode(".jpg", img_cv, [cv2.IMWRITE_JPEG_QUALITY, 95])
                b64_data = base64.b64encode(buf).decode("utf-8")
                
                res = _safe_post(OCR_API, json={"base64": b64_data}, timeout=15)
                if res.status_code == 200:
                    data = res.json().get("data", [])
                    coord_pattern = re.compile(r'[\(（]?\s*(\d+)\s*[,：:]\s*(\d+)\s*[\)）]?')
                    result = []
                    for item in data:
                        text = item.get("text", "").strip()
                        match = coord_pattern.search(text)
                        if match:
                            coord_x = int(match.group(1))
                            coord_y = int(match.group(2))
                            result.append((text, coord_x, coord_y))
                    
                    if result:
                        all_x = [item[1] for item in result]
                        all_y = [item[2] for item in result]
                        left_x = min(all_x)
                        right_y = max(all_y)
                        coord_str = f"{left_x},{right_y}"
                        QMetaObject.invokeMethod(self, "_update_coord_from_ocr", 
                            Qt.ConnectionType.QueuedConnection,
                            Q_ARG(str, coord_str))
            except:
                pass
        
        import threading
        threading.Thread(target=ocr_in_background, daemon=True).start()
    
    @Slot(str)
    def _update_coord_from_ocr(self, coord_str):
        """OCR识别完成后更新起点坐标"""
        self.current_coord_edit.setText(coord_str)
    
    def _on_box_cancelled(self):
        """框选取消"""
        self.setVisible(True)
        self.raise_()
        self.activateWindow()
        if hasattr(self, 'select_window'):
            self.select_window = None
    
    def _show_var_select_dialog(self, target_edit, title):
        """显示变量选择对话框 - 使用增强版"""
        selected_data, selected_label = VarSelectDialog.get_var_selection(
            self, self, axis=None, show_clear=False
        )
        
        if selected_data is None:
            return
        
        source_type, val = selected_data
        if source_type == 'var':
            target_edit.setText(val)
            if hasattr(self.variables, 'declare_var'):
                self.variables.declare_var(val)
    
    def _on_ok(self):
        config = self.get_config()
        # 立即声明变量，确保其他功能立即可用
        if hasattr(self.variables, 'declare_from_config'):
            self.variables.declare_from_config(config)
        self.saved.emit(config)
        self.accept()
    
    def get_config(self):
        config = {
            'current_coord': self.current_coord_edit.text(),
            'target_coord': self.target_coord_edit.text(),
            'offset': self.offset_edit.text(),
            'output_var': self.output_var_edit.text(),
        }
        
        try:
            config['max_iterations'] = int(self.max_iterations_edit.text())
        except:
            config['max_iterations'] = 100
        
        for d in self.DIRECTIONS:
            config[f'key_{d}'] = self.dir_edits[d].text()
            config[f'enable_{d}'] = self.dir_checkboxes[d].isChecked()
        
        return config

