    def import_file(self):
        if self.convert_direction == 'bloody_to_dmf':
            filepath, _ = QFileDialog.getOpenFileName(
                self, '选择血手宝典文件', '',
                'AMC2文件 (*.amc2 *.xml);;所有文件 (*.*)'
            )
        elif self.convert_direction == 'km_to_dmf':
            filepath, _ = QFileDialog.getOpenFileName(
                self, '选择魔盒KM脚本文件', '',
                '魔盒脚本 (*.km);;所有文件 (*.*)'
            )
        else:
            filepath, _ = QFileDialog.getOpenFileName(
                self, '选择灵枢 DMF 文件', '',
                '道码流程文件 (*.dmf);;所有文件 (*.*)'
            )
        
        if not filepath:
            return
        
        self.input_filepath = filepath
        
        try:
            filename = os.path.basename(filepath)
            
            if self.convert_direction == 'bloody_to_dmf':
                parser = BloodyScriptParser()
                self.bloody_data = parser.parse_file(filepath)
                
                if self.bloody_data.get('is_encrypted', False) and len(self.bloody_data.get('script_lines', [])) == 0:
                    error_msg = self.bloody_data.get('error_message', '文件已加密')
                    self.status_icon.setText('🔒')
                    self.status_text.setText('无法解密')
                    self.status_detail.setText(error_msg)
                    self.btn_convert.setEnabled(False)
                    self.btn_export_dmf.setEnabled(False)
                    
                    reply = QMessageBox.question(
                        self, '无法解密',
                        '%s\n\n是否手动输入解密后的脚本内容？' % error_msg,
                        QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No
                    )
                    
                    if reply == QMessageBox.StandardButton.Yes:
                        self.show_manual_input()
                    return
                
                self.flow_name = os.path.splitext(filename)[0]
                if '【破解】' in self.flow_name:
                    self.flow_name = self.flow_name.replace('【破解】', '')
                
                line_count = len(self.bloody_data.get('script_lines', []))
                
                self.status_icon.setText('✅')
                self.status_text.setText('文件导入成功')
                self.status_detail.setText('%s · %d 条指令' % (filename, line_count))
            
            elif self.convert_direction == 'km_to_dmf':
                parser = KMScriptParser()
                self.km_data = parser.parse_file(filepath)
                
                self.flow_name = os.path.splitext(filename)[0]
                
                line_count = len(self.km_data.get('main_lines', []))
                sub_count = len(self.km_data.get('subs', {}))
                
                self.status_icon.setText('✅')
                self.status_text.setText('文件导入成功')
                self.status_detail.setText('%s · %d 行主脚本 · %d 个子程序' % (filename, line_count, sub_count))
            
            else:
                self.current_flow_data = self._parse_dmf_file(filepath)
                
                self.flow_name = os.path.splitext(filename)[0]
                
                total_tasks = 0
                for tab in self.current_flow_data.get('tabs', []):
                    total_tasks += len(tab.get('tasks', []))
                
                self.status_icon.setText('✅')
                self.status_text.setText('文件导入成功')
                self.status_detail.setText('%s · %d 个任务' % (filename, total_tasks))
            
            self.btn_convert.setEnabled(True)
            self.btn_export_dmf.setEnabled(False)
            self.btn_export_bloody.setEnabled(False)
            self.btn_export_km.setEnabled(False)
            
        except Exception as e:
            self.status_icon.setText('❌')
            self.status_text.setText('导入失败')
            self.status_detail.setText(str(e)[:50])
            QMessageBox.critical(self, '错误', '导入文件失败：%s' % str(e))
    
    def _parse_dmf_file(self, filepath):
        with zipfile.ZipFile(filepath, 'r') as zipf:
            namelist = zipf.namelist()
            
            flow_json_path = None
            for name in namelist:
                if name.endswith('/flow.json'):
                    flow_json_path = name
                    break
            
            if not flow_json_path:
                raise ValueError('DMF文件中未找到flow.json')
            
            with zipf.open(flow_json_path) as f:
                flow_json_str = f.read().decode('utf-8')
                return json.loads(flow_json_str)
    
    def show_manual_input(self):
        dialog = QDialog(self)
        dialog.setWindowTitle('手动输入脚本内容')
        dialog.setMinimumSize(600, 400)
        
        layout = QVBoxLayout(dialog)
        
        label = QLabel('请粘贴解密后的血手宝典脚本内容（XML格式）：')
        label.setStyleSheet('font-size: 13px; color: #6b7280; margin-bottom: 8px;')
        layout.addWidget(label)
        
        text_edit = QTextEdit()
        text_edit.setStyleSheet('font-family: Consolas, monospace; font-size: 12px;')
        text_edit.setPlaceholderText('<Macro name="...">\n    <Syntax>\n        ...\n    </Syntax>\n</Macro>')
        layout.addWidget(text_edit)
        
        btn_layout = QHBoxLayout()
        btn_layout.addStretch()
        
        btn_cancel = QPushButton('取消')
        btn_cancel.clicked.connect(dialog.reject)
        btn_layout.addWidget(btn_cancel)
        
        btn_ok = QPushButton('确认导入')
        btn_ok.clicked.connect(dialog.accept)
        btn_layout.addWidget(btn_ok)
        
        layout.addLayout(btn_layout)
        
        if dialog.exec() == QDialog.DialogCode.Accepted:
            content = text_edit.toPlainText().strip()
            if content:
                self._process_manual_content(content)
    
    def _process_manual_content(self, content):
        try:
            parser = BloodyScriptParser()
            self.bloody_data = parser.parse_content(content)
            
            if self.bloody_data.get('is_encrypted', False) and len(self.bloody_data.get('script_lines', [])) == 0:
                self.status_icon.setText('🔒')
                self.status_text.setText('解析失败')
                self.status_detail.setText('内容不是有效的XML格式')
                self.btn_convert.setEnabled(False)
                self.btn_export_dmf.setEnabled(False)
                return
            
            self.flow_name = '手动输入脚本'
            line_count = len(self.bloody_data.get('script_lines', []))
            
            self.status_icon.setText('✅')
            self.status_text.setText('内容导入成功')
            self.status_detail.setText('手动输入 · %d 条指令' % line_count)
            
            self.btn_convert.setEnabled(True)
            self.btn_export_dmf.setEnabled(False)
            
        except Exception as e:
            self.status_icon.setText('❌')
            self.status_text.setText('导入失败')
            self.status_detail.setText(str(e)[:50])
            QMessageBox.critical(self, '错误', '导入内容失败：%s' % str(e))
    
    def convert_file(self):
        try:
            if self.convert_direction == 'bloody_to_dmf':
                if not self.bloody_data:
                    return
                
                converter = BloodyToDMFConverter()
                self.current_flow_data = converter.convert(
                    self.bloody_data, 
                    flow_name=self.flow_name
                )
                
                tasks = self.current_flow_data['tabs'][0]['tasks']
                total = self._count_tasks(tasks)
                
                self.status_icon.setText('🎉')
                self.status_text.setText('转换成功！')
                self.status_detail.setText('共 %d 个节点，%d 个顶层节点' % (total, len(tasks)))
                
                self.btn_export_dmf.setEnabled(True)
                self.btn_export_bloody.setEnabled(False)
                self.btn_export_km.setEnabled(False)
                
            elif self.convert_direction == 'km_to_dmf':
                if not self.km_data:
                    return
                
                converter = KMToDMFConverter()
                self.current_flow_data = converter.convert(
                    self.km_data,
                    macro_name=self.flow_name
                )
                self.skipped_tasks = converter.skipped_tasks
                
                total_tabs = len(self.current_flow_data.get('tabs', []))
                total_tasks = 0
                for tab in self.current_flow_data.get('tabs', []):
                    total_tasks += len(tab.get('tasks', []))
                
                self.status_icon.setText('🎉')
                self.status_text.setText('转换成功！')
                
                if self.skipped_tasks:
                    self.status_detail.setText('%d 个标签页 · %d 个任务 · %d 个跳过' % (total_tabs, total_tasks, len(self.skipped_tasks)))
                else:
                    self.status_detail.setText('%d 个标签页 · %d 个任务' % (total_tabs, total_tasks))
                
                self.btn_export_dmf.setEnabled(True)
                self.btn_export_bloody.setEnabled(False)
                self.btn_export_km.setEnabled(False)
                
            elif self.convert_direction == 'dmf_to_km':
                if not self.current_flow_data:
                    return
                
                converter = DMFToKMConverter()
                self.km_script_content = converter.convert(
                    self.current_flow_data,
                    macro_name=self.flow_name
                )
                self.skipped_tasks = converter.skipped_tasks
                
                line_count = len(self.km_script_content.split('\n'))
                
                self.status_icon.setText('🎉')
                self.status_text.setText('转换成功！')
                
                if self.skipped_tasks:
                    self.status_detail.setText('共 %d 行魔盒脚本，%d 个任务被跳过' % (line_count, len(self.skipped_tasks)))
                else:
                    self.status_detail.setText('共 %d 行魔盒脚本' % line_count)
                
                self.btn_export_km.setEnabled(True)
                self.btn_export_dmf.setEnabled(False)
                self.btn_export_bloody.setEnabled(False)
                
            else:
                if not self.current_flow_data:
                    return
                
                converter = DMFToBloodyConverter()
                self.bloody_script_content = converter.convert(
                    self.current_flow_data,
                    macro_name=self.flow_name
                )
                self.skipped_tasks = converter.skipped_tasks
                
                line_count = len(self.bloody_script_content.split('\n'))
                
                self.status_icon.setText('🎉')
                self.status_text.setText('转换成功！')
                
                if self.skipped_tasks:
                    self.status_detail.setText('共 %d 行血手脚本，%d 个任务被跳过' % (line_count, len(self.skipped_tasks)))
                else:
                    self.status_detail.setText('共 %d 行血手脚本' % line_count)
                
                self.btn_export_bloody.setEnabled(True)
                self.btn_export_dmf.setEnabled(False)
                self.btn_export_km.setEnabled(False)
                
        except Exception as e:
            self.status_icon.setText('❌')
            self.status_text.setText('转换失败')
            self.status_detail.setText(str(e)[:50])
            QMessageBox.critical(self, '错误', '转换失败：%s' % str(e))
    
    def _count_tasks(self, tasks):
        count = 0
        for task in tasks:
            count += 1
            children = task.get('subtasks', [])
            if children:
                count += self._count_tasks(children)
        return count
    
    def export_dmf(self):
        if not self.current_flow_data:
            return
        
        try:
            default_name = '%s.dmf' % self.flow_name
            filepath, _ = QFileDialog.getSaveFileName(
                self, '导出 DMF 文件', default_name,
                '道码流程文件 (*.dmf);;所有文件 (*.*)'
            )
            if not filepath:
                return
            
            flow_id = str(uuid.uuid4())[:8]
            
            zip_buffer = io.BytesIO()
            with zipfile.ZipFile(zip_buffer, 'w', zipfile.ZIP_DEFLATED) as zipf:
                flow_json_str = json.dumps(self.current_flow_data, ensure_ascii=False, indent=2)
                flow_arcname = '%s/flow.json' % flow_id
                zipf.writestr(flow_arcname, flow_json_str)
                
                screenshots_data = {
                    'screenshots': []
                }
                screenshots_str = json.dumps(screenshots_data, ensure_ascii=False, indent=2)
                screenshots_arcname = '%s/screenshots.json' % flow_id
                zipf.writestr(screenshots_arcname, screenshots_str)
            
            zip_buffer.seek(0)
            zip_data = zip_buffer.read()
            
            with open(filepath, 'wb') as f:
                f.write(zip_data)
            
            self.status_icon.setText('💾')
            self.status_text.setText('导出成功！')
            self.status_detail.setText(os.path.basename(filepath))
            
            QMessageBox.information(
                self, '导出成功',
                'DMF 文件已成功导出！\n\n文件：%s\n\n可以直接导入到灵枢中使用。' % filepath
            )
            
        except Exception as e:
            self.status_icon.setText('❌')
            self.status_text.setText('导出失败')
            self.status_detail.setText(str(e)[:50])
            QMessageBox.critical(self, '错误', '导出失败：%s' % str(e))
    
    def export_bloody(self):
        if not hasattr(self, 'bloody_script_content') or not self.bloody_script_content:
            return
        
        try:
            default_name = '%s_血手脚本.amc2' % self.flow_name
            filepath, _ = QFileDialog.getSaveFileName(
                self, '导出血手宝典脚本', default_name,
                '血手宝典脚本 (*.amc2);;所有文件 (*.*)'
            )
            if not filepath:
                return
            
            if not filepath.lower().endswith('.amc2'):
                filepath += '.amc2'
            
            with open(filepath, 'w', encoding='gbk', errors='replace') as f:
                f.write(self.bloody_script_content)
            
            self.status_icon.setText('📄')
            self.status_text.setText('导出成功！')
            self.status_detail.setText(os.path.basename(filepath))
            
            skipped_info = ''
            if hasattr(self, 'skipped_tasks') and self.skipped_tasks:
                skipped_summary = {}
                for task in self.skipped_tasks:
                    reason = task.get('reason', '未知')
                    skipped_summary[reason] = skipped_summary.get(reason, 0) + 1
                
                skipped_lines = ['\n⚠️  以下功能血手不支持，已转为注释：']
                for reason, count in skipped_summary.items():
                    skipped_lines.append(f'   - {reason}: {count} 个')
                skipped_info = '\n'.join(skipped_lines)
            
            QMessageBox.information(
                self, '导出成功',
                '血手宝典脚本已成功导出为AMC2格式！\n\n文件：%s\n\n可以直接导入到血手宝典中使用。%s' % (filepath, skipped_info)
            )
            
        except Exception as e:
            self.status_icon.setText('❌')
            self.status_text.setText('导出失败')
            self.status_detail.setText(str(e)[:50])
            QMessageBox.critical(self, '错误', '导出失败：%s' % str(e))
    
    def export_km(self):
        if not hasattr(self, 'km_script_content') or not self.km_script_content:
            return
        
        try:
            default_name = '%s_魔盒脚本.km' % self.flow_name
            filepath, _ = QFileDialog.getSaveFileName(
                self, '导出魔盒KM脚本', default_name,
                '魔盒脚本 (*.km);;所有文件 (*.*)'
            )
            if not filepath:
                return
            
            if not filepath.lower().endswith('.km'):
                filepath += '.km'
            
            # 用GBK编码+二进制模式写入，确保CRLF换行符不被转换
            km_bytes = self.km_script_content.encode('gbk', errors='replace')
            with open(filepath, 'wb') as f:
                f.write(km_bytes)
            
            self.status_icon.setText('📄')
            self.status_text.setText('导出成功！')
            self.status_detail.setText(os.path.basename(filepath))
            
            skipped_info = ''
            if hasattr(self, 'skipped_tasks') and self.skipped_tasks:
                skipped_summary = {}
                for task in self.skipped_tasks:
                    reason = task.get('reason', '未知')
                    skipped_summary[reason] = skipped_summary.get(reason, 0) + 1
                
                skipped_lines = ['\n⚠️  以下功能魔盒不支持，已转为注释：']
                for reason, count in skipped_summary.items():
                    skipped_lines.append(f'   - {reason}: {count} 个')
                skipped_info = '\n'.join(skipped_lines)
            
            # 自动打开导出的文件
            try:
                import subprocess
                if sys.platform == 'win32':
                    os.startfile(filepath)
                else:
                    subprocess.Popen(['open', filepath] if sys.platform == 'darwin' else ['xdg-open', filepath])
            except Exception:
                pass
            
            QMessageBox.information(
                self, '导出成功',
                '魔盒脚本已成功导出为KM格式并自动打开！\n\n文件：%s\n\n可以直接导入到魔盒中使用。%s' % (filepath, skipped_info)
            )
            
        except Exception as e:
            self.status_icon.setText('❌')
            self.status_text.setText('导出失败')
            self.status_detail.setText(str(e)[:50])
            QMessageBox.critical(self, '错误', '导出失败：%s' % str(e))


