# 魔盒KM脚本 -> 灵枢DMF 转换器
# ============================================================

class KMScriptParser:
    def __init__(self):
        self.script_lines = []
        self.subs = {}
        self.main_lines = []
        self.screen_x = 1920
        self.screen_y = 1080
        self.times = 1
    
    def parse_file(self, filepath):
        content = None
        for enc in ['gbk', 'utf-8', 'utf-16', 'latin1']:
            try:
                with open(filepath, 'r', encoding=enc) as f:
                    content = f.read()
                break
            except (UnicodeDecodeError, LookupError):
                continue
        
        if content is None:
            with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
                content = f.read()
        
        return self.parse_content(content)
    
    def parse_content(self, content):
        lines = content.split('\n')
        current_section = None
        current_sub_name = None
        current_sub_lines = []
        main_lines = []
        
        for line in lines:
            stripped = line.strip()
            
            if stripped.startswith('[General]'):
                current_section = 'general'
                continue
            elif stripped.startswith('[Script]'):
                current_section = 'script'
                continue
            
            if current_section == 'general':
                if '=' in stripped:
                    key, val = stripped.split('=', 1)
                    key = key.strip()
                    val = val.strip()
                    if key == 'ScreenX':
                        self.screen_x = int(val)
                    elif key == 'ScreenY':
                        self.screen_y = int(val)
                    elif key == 'Times':
                        self.times = int(val)
                continue
            
            if current_section != 'script':
                continue
            
            if stripped.lower().startswith('sub '):
                if current_sub_name:
                    self.subs[current_sub_name] = current_sub_lines
                current_sub_name = stripped[4:].strip()
                current_sub_lines = []
                continue
            
            if stripped.lower() == 'endsub':
                if current_sub_name:
                    self.subs[current_sub_name] = current_sub_lines
                current_sub_name = None
                current_sub_lines = []
                continue
            
            if current_sub_name:
                current_sub_lines.append(stripped)
            else:
                main_lines.append(stripped)
        
        self.main_lines = main_lines
        return {
            'screen_x': self.screen_x,
            'screen_y': self.screen_y,
            'times': self.times,
            'main_lines': main_lines,
            'subs': self.subs
        }


class KMToDMFConverter:
    KEY_MAP = {
        'enter': 'Enter', 'return': 'Enter',
        'esc': 'Esc', 'escape': 'Esc',
        'space': 'Space',
        'tab': 'Tab',
        'backspace': 'Backspace',
        'up': 'Up', 'down': 'Down', 'left': 'Left', 'right': 'Right',
        'insert': 'Insert', 'delete': 'Delete',
        'home': 'Home', 'end': 'End',
        'pageup': 'PageUp', 'pagedown': 'PageDown',
        'capslock': 'CapsLock', 'numlock': 'NumLock',
        'scrolllock': 'ScrollLock', 'printscreen': 'PrintScreen',
        'pause': 'Pause',
        'ctrl': 'Ctrl', 'shift': 'Shift', 'alt': 'Alt',
        'ctrl_l': 'Ctrl', 'ctrl_r': 'Ctrl',
        'shift_l': 'Shift', 'shift_r': 'Shift',
        'alt_l': 'Alt', 'alt_r': 'Alt',
        'lbutton': 'Left', 'rbutton': 'Right', 'mbutton': 'Middle',
    }
    
    def __init__(self):
        self.var_map = {}
        self.skipped_tasks = []
    
    def _convert_key(self, key):
        key_lower = key.lower().strip()
        if key_lower in self.KEY_MAP:
            return self.KEY_MAP[key_lower]
        if len(key) == 1:
            return key.upper()
        for i in range(1, 13):
            if key_lower == 'f%d' % i:
                return 'F%d' % i
        for i in range(10):
            if key_lower == 'num%d' % i:
                return 'Num%d' % i
        return key
    
    def _split_cmd_and_comment(self, line):
        comment = ''
        cmd = line
        if '//' in line:
            idx = line.find('//')
            cmd = line[:idx].strip()
            comment = line[idx+2:].strip()
        return cmd, comment
    
    def _convert_color(self, color_str):
        color_str = color_str.strip().strip('"').strip("'")
        
        if color_str.startswith('#'):
            color_str = color_str[1:]
        
        if color_str.startswith('&H') or color_str.startswith('&h'):
            color_str = color_str[2:]
        
        if len(color_str) == 6:
            b = color_str[0:2]
            g = color_str[2:4]
            r = color_str[4:6]
            return '#%s%s%s' % (r.upper(), g.upper(), b.upper())
        
        return '#%s' % color_str.upper()
    
    def _parse_condition(self, condition_str):
        condition_str = condition_str.strip()
        
        op_map = {
            '>=': '大于等于',
            '<=': '小于等于',
            '==': '等于',
            '<>': '不等于',
            '!=': '不等于',
            '>':  '大于',
            '<':  '小于',
        }
        
        found_op = None
        for op in ['>=', '<=', '==', '<>', '!=', '>', '<']:
            if op in condition_str:
                found_op = op
                break
        
        if not found_op:
            return {
                'condition': condition_str,
                'variable_name': '',
                'compare': '等于',
                'compare_value': ''
            }
        
        parts = condition_str.split(found_op, 1)
        var_name = parts[0].strip()
        compare_value = parts[1].strip()
        
        return {
            'condition': '变量判断',
            'variable_name': var_name,
            'compare': op_map.get(found_op, '等于'),
            'compare_value': compare_value
        }
    
    def convert(self, km_data, macro_name='转换脚本'):
        main_lines = km_data.get('main_lines', [])
        subs = km_data.get('subs', {})
        
        tabs = []
        
        main_tasks = self._parse_lines(main_lines)
        tabs.append({
            'name': '主流程',
            'tasks': main_tasks
        })
        
        for sub_name, sub_lines in subs.items():
            sub_tasks = self._parse_lines(sub_lines)
            tabs.append({
                'name': sub_name,
                'tasks': sub_tasks
            })
        
        return {
            'name': macro_name,
            'description': '从魔盒KM脚本转换',
            'tabs': tabs
        }
    
    def _parse_lines(self, lines):
        tasks = []
        i = 0
        while i < len(lines):
            line = lines[i].strip()
            if not line or line.startswith('/////'):
                i += 1
                continue
            
            if line.lower().startswith('//'):
                text = line[2:].strip()
                if text:
                    tasks.append({'type': 'remark', 'config': {'text': text, 'remark': ''}, 'subtasks': []})
                i += 1
                continue
            
            if line.lower().startswith('moved '):
                rest = line[6:].strip()
                parts = rest.split(',')
                if len(parts) >= 2:
                    try:
                        x = int(parts[0].strip())
                        y = int(parts[1].strip())
                        comment = ''
                        if '//' in rest:
                            idx = rest.find('//')
                            comment = rest[idx+2:].strip()
                        task = {
                            'type': 'mouse_action',
                            'config': {
                                'task_name': '鼠标操作',
                                'action_type': 'none',
                                'move_type': 'absolute',
                                'x': x,
                                'y': y,
                                'duration': 50,
                                'interval': 50,
                                'move_delay': 0,
                                'scroll_delta': 120,
                                'remark': comment
                            },
                            'subtasks': []
                        }
                        tasks.append(task)
                    except ValueError:
                        pass
                i += 1
                continue
            
            if line.lower().startswith('mover '):
                rest = line[6:].strip()
                parts = rest.split(',')
                if len(parts) >= 2:
                    try:
                        dx = int(parts[0].strip())
                        dy = int(parts[1].strip())
                        comment = ''
                        if '//' in rest:
                            idx = rest.find('//')
                            comment = rest[idx+2:].strip()
                        task = {
                            'type': 'mouse_action',
                            'config': {
                                'task_name': '鼠标操作',
                                'action_type': 'none',
                                'move_type': 'relative',
                                'x': dx,
                                'y': dy,
                                'duration': 50,
                                'interval': 50,
                                'move_delay': 0,
                                'scroll_delta': 120,
                                'remark': comment
                            },
                            'subtasks': []
                        }
                        tasks.append(task)
                    except ValueError:
                        pass
                i += 1
                continue
            
            cmd, comment = self._split_cmd_and_comment(line)
            cmd_lower = cmd.lower()
            
            if cmd_lower == 'leftdown':
                task = {
                    'type': 'mouse_action',
                    'config': {
                        'task_name': '鼠标操作',
                        'action_type': 'left_down',
                        'move_type': 'current',
                        'x': 0,
                        'y': 0,
                        'duration': 50,
                        'interval': 50,
                        'move_delay': 0,
                        'scroll_delta': 120,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower == 'leftup':
                task = {
                    'type': 'mouse_action',
                    'config': {
                        'task_name': '鼠标操作',
                        'action_type': 'left_up',
                        'move_type': 'current',
                        'x': 0,
                        'y': 0,
                        'duration': 50,
                        'interval': 50,
                        'move_delay': 0,
                        'scroll_delta': 120,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower == 'rightdown':
                task = {
                    'type': 'mouse_action',
                    'config': {
                        'task_name': '鼠标操作',
                        'action_type': 'right_down',
                        'move_type': 'current',
                        'x': 0,
                        'y': 0,
                        'duration': 50,
                        'interval': 50,
                        'move_delay': 0,
                        'scroll_delta': 120,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower == 'rightup':
                task = {
                    'type': 'mouse_action',
                    'config': {
                        'task_name': '鼠标操作',
                        'action_type': 'right_up',
                        'move_type': 'current',
                        'x': 0,
                        'y': 0,
                        'duration': 50,
                        'interval': 50,
                        'move_delay': 0,
                        'scroll_delta': 120,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('delay '):
                rest = cmd[6:].strip()
                try:
                    ms = int(rest.split()[0].strip())
                    task = {
                        'type': 'delay',
                        'config': {
                            'type': 'fixed',
                            'value': ms,
                            'random_min': 500,
                            'random_max': 1500,
                            'remark': comment
                        },
                        'subtasks': []
                    }
                    tasks.append(task)
                except ValueError:
                    pass
                i += 1
                continue
            
            if cmd_lower.startswith('delayrandom '):
                rest = cmd[12:].strip()
                parts = rest.split(',')
                if len(parts) >= 2:
                    try:
                        min_ms = int(parts[0].strip())
                        max_ms = int(parts[1].strip())
                        avg_ms = (min_ms + max_ms) // 2
                        task = {
                            'type': 'delay',
                            'config': {
                                'type': 'fixed',
                                'value': avg_ms,
                                'random_min': min_ms,
                                'random_max': max_ms,
                                'remark': comment
                            },
                            'subtasks': []
                        }
                        tasks.append(task)
                    except ValueError:
                        pass
                i += 1
                continue
            
            if cmd_lower.startswith('keydown '):
                key = self._convert_key(cmd[8:].strip())
                task = {
                    'type': 'key',
                    'config': {
                        'key': key,
                        'action': 'press',
                        'duration': 100,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('keyup '):
                key = self._convert_key(cmd[6:].strip())
                task = {
                    'type': 'key',
                    'config': {
                        'key': key,
                        'action': 'release',
                        'duration': 50,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('rem '):
                mark_name = cmd[4:].strip()
                task = {
                    'type': 'set_mark',
                    'config': {
                        'mark_name': mark_name,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('goto '):
                mark_name = cmd[5:].strip()
                task = {
                    'type': 'goto_mark',
                    'config': {
                        'mark_name': mark_name,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('call '):
                sub_name = cmd[5:].strip()
                task = {
                    'type': 'subflow',
                    'config': {
                        'name': sub_name,
                        'threaded': False,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('for '):
                rest = cmd[4:].strip()
                try:
                    count = int(rest)
                except ValueError:
                    count = 1
                
                children, new_i = self._parse_block(lines, i + 1, 'next')
                task = {
                    'type': 'loop',
                    'config': {
                        'loop_type': '计次循环',
                        'loop_count': count,
                        'remark': comment
                    },
                    'subtasks': children
                }
                tasks.append(task)
                i = new_i + 1
                continue
            
            if cmd_lower.startswith('if ') and cmd_lower.endswith(' then'):
                condition = cmd[3:-5].strip()
                children, new_i = self._parse_block(lines, i + 1, 'end if')
                cond_config = self._parse_condition(condition)
                cond_config['task_name'] = '条件判断'
                cond_config['remark'] = comment
                task = {
                    'type': 'condition',
                    'config': cond_config,
                    'subtasks': children
                }
                tasks.append(task)
                i = new_i + 1
                continue
            
            if cmd_lower == 'break':
                task = {
                    'type': 'exit_loop',
                    'config': {},
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('findmulticolor '):
                rest = cmd[14:].strip()
                
                parts = self._parse_findmulticolor_args(rest)
                if parts:
                    x1 = parts.get('x1', 0)
                    y1 = parts.get('y1', 0)
                    x2 = parts.get('x2', 0)
                    y2 = parts.get('y2', 0)
                    similarity = parts.get('similarity', 0.9)
                    tolerance = int((1 - similarity) * 255)
                    cx = (x1 + x2) // 2
                    cy = (y1 + y2) // 2
                    var_x = parts.get('var_x', '')
                    var_y = parts.get('var_y', '')
                    var_name = var_x if var_x else '图色坐标'
                    
                    if var_x:
                        tasks.append({
                            'type': 'variable',
                            'config': {
                                'category': '全局变量',
                                'data_type': '整数类型',
                                'var_name': var_x,
                                'initial_value': '-1',
                                'value': -1
                            },
                            'subtasks': []
                        })
                        if var_y:
                            tasks.append({
                                'type': 'variable',
                                'config': {
                                    'category': '全局变量',
                                    'data_type': '整数类型',
                                    'var_name': var_y,
                                    'initial_value': '-1',
                                    'value': -1
                                },
                                'subtasks': []
                            })
                    
                    task = {
                        'type': 'color',
                        'config': {
                            'task_name': '图色查找',
                            'color_value': self._convert_color(parts.get('base_color', '')),
                            'tolerance': tolerance,
                            'x': cx,
                            'y': cy,
                            'width': x2 - x1,
                            'height': y2 - y1,
                            'offset_x': 0,
                            'offset_y': 0,
                            'click_action': '无操作',
                            'var_name': var_name,
                            'var_base': var_name,
                            'move_type': 'current',
                            'remark': comment
                        },
                        'subtasks': []
                    }
                    tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('dim '):
                vars_str = cmd[4:].strip()
                var_names = [v.strip() for v in vars_str.split(',') if v.strip()]
                for var_name in var_names:
                    task = {
                        'type': 'variable',
                        'config': {
                            'var_name': var_name,
                            'data_type': '整数类型',
                            'initial_value': '0',
                            'remark': comment
                        },
                        'subtasks': []
                    }
                    tasks.append(task)
                i += 1
                continue
            
            if cmd_lower == 'else':
                i += 1
                continue
            
            if cmd_lower == 'endscript':
                task = {
                    'type': 'terminate_program',
                    'config': {},
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower == 'exit for' or cmd_lower == 'exit do':
                task = {
                    'type': 'exit_loop',
                    'config': {},
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower == 'pause':
                task = {
                    'type': 'remark',
                    'config': {'text': 'Pause 暂停脚本', 'remark': comment},
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('keypress '):
                key = self._convert_key(cmd[9:].strip())
                task = {
                    'type': 'key',
                    'config': {
                        'key': key,
                        'action': 'click',
                        'duration': 100,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower == 'middledown':
                task = {
                    'type': 'mouse_action',
                    'config': {
                        'task_name': '鼠标操作',
                        'action_type': 'middle_down',
                        'move_type': 'current',
                        'x': 0, 'y': 0,
                        'duration': 50, 'interval': 50,
                        'move_delay': 0, 'scroll_delta': 120,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower == 'middleup':
                task = {
                    'type': 'mouse_action',
                    'config': {
                        'task_name': '鼠标操作',
                        'action_type': 'middle_up',
                        'move_type': 'current',
                        'x': 0, 'y': 0,
                        'duration': 50, 'interval': 50,
                        'move_delay': 0, 'scroll_delta': 120,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('findcolor ') or cmd_lower.startswith('findcolorex ') or cmd_lower.startswith('findcentercolor '):
                parts = self._parse_findcolor_args(cmd)
                if parts:
                    x1 = parts.get('x1', 0)
                    y1 = parts.get('y1', 0)
                    x2 = parts.get('x2', 0)
                    y2 = parts.get('y2', 0)
                    similarity = parts.get('similarity', 0.9)
                    tolerance = int((1 - similarity) * 255)
                    cx = (x1 + x2) // 2
                    cy = (y1 + y2) // 2
                    task = {
                        'type': 'color',
                        'config': {
                            'task_name': '图色查找',
                            'color_value': self._convert_color(parts.get('base_color', '')),
                            'tolerance': tolerance,
                            'x': cx,
                            'y': cy,
                            'width': x2 - x1,
                            'height': y2 - y1,
                            'offset_x': 0,
                            'offset_y': 0,
                            'click_action': '无操作',
                            'var_name': '',
                            'var_base': '图色坐标',
                            'move_type': 'current',
                            'remark': comment
                        },
                        'subtasks': []
                    }
                    tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('ifcolor '):
                condition = cmd[7:].strip()
                children, new_i = self._parse_block(lines, i + 1, 'end if')
                cond_config = {
                    'task_name': '条件判断',
                    'condition': '颜色判断',
                    'color_condition': condition,
                    'remark': comment
                }
                task = {
                    'type': 'condition',
                    'config': cond_config,
                    'subtasks': children
                }
                tasks.append(task)
                i = new_i + 1
                continue
            
            if cmd_lower.startswith('elseif ') and cmd_lower.endswith(' then'):
                i += 1
                continue
            
            if cmd_lower.startswith('while ') and cmd_lower.endswith(' then'):
                condition = cmd[6:-5].strip()
                children, new_i = self._parse_block(lines, i + 1, 'wend')
                task = {
                    'type': 'loop',
                    'config': {
                        'loop_type': '条件循环',
                        'loop_condition': condition,
                        'remark': comment
                    },
                    'subtasks': children
                }
                tasks.append(task)
                i = new_i + 1
                continue
            
            if cmd_lower == 'do':
                children, new_i = self._parse_block(lines, i + 1, 'loop')
                task = {
                    'type': 'loop',
                    'config': {
                        'loop_type': '条件循环',
                        'loop_condition': '',
                        'remark': comment
                    },
                    'subtasks': children
                }
                tasks.append(task)
                i = new_i + 1
                continue
            
            if cmd_lower.startswith('for ') and ' to ' in cmd_lower:
                match = re.match(r'for\s+(\w+)\s*=\s*(\d+)\s+to\s+(\d+)(?:\s+step\s+(\d+))?', cmd, re.IGNORECASE)
                if match:
                    var_name = match.group(1)
                    start_val = int(match.group(2))
                    end_val = int(match.group(3))
                    step = int(match.group(4)) if match.group(4) else 1
                    count = max(1, (end_val - start_val) // step + 1)
                    
                    children, new_i = self._parse_block(lines, i + 1, 'next')
                    task = {
                        'type': 'loop',
                        'config': {
                            'loop_type': '计次循环',
                            'loop_count': count,
                            'remark': comment
                        },
                        'subtasks': children
                    }
                    tasks.append(task)
                    i = new_i + 1
                    continue
            
            if cmd_lower.startswith('saystring '):
                text = cmd[10:].strip().strip('"')
                task = {
                    'type': 'sim_input',
                    'config': {
                        'text': text,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('saystringunicode '):
                text = cmd[16:].strip().strip('"')
                task = {
                    'type': 'sim_input',
                    'config': {
                        'text': text,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('msgbox ') or cmd_lower.startswith('traceprint '):
                text = cmd.split(' ', 1)[1].strip().strip('"') if ' ' in cmd else ''
                task = {
                    'type': 'remark',
                    'config': {'text': text, 'remark': comment},
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('runapp '):
                app_path = cmd[7:].strip().strip('"')
                task = {
                    'type': 'py_code',
                    'config': {
                        'code': 'import os; os.startfile(r\"%s\")' % app_path,
                        'remark': comment
                    },
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower.startswith('beep'):
                task = {
                    'type': 'remark',
                    'config': {'text': 'Beep 蜂鸣', 'remark': comment},
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            if cmd_lower in ('randomize', 'on_pause', 'resumescript', 'clearstack', 'freepic', 'capturemode', 'capturescreen', 'getscreenscale', 'setscreenscale'):
                i += 1
                continue
            
            if cmd_lower.startswith('get') or cmd_lower.startswith('findfile') or cmd_lower.startswith('getfileline') or cmd_lower.startswith('curl') or cmd_lower.startswith('waitkey') or cmd_lower.startswith('pressrandom'):
                task = {
                    'type': 'remark',
                    'config': {'text': cmd, 'remark': comment},
                    'subtasks': []
                }
                tasks.append(task)
                i += 1
                continue
            
            self.skipped_tasks.append({'line': line, 'reason': '不支持的指令'})
            i += 1
        
        return tasks
    
    def _parse_block(self, lines, start_i, end_keyword):
        children = []
        i = start_i
        end_lower = end_keyword.lower()
        while i < len(lines):
            line = lines[i].strip()
            if not line:
                i += 1
                continue
            
            cmd, comment = self._split_cmd_and_comment(line)
            cmd_lower = cmd.lower()
            
            if cmd_lower == end_lower:
                return children, i
            
            if cmd_lower.startswith('if ') and cmd_lower.endswith(' then'):
                condition = cmd[3:-5].strip()
                sub_children, new_i = self._parse_block(lines, i + 1, 'end if')
                cond_config = self._parse_condition(condition)
                cond_config['task_name'] = '条件判断'
                cond_config['remark'] = comment
                task = {
                    'type': 'condition',
                    'config': cond_config,
                    'subtasks': sub_children
                }
                children.append(task)
                i = new_i + 1
                continue
            
            if cmd_lower == 'else':
                i += 1
                continue
            
            if cmd_lower.startswith('for '):
                rest = cmd[4:].strip()
                try:
                    count = int(rest)
                except ValueError:
                    count = 1
                
                sub_children, new_i = self._parse_block(lines, i + 1, 'next')
                task = {
                    'type': 'loop',
                    'config': {
                        'loop_type': '计次循环',
                        'loop_count': count,
                        'remark': comment
                    },
                    'subtasks': sub_children
                }
                children.append(task)
                i = new_i + 1
                continue
            
            if cmd_lower == 'break':
                task = {
                    'type': 'exit_loop',
                    'config': {},
                    'subtasks': []
                }
                children.append(task)
                i += 1
                continue
            
            task_list = self._parse_lines([line])
            children.extend(task_list)
            i += 1
        
        return children, i - 1
    
    def _parse_findmulticolor_args(self, args_str):
        parts = []
        current = ''
        in_quotes = False
        
        for char in args_str:
            if char == '"':
                in_quotes = not in_quotes
                current += char
            elif char == ',' and not in_quotes:
                parts.append(current.strip())
                current = ''
            else:
                current += char
        
        if current.strip():
            parts.append(current.strip())
        
        if len(parts) < 6:
            return None
        
        try:
            x1 = int(parts[0].strip())
            y1 = int(parts[1].strip())
            x2 = int(parts[2].strip())
            y2 = int(parts[3].strip())
            base_color = parts[4].strip().strip('"')
            offset_colors = parts[5].strip().strip('"')
            similarity = 0.9
            if len(parts) >= 7:
                try:
                    similarity = float(parts[6].strip())
                except ValueError:
                    pass
            var_x = ''
            var_y = ''
            if len(parts) >= 10:
                var_x = parts[8].strip()
                var_y = parts[9].strip()
            elif len(parts) >= 9:
                var_x = parts[8].strip()
            
            return {
                'x1': x1,
                'y1': y1,
                'x2': x2,
                'y2': y2,
                'base_color': base_color,
                'offset_colors': offset_colors,
                'similarity': similarity,
                'var_x': var_x,
                'var_y': var_y
            }
        except ValueError:
            return None
    
    def _parse_findcolor_args(self, cmd):
        rest = cmd.split(' ', 1)[1].strip() if ' ' in cmd else ''
        
        parts = []
        current = ''
        in_quotes = False
        for char in rest:
            if char == '"':
                in_quotes = not in_quotes
                current += char
            elif char == ',' and not in_quotes:
                parts.append(current.strip())
                current = ''
            else:
                current += char
        if current.strip():
            parts.append(current.strip())
        
        if len(parts) < 5:
            return None
        
        try:
            x1 = int(parts[0].strip())
            y1 = int(parts[1].strip())
            x2 = int(parts[2].strip())
            y2 = int(parts[3].strip())
            base_color = parts[4].strip().strip('"')
            similarity = 0.9
            if len(parts) >= 6:
                try:
                    similarity = float(parts[5].strip())
                except ValueError:
                    pass
            
            return {
                'x1': x1, 'y1': y1,
                'x2': x2, 'y2': y2,
                'base_color': base_color,
                'similarity': similarity
            }
        except ValueError:
            return None


def _converter_main():
    app = QApplication(sys.argv)
    app.setStyle('Fusion')
    
    window = ConverterMainWindow()
    window.show()
    
    sys.exit(app.exec())

