def cleanup_old_logs(days_to_keep=7):
    """清理指定天数之前的日志文件"""
    try:
        log_dir = os.path.join(BASE_DATA_DIR, "logs")
        if not os.path.exists(log_dir):
            return
        
        now = time.time()
        cutoff_time = now - (days_to_keep * 24 * 60 * 60)
        
        for filename in os.listdir(log_dir):
            if filename.startswith("verify_") and filename.endswith(".log"):
                file_path = os.path.join(log_dir, filename)
                try:
                    file_mtime = os.path.getmtime(file_path)
                    if file_mtime < cutoff_time:
                        os.remove(file_path)
                except:
                    pass
    except:
        pass


# 程序入口
if __name__ == "__main__":
    # 【关键修复】最早位置处理子进程模式，避免 multiprocessing.freeze_support()
    # 及后续主程序代码执行，彻底杜绝子进程链式复制。
    # 必须在 freeze_support() 之前，因为 freeze_support() 在某些 PyInstaller 环境下
    # 可能有副作用，且 worker 不需要 multiprocessing 支持。

    # ---- 子进程 kmbox worker 模式：--kmbox-worker ----
    # 常驻子进程，通过 stdin/stdout(JSON) 接收 kmNet 调用指令并执行
    # 注意：打包环境下不再使用此子进程模式，改为主进程内直接调用 kmNet
    # 此分支仅作为非打包环境的兼容保留
    if len(sys.argv) >= 2 and sys.argv[1] == '--kmbox-worker':
        import json, traceback
        try:
            import kmNet
            kmNet_available = True
        except ImportError:
            kmNet_available = False

        def write_result(result):
            try:
                sys.stdout.write(json.dumps(result) + '\n')
                sys.stdout.flush()
            except Exception:
                pass

        while True:
            try:
                line = sys.stdin.readline()
                if not line:
                    break
                cmd = json.loads(line.strip())
                action = cmd.get('action')
                if action == 'exit':
                    write_result({'ok': True})
                    break
                if not kmNet_available:
                    write_result({'ok': False, 'error': 'kmNet not available'})
                    continue
                func_name = cmd.get('func')
                args = cmd.get('args', [])

                func = getattr(kmNet, func_name, None)
                if func is None:
                    write_result({'ok': False, 'error': 'function not found: ' + str(func_name)})
                    continue
                ret = func(*args)
                write_result({'ok': True, 'ret': ret})
            except Exception as e:
                try:
                    write_result({'ok': False, 'error': str(e), 'tb': traceback.format_exc()})
                except Exception:
                    pass
        # 使用 os._exit(0) 而非 sys.exit(0)，确保子进程立即退出
        os._exit(0)

    # ---- 子进程测试 kmbox 初始化模式：--kmbox-test-init ip port uuid [result_file] ----
    # 打包后通过 subprocess 调用主程序自身来测试 kmNet.init，避免 GIL 阻塞
    # windowed 程序 sys.stdout 为 NullWriter，print 不可靠，结果写入 result_file 回传
    if len(sys.argv) >= 5 and sys.argv[1] == '--kmbox-test-init':
        ip = sys.argv[2]
        port = sys.argv[3]
        uuid = sys.argv[4]
        result_file = sys.argv[5] if len(sys.argv) >= 6 else None
        ret_line = None
        try:
            import kmNet
            ret = kmNet.init(ip, port, uuid)
            ret_line = f'RET:{ret}'
        except Exception as e:
            ret_line = f'EXC:{e}'
        if result_file:
            try:
                with open(result_file, 'w', encoding='utf-8') as _f:
                    _f.write(ret_line)
            except Exception:
                pass
        try:
            print(ret_line)
        except Exception:
            pass
        # 使用 os._exit(0) 防止子进程继续执行
        os._exit(0)

    # ---- 主进程代码 ----
    import multiprocessing
    multiprocessing.freeze_support()
    
    # ========== 单实例锁：防止多开 ==========
    # 用全局命名互斥体检测是否已有实例在运行，有则提示并退出本次启动。
    # 用互斥体(而非锁文件)：进程异常退出/强杀时内核会自动释放句柄，不会残留卡死。
    try:
        import ctypes as _ct
        from ctypes import wintypes as _wt
        _s_kernel32 = _ct.WinDLL('kernel32', use_last_error=True)
        _s_kernel32.CreateMutexW.restype = _wt.HANDLE
        _s_kernel32.CreateMutexW.argtypes = [_wt.LPVOID, _wt.BOOL, _wt.LPCWSTR]
        _SINGLE_INSTANCE_MUTEX = _s_kernel32.CreateMutexW(None, False, "LingHub_SingleInstance_2c7f1e9a")
        if _SINGLE_INSTANCE_MUTEX and _ct.get_last_error() == 183:  # ERROR_ALREADY_EXISTS
            try:
                _s_user32 = _ct.WinDLL('user32', use_last_error=True)
                _s_user32.MessageBoxW.argtypes = [_wt.HWND, _wt.LPCWSTR, _wt.LPCWSTR, _wt.UINT]
                _s_user32.MessageBoxW.restype = _wt.INT
                _s_user32.MessageBoxW(None, "灵枢已经在运行，请勿重复打开。", "提示", 0x40)
            except Exception:
                pass
            os._exit(0)
    except Exception:
        pass
    
    # 清理旧日志文件
